  1	package net.officefloor.hq.app.person;
  2	
  3	/** A person on a sheet. Mutable so an Apply step can change it in place. */
  4	import java.math.BigDecimal;
  5	import java.time.LocalDate;
  6	import net.officefloor.hq.app.claim.Claim;
  7	import net.officefloor.hq.app.claim.ClaimStatus;
  8	
  9	public class Person {
 10	
 11	    /** The from-date standing for the beginning of time (stored as a null from-date). */
 12	    public static final LocalDate BEGINNING = LocalDate.MIN;
 13	
 14	    private final long id;
 15	    private final String sheetId;
 16	    private String name;
 17	    /** The person's grades by the date each is in force from; {@link #BEGINNING} is the beginning of time. */
 18	    private final java.util.TreeMap<LocalDate, String> grades = new java.util.TreeMap<>();
 19	    /** The sheet's today when the person was loaded: the grade in force on it is the one shown. */
 20	    private LocalDate today;
 21	    /** A grade recorded by this edit and not yet written: its from-date and grade. */
 22	    private java.util.Map.Entry<LocalDate, String> recorded;
 23	    private int version;
 24	    /** The person's own terms in days; null when they have none (their grade's or the sheet's apply). */
 25	    private Integer terms;
 26	    /** Whether this edit changed the person's terms from those loaded. */
 27	    private boolean termsChanged;
 28	    private int statementCount;
 29	    private BigDecimal statedTotal;
 30	    private LocalDate statementDate;
 31	    private LocalDate retiredFrom;
 32	    /** The person's holds, in the order they were added. */
 33	    private java.util.List<Hold> holds = new java.util.ArrayList<>();
 34	    private java.util.List<Long> patronIds = new java.util.ArrayList<>();
 35	    private java.util.List<String> patronNames = new java.util.ArrayList<>();
 36	    /** The person's aliases, sorted as names are compared. */
 37	    private java.util.List<String> aliases = new java.util.ArrayList<>();
 38	    /** Whether the person's name or an alias is used by someone else on a sheet of the sheet's tree. */
 39	    private boolean clashing;
 40	
 41	    public Person(long id, String sheetId, String name, String grade) {
 42	        this(id, sheetId, name, grade, 0);
 43	    }
 44	
 45	    public Person(long id, String sheetId, String name, String grade, int version) {
 46	        this.id = id;
 47	        this.sheetId = sheetId;
 48	        this.name = name;
 49	        this.grades.put(BEGINNING, grade);
 50	        this.version = version;
 51	    }
 52	
 53	    public long getId() { return id; }
 54	    public String getSheetId() { return sheetId; }
 55	    public String getName() { return name; }
 56	    /** The grade in force on the sheet's today. */
 57	    public String getGrade() { return gradeOn(today); }
 58	    /** The grade in force on a date: the one with the latest from-date on or before it; with no date, the first. */
 59	    public String gradeOn(LocalDate date) {
 60	        java.util.Map.Entry<LocalDate, String> found = date == null ? null : grades.floorEntry(date);
 61	        return found == null ? grades.firstEntry().getValue() : found.getValue();
 62	    }
 63	    /** The person's grades by from-date ({@link #BEGINNING} for the first), earliest first. */
 64	    public java.util.SortedMap<LocalDate, String> getGrades() { return java.util.Collections.unmodifiableSortedMap(grades); }
 65	    public void setGrades(java.util.Map<LocalDate, String> loaded) {
 66	        if (!loaded.isEmpty()) {
 67	            grades.clear();
 68	            grades.putAll(loaded);
 69	        }
 70	    }
 71	    /** Records the grade from the date (replacing one recorded from that same date), to be written on save. */
 72	    public void recordGrade(LocalDate from, String grade) {
 73	        grades.put(from, grade);
 74	        recorded = java.util.Map.entry(from, grade);
 75	    }
 76	    /** The grade this edit recorded and has not written yet; null when none. */
 77	    public java.util.Map.Entry<LocalDate, String> getRecordedGrade() { return recorded; }
 78	    public void clearRecordedGrade() { recorded = null; }
 79	    public LocalDate getToday() { return today; }
 80	    public void setToday(LocalDate today) { this.today = today; }
 81	    public int getVersion() { return version; }
 82	    /** The person's own terms in days; null when none. */
 83	    public Integer getTerms() { return terms; }
 84	    public void setTerms(Integer terms) { this.terms = terms; }
 85	    /** Sets the terms the form gave, noting whether they differ from those the person had (a save giving the
 86	     *  terms they already had changes nothing, even while dated terms are in force on the sheet's today — except a
 87	     *  save giving none while dated terms are in force, which counts as a change of the terms shown). */
 88	    public void editTerms(Integer terms) {
 89	        termsChanged = !java.util.Objects.equals(this.terms, terms) || (terms == null && termsOn(today) != null);
 90	        this.terms = terms;
 91	    }
 92	    public boolean isTermsChanged() { return termsChanged; }
