2	import { lateFrom } from '../claims/overdue';
3	import type { Grace } from '../claims/useGrace';
4	
5	// Due is worked in exact integers: an amount in cents times a rate in hundredths of a percent is
6	// due in millionths, then rounded to cents — by the sheet's rounding mode in force on the claim's date, else half up
7	// for a claim dated before the sheet's policy date, half to even for one dated on or after it. No float ever touches it.
8	
9	export const NA = 'n/a';
10	
11	/** "10.25" -> 1025n. */
12	export function toCents(amount: string): bigint {
13	  const negative = amount.trim().startsWith('-');
14	  const [whole, frac = ''] = amount.trim().replace(/^[-+]/, '').split('.');
15	  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
16	  return negative ? -cents : cents;
17	}
18	
19	/** 1025n -> "10.25". */
20	export function formatCents(cents: bigint): string {
21	  const negative = cents < 0n;
22	  const abs = negative ? -cents : cents;
23	  const frac = (abs % 100n).toString().padStart(2, '0');
24	  return `${negative ? '-' : ''}${abs / 100n}.${frac}`;
25	}
26	
27	/** The due on an amount of cents at a rate ("12.50"), in cents, rounded half up or else half to
28	 *  even; null when there is no rate. */
29	export function dueCents(cents: bigint, rate: string | undefined, halfUp = false): bigint | null {
30	  if (rate === undefined) return null;
31	  const millionths = cents * toCents(rate);
32	  const negative = millionths < 0n;
33	  const abs = negative ? -millionths : millionths;
34	  const whole = abs / 10000n;
35	  const rest = abs % 10000n;
36	  const rounded = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
37	  return negative ? -rounded : rounded;
38	}
39	
40	/** A due for display: two decimals, or n/a. */
41	export function showDue(due: bigint | null): string {
42	  return due === null ? NA : formatCents(due);
43	}
44	
45	/** A live due raised to a floor ("1.00"); n/a stays n/a. */
46	export function floored(due: bigint | null, floor: string): bigint | null {
47	  if (due === null) return null;
48	  const min = toCents(floor);
49	  return due < min ? min : due;
50	}
51	
52	/** The value of a dated setting in force on a date (a claim's: its date), e.g. "1.00". */
53	export type On = (date: string) => string;
54	
55	/** What a late charge needs: the sheet's late percent in force on a date (a boundary's, "10.00"), its today and each
56	 *  claim's grace days (none when left out). */
57	export type Late = { pct: On; today: string | undefined; grace?: Grace };
58	
59	const DAY_MS = 86_400_000;
60	
61	/** How the sheet's claims round: its policy date (blank: the sheet's today; undefined while loading) and every
62	 *  rounding mode recorded (half-up, half-even; "" for none), oldest from-date first. */
63	export type Policy = { date: string | undefined; rounding: { from: string; value: string }[] };
64	
65	/** Whether a claim's live figures round half up: by the rounding mode in force on its rounding date (a correction's is
66	 *  the date of the claim it corrects) when one is, else when that date is before the sheet's policy date. */
67	export function roundsHalfUp(claim: { roundingDate?: string; date: string }, policy: Policy | undefined): boolean {
68	  const on = claim.roundingDate || claim.date;
69	  const mode = (policy?.rounding ?? []).filter((d) => d.from <= on).pop()?.value ?? '';
70	  if (mode !== '') return mode === 'half-up';
71	  return policy?.date !== undefined && policy.date !== '' && on < policy.date;
72	}
73	
74	/** A claim with a negative amount is a correction: its due has no floor and no late charge. */
75	export const isCorrection = (claim: { amount?: string }) => claim.amount !== undefined && toCents(claim.amount) < 0n;
76	
77	/** The late charge on a figure in cents: an OPEN (or PENDING) claim whose due-by (fixed when it was created) is
78	 *  before today (and that is not deferred) gains, for each full 30 days it is overdue, the late percent in force on that
79	 *  boundary date (its due-by plus its grace days plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries
80	 *  before it (compounding), each rounded like due, the charges added up. A statement binds it into the due it binds; settling freezes it into the settled due.
81	 *  A claim whose late charge a steward waived gains none, whatever its overdue state. */
82	export function lateCents(claim: { amount?: string; date: string; status?: string; roundingDate?: string; dueBy?: string; deferredUntil?: string; stated?: boolean; personId?: string; waived?: boolean }, figure: bigint, late: Late | undefined, policy?: Policy): bigint {
83	  if (late === undefined || late.today === undefined || !claim.dueBy || claim.waived || !isOpen(claim) || isDeferred(claim, late.today) || isCorrection(claim)) return 0n;
84	  const from = lateFrom(claim, late.grace);
85	  const days = Math.round((Date.parse(late.today) - Date.parse(from)) / DAY_MS);
86	  const periods = days > 0 ? Math.floor(days / 30) : 0;
87	  const halfUp = roundsHalfUp(claim, policy);
88	  let charge = 0n;
89	  for (let n = 1; n <= periods; n++) {
90	    const boundary = new Date(Date.parse(from) + n * 30 * DAY_MS).toISOString().slice(0, 10);
91	    charge += dueCents(figure + charge, late.pct(boundary), halfUp) ?? 0n;
92	  }
93	  return charge;
94	}
95	
96	/** A claim's due: the one fixed when it was settled, frozen as it is; else the due a statement bound it to, as it was shown
97	 *  then (late charge and floor included; a claim bound to n/a stays n/a); else its amount at the current rate, raised first to the floor in force on its
98	 *  date, with an overdue claim's late charge (each 30-day boundary at the late percent in force on it) worked on that
99	 *  floored figure and added on top. A correction is never floored and gains no late charge. Live
100	 *  figures round by the sheet's rounding mode or policy date (see roundsHalfUp). */
101	export function claimDue(
102	  claim: { amount: string; due: string; date: string; status?: string; stated?: boolean; roundingDate?: string; dueBy?: string; deferredUntil?: string; personId?: string; waived?: boolean },
103	  rate: string | undefined,
104	  floor: On,
105	  late?: Late,
106	  policy?: Policy,
107	): bigint | null {
108	  if (claim.due !== '' && (claim.status === 'SETTLED' || claim.stated)) return toCents(claim.due);
109	  const figure = claim.due !== '' ? toCents(claim.due) : claim.stated ? null : dueCents(toCents(claim.amount), rate, roundsHalfUp(claim, policy));
110	  if (figure === null) return null;
111	  const base = isCorrection(claim) ? figure : floored(figure, floor(claim.date))!;
112	  return base + lateCents(claim, base, late, policy);
113	}
114	
115	/** A person's due-total: the sum of the figures of their claims that count. With no rate for their
116	 *  grade today it is n/a, unless a claim keeps a figure (a settled one, or one worked at the grade
117	 *  in force on its date); then it is the sum of the figures there are. A claim whose figure is n/a
118	 *  adds nothing. */
119	export function dueTotal(
120	  claims: { amount: string; due: string; date: string; status?: string; stated?: boolean; roundingDate?: string; dueBy?: string; personId?: string; rateMark?: number }[],
121	  rateOf: (claim: { date: string; rateMark?: number }) => string | undefined,
122	  rateToday: string | undefined,
123	  floor: On,
124	  late?: Late,
125	  policy?: Policy,
126	): bigint | null {
127	  const figures = claims.map((c) => claimDue(c, rateOf(c), floor, late, policy));
128	  if (rateToday === undefined && figures.every((f) => f === null)) return null;
129	  return figures.reduce<bigint>((sum, f) => sum + (f ?? 0n), 0n);
130	}
