132	/** A due-total held to the sheet's cap ("" for none) less the person's cut total (not below 0.00): that when it is
133	 *  above it. n/a is not capped. */
134	export function capped(total: bigint | null, cap: string, cut: bigint = 0n): bigint | null {
135	  if (total === null || cap === '') return total;
136	  const room = toCents(cap) - cut;
137	  const max = room < 0n ? 0n : room;
138	  return total > max ? max : total;
139	}
140	
141	/** How far a due-total is above the sheet's cap less the person's cut total; 0 when it is not, or is n/a. */
142	export function excess(total: bigint | null, cap: string, cut: bigint = 0n): bigint {
143	  const held = capped(total, cap, cut);
144	  return total === null || held === null ? 0n : total - held;
145	}
