15	// The figures the people list, its totals, the summary and the header are all worked from, so
16	// every place that repeats a figure shows the same one.
17	export function useSheetFigures(sheet: string) {
18	  const people = usePeople(sheet);
19	  const claims = useClaims(sheet);
20	  const rates = useRates(sheet);
21	  const tags = useTags(sheet);
22	  const today = useSheetToday(sheet);
23	  const floor = useFloor(sheet);
24	  const grace = useGrace(sheet);
25	  const late = { pct: useLatePct(sheet), today, grace };
26	  const policy = usePolicy(sheet);
27	  const cap = useCap(sheet);
28	  const pools = usePools(sheet);
29	  const settings = useSettings(sheet);
30	  const reviewSla = settings?.reviewSla;
31	  const pendingSla = settings?.pendingSla;
32	  const byId = new Map(people.map((p) => [p.id, p]));
33	  const live = claims.filter((c) => {
34	    const person = byId.get(c.personId);
35	    return person !== undefined && countsLive(c, retiredOn(person, today), today);
36	  });
37	  // The claims that count toward claimed: a held claim does, as it does in every total.
38	  const claimedLive = claims.filter((c) => {
39	    const person = byId.get(c.personId);
40	    return person !== undefined && countsClaimed(c, retiredOn(person, today), today);
41	  });
42	  // A shared claim's parts: each holder's part is the claim's amount times their share over 100, times the rate of the
43	  // holder's own grade in force on the claim's date over 100, rounded like the claim (0.00 when that grade has no rate);
44	  // a settled claim's parts stay frozen at its settled due times the share over 100, rounded half to even. Each part is
45	  // taken from the claim's own person; only a counting claim with a figure has parts.
46	  const parts = live.flatMap((c) => {
47	    const owner = byId.get(c.personId)!;
48	    const due = (c.shares ?? []).length === 0 ? null : claimDue(c, claimRate(rates, gradeOn(owner, c.date), c), floor, late, policy);
49	    if (due === null) return [];
50	    const frozen = c.status === 'SETTLED' && c.due !== '';
51	    return (c.shares ?? [])
52	      .filter((h) => byId.has(h.personId))
53	      .flatMap((h) => {
54	        if (frozen) return [{ claim: c, ownerId: c.personId, holderId: h.personId, part: halfEvenDiv(due * toCents(h.share), 10000n) }];
55	        const rate = claimRate(rates, gradeOn(byId.get(h.personId)!, c.date), c);
56	        // A holder whose grade has no rate holds 0.00: it takes nothing and gives them no figure.
57	        if (rate === undefined) return [];
58	        const part = roundDiv(toCents(c.amount) * toCents(h.share) * toCents(rate), 100000000n, roundsHalfUp(c, policy));
59	        return [{ claim: c, ownerId: c.personId, holderId: h.personId, part }];
60	      });
61	  });
62	  // What a person's parts move: added for the parts they hold, taken off for the parts of their own claims.
63	  const partsOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
64	    parts.reduce(
65	      (sum, p) => (!which(p.claim) ? sum : sum + (p.holderId === person.id ? p.part : 0n) - (p.ownerId === person.id ? p.part : 0n)),
66	      0n,
67	    );
68	  // A claim is worked at the grade in force on its date; the row shows the one in force today.
69	  // The sum of a person's figures, before the cap, with their parts; holding a part is a figure.
70	  const uncappedOf = (person: Person) => {
71	    const own = dueTotal(
72	      live.filter((c) => c.personId === person.id),
73	      (c) => claimRate(rates, gradeOn(person, c.date), c),
74	      rateOn(rates, gradeOn(person, today), today),
75	      floor,
76	      late,
77	      policy,
78	    );
79	    if (own === null && !parts.some((p) => p.holderId === person.id)) return null;
80	    return (own ?? 0n) + partsOf(person, () => true);
81	  };
82	  // A person's cut total: their cuts in every pool added up.
83	  const cutOf = (personId: string) =>
84	    pools.reduce(
85	      (sum, pool) => pool.members.reduce((s, m) => (m.personId === personId && m.cut !== '' ? s + toCents(m.cut) : s), sum),
86	      0n,
87	    );
88	  // A person's due-total: at most their cap less their cut total, not below 0.00 (n/a is not capped);
89	  // everything that adds up due-totals uses it. Their excess is how far the sum of their figures is above that.
90	  // The cap is the one in force on the date of their latest claim that counts (the sheet's today when none does).
91	  const capOf = (person: Person) => {
92	    const latest = live.filter((c) => c.personId === person.id).reduce<string | undefined>((d, c) => (d === undefined || c.date > d ? c.date : d), undefined);
93	    const on = latest ?? today;
94	    return on === undefined ? '' : cap(on);
95	  };
96	  const totalOf = (person: Person) => capped(uncappedOf(person), capOf(person), cutOf(person.id));
97	  const excessOf = (person: Person) => excess(uncappedOf(person), capOf(person), cutOf(person.id));
98	  // A person's settled-total and open-total: the dues of their counting SETTLED claims (frozen
99	  // figures, corrections included), and of their counting OPEN and PENDING claims; n/a adds nothing.
100	  // Together they make the sum of their figures before the cap.
101	  const dueSumOf = (person: Person, which: (c: (typeof live)[number]) => boolean) =>
102	    live
103	      .filter((c) => c.personId === person.id && which(c))
104	      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
