106	  const settledOf = (c: (typeof live)[number]) => c.status === 'SETTLED';
107	  const settledTotalOf = (person: Person) => dueSumOf(person, settledOf) + partsOf(person, settledOf);
108	  const openTotalOf = (person: Person) => dueSumOf(person, isOpen) + partsOf(person, isOpen);
109	  // Each person's settled-total, open-total and cut total (always a figure), in list order.
110	  const settledFigures = people.map(settledTotalOf);
111	  const openFigures = people.map(openTotalOf);
112	  const cutFigures = people.map((p) => cutOf(p.id));
113	  // The sheet's settled-total, open-total and cut total: everyone's figure added up, trimmed.
