115	  const sheetOpenTotal = formatCents(trimmedSum(openFigures));
116	  const sheetCutTotal = formatCents(trimmedSum(cutFigures));
117	  const overdue = live.filter((c) => isOverdue(c, today, grace));
118	  const overdueSum = (cs: typeof overdue) =>
119	    cs.reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n);
120	  const overdueTotal = (cs: typeof overdue) => formatCents(overdueSum(cs));
121	  // A person's score: the dues of their counting SETTLED claims that correct nothing, over 100,
122	  // minus 5 for each of their overdue counting claims, rounded half to even to a whole number.
123	  const scoreOf = (person: Person) => {
124	    const overdueCount = BigInt(overdue.filter((c) => c.personId === person.id).length);
125	    const settled = dueSumOf(person, (c) => c.status === 'SETTLED' && !c.corrects);
126	    return halfEvenDiv(settled - overdueCount * 50000n, 10000n).toString();
127	  };
128	  // Each person's due-total, skipping n/a, and overdue-total (always a figure), in list order.
129	  const dueFigures = people.map(totalOf).filter((due): due is bigint => due !== null);
130	  const overdueFigures = people.map((p) => overdueSum(overdue.filter((c) => c.personId === p.id)));
131	  // The sheet's due-total and overdue-total: those figures added up, trimmed.
132	  const sheetDueTotal = formatCents(trimmedSum(dueFigures));
133	  const sheetOverdueTotal = formatCents(trimmedSum(overdueFigures));
134	  // Active: an OPEN or PENDING claim that counts, dated within the 30 days up to and including today.
135	  const activeFrom = today === undefined ? undefined : daysBefore(today, 29);
136	  const isActive = (person: Person) =>
137	    activeFrom !== undefined &&
138	    live.some((c) => c.personId === person.id && isOpen(c) && c.date >= activeFrom && c.date <= today!);
139	  // Settled: the sum of a person's SETTLED claims' frozen figures, dated within the 90 days up to and including today.
140	  const settledFrom = today === undefined ? undefined : daysBefore(today, 89);
141	  const recentSettledOf = (person: Person) =>
142	    settledFrom === undefined
143	      ? 0n
144	      : claims
145	          .filter((c) => c.personId === person.id && c.status === 'SETTLED' && c.date >= settledFrom && c.date <= today! && /^-?\d+\.\d{2}$/.test(c.due))
146	          .reduce((sum, c) => sum + toCents(c.due), 0n);
147	  // Aged: the dues of a person's OPEN and PENDING claims that count, split by the claim's age on
148	  // today (days from its date): 0 to 30, 31 to 60, 61 or more; a claim dated after today is 0 to 30.
149	  const agedOf = (person: Person) => {
150	    const buckets = [0n, 0n, 0n];
151	    if (today === undefined) return buckets;
152	    for (const c of live) {
153	      if (c.personId !== person.id || !isOpen(c)) continue;
154	      const age = daysBetween(c.date, today);
