157	    }
158	    return buckets;
159	  };
160	  // The sheet's aged buckets: the people's buckets added up, not trimmed.
161	  const sheetAged = people
162	    .map(agedOf)
163	    .reduce((sum, b) => sum.map((v, i) => v + b[i]), [0n, 0n, 0n])
164	    .map(formatCents);
165	  // Each tag ever used on the sheet with its due-total: the dues of the counting claims that carry it,
166	  // or whose person carries it, each claim once (a claim with two tags counts in both); n/a adds nothing.
167	  const tagTotals = tags.map((tag) => ({
168	    tag,
169	    total: formatCents(
170	      live
171	        .filter((c) => hasTag(c, tag) || hasTag(byId.get(c.personId)!, tag))
172	        .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n),
173	    ),
174	  }));
175	  const onSheet = new Set(people.map((p) => p.id));
176	  const sheetClaims = claims.filter((c) => onSheet.has(c.personId));
177	  // Each calendar month (yyyy-mm) any claim on the sheet is dated in, earliest first, with its
178	  // due-total: the dues of the counting claims dated in it; n/a adds nothing.
179	  const monthTotals = [...new Set(sheetClaims.map((c) => c.date.slice(0, 7)))].sort().map((month) => ({
180	    month,
181	    total: formatCents(
182	      live
183	        .filter((c) => c.date.slice(0, 7) === month)
184	        .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(byId.get(c.personId)!, c.date), c), floor, late, policy) ?? 0n), 0n),
185	    ),
186	  }));
187	  const statusCount = (s: (typeof STATUSES)[number]) => sheetClaims.filter((c) => c.status === s).length;
188	  // Review-late: REVIEW claims whose review day plus the sheet's review SLA is before the sheet's today.
189	  const reviewLateCount = sheetClaims.filter((c) => isReviewLate(c, today, reviewSla)).length;
190	  // Pending-late: PENDING claims whose pending day plus the sheet's pending SLA is before the sheet's today.
191	  const pendingLateCount = sheetClaims.filter((c) => isPendingLate(c, today, pendingSla)).length;
192	  const voidReasonCount = (reason: string) => sheetClaims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length;
193	  return { people, claims, rates, today, byId, live, claimedLive, cutOf, totalOf, excessOf, overdue, overdueTotal, dueFigures, overdueFigures, sheetDueTotal, sheetOverdueTotal, statusCount, reviewLateCount, pendingLateCount, voidReasonCount, isActive, recentSettledOf, agedOf, sheetAged, settledTotalOf, openTotalOf, scoreOf, sheetSettledTotal, sheetOpenTotal, sheetCutTotal, settledFigures, openFigures, cutFigures, tagTotals, monthTotals };
194	}
