196	// People's figures added up, leaving out the single highest and the single lowest when there are
197	// three or more.
198	export function trimmedSum(figures: bigint[]): bigint {
199	  const sum = figures.reduce((a, b) => a + b, 0n);
200	  if (figures.length < 3) return sum;
201	  const max = figures.reduce((a, b) => (b > a ? b : a));
202	  const min = figures.reduce((a, b) => (b < a ? b : a));
203	  return sum - max - min;
204	}
