206	// The ISO date `days` days before `date`.
207	function daysBefore(date: string, days: number): string {
208	  const d = new Date(`${date}T00:00:00Z`);
209	  d.setUTCDate(d.getUTCDate() - days);
210	  return d.toISOString().slice(0, 10);
211	}
212	
213	// The whole days from one ISO date to a later one (negative when it is earlier).
214	function daysBetween(from: string, to: string): number {
215	  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
216	}
217	
218	// n / d (d > 0) rounded half up (away from zero) or else half to even.
219	function roundDiv(n: bigint, d: bigint, halfUp: boolean): bigint {
220	  if (!halfUp) return halfEvenDiv(n, d);
221	  const abs = n < 0n ? -n : n;
222	  const q = (abs * 2n + d) / (2n * d);
223	  return n < 0n ? -q : q;
224	}
225	
226	// n / d (d > 0) rounded half to even.
227	function halfEvenDiv(n: bigint, d: bigint): bigint {
228	  let q = n / d;
229	  let r = n % d;
230	  if (r < 0n) {
231	    q -= 1n;
232	    r += d;
233	  }
234	  if (r * 2n > d || (r * 2n === d && q % 2n !== 0n)) q += 1n;
235	  return q;
236	}
