11	/** A person's due-total for a period: the dues as shown now, late charges included, of their claims whose due-by
12	 *  (as fixed at creation) falls in it that counted at the end of its last day (see countsAtEnd), leaving out their unbound OPEN claims once they are retired (a hold takes none out) (a claim whose due is n/a
13	 *  adds nothing); a closed or soft-closed period gives the figure fixed when it was closed (0.00 for a person added later). */
14	export function usePersonPeriodDueTotal(sheet: string): (period: Period, personId: string) => bigint {
15	  const periods = usePeriods(sheet);
16	  const people = usePeople(sheet);
17	  const claims = useClaims(sheet);
18	  const rates = useRates(sheet);
19	  const floor = useFloor(sheet);
20	  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet), grace: useGrace(sheet) };
21	  const policy = usePolicy(sheet);
22	  const personOf = new Map(people.map((p) => [p.id, p]));
23	  return (period: Period, personId: string) => {
24	    if (period.closed || period.softClosed) return toCents(period.closedPersonTotals[personId] ?? '0.00');
25	    const person = personOf.get(personId);
26	    if (!person) return 0n;
27	    return claims
28	      .filter((c) => c.personId === personId && countsAtEnd(c, period.to, retiredOn(person, late.today), late.today) && periodOf(periods, c.dueBy)?.name === period.name)
29	      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
30	  };
31	}
