33	/** A person's carried figure for a period: the dues as shown now, late charges included, of their claims whose due-by
34	 *  falls in a period ending before this one starts that counted at the end of this period's last day (see countsAtEnd)
35	 *  and were then still OPEN or PENDING by the status log, plus their opening balance for it; 0 when nothing is carried. A closed or soft-closed period
36	 *  gives the figure fixed when it was closed (0.00 for a person added later; worked as above for a close made before
37	 *  carried figures were kept). */
38	export function usePersonPeriodCarried(sheet: string): (period: Period, personId: string) => bigint {
39	  const periods = usePeriods(sheet);
40	  const people = usePeople(sheet);
41	  const claims = useClaims(sheet);
42	  const rates = useRates(sheet);
43	  const floor = useFloor(sheet);
44	  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet), grace: useGrace(sheet) };
45	  const policy = usePolicy(sheet);
46	  const openings = useOpenings(sheet);
47	  const personOf = new Map(people.map((p) => [p.id, p]));
48	  return (period: Period, personId: string) => {
49	    if (period.closed || period.softClosed) {
50	      const fixed = period.closedPersonCarried?.[personId];
51	      if (fixed !== undefined) return toCents(fixed);
52	      if (period.closedPersonTotals[personId] === undefined) return 0n;
53	    }
54	    const person = personOf.get(personId);
55	    if (!person) return 0n;
56	    const opening = openings
57	      .filter((o) => o.personId === personId && o.period === period.name)
58	      .reduce((sum, o) => sum + toCents(o.amount), 0n);
59	    return opening + claims
60	      .filter((c) => {
61	        if (c.personId !== personId) return false;
62	        const from = periodOf(periods, c.dueBy);
63	        if (!from || from.to >= period.from) return false;
64	        const then = statusAt(c, period.to);
65	        return (then === 'OPEN' || then === 'PENDING')
66	          && countsAtEnd(c, period.to, retiredOn(person, late.today), late.today);
67	      })
68	      .reduce((sum, c) => sum + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), 0n);
69	  };
70	}
