79	/** A period's classic due-total: the dues as shown now, late charges included, of every person's claims whose due-by
80	 *  falls in it, each counted by its status now (as the live totals count it) rather than its status at the period's
81	 *  end; a closed or soft-closed period gives the figure fixed when it was closed. */
82	export function useClassicPeriodDueTotal(sheet: string): (period: Period) => bigint {
83	  const periods = usePeriods(sheet);
84	  const people = usePeople(sheet);
85	  const claims = useClaims(sheet);
86	  const rates = useRates(sheet);
87	  const floor = useFloor(sheet);
88	  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet), grace: useGrace(sheet) };
89	  const policy = usePolicy(sheet);
90	  return (period: Period) => {
91	    if (period.closed || period.softClosed) return toCents(period.closedTotal || '0.00');
92	    return people.reduce((sum, person) => {
93	      const retired = retiredOn(person, late.today);
94	      return claims
95	        .filter((c) => c.personId === person.id && countsLive(c, retired, late.today) && periodOf(periods, c.dueBy)?.name === period.name)
96	        .reduce((s, c) => s + (claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late, policy) ?? 0n), sum);
97	    }, 0n);
98	  };
