 72	// How a figure is shown under a locale. A figure is any text that is wholly a number with two
 73	// decimals (an amount, a due figure, a total, a rate, a share, a cut). The app renders figures as
 74	// 1234.56 everywhere (they are also what exports and audit lines carry), so the locale is applied
 75	// once, at display: under 'de' every such text on screen is shown as 1.234,56. Entries are typed
 76	// with a dot regardless: inputs hold values, not text, and are never touched.
 77	
 78	const FIGURE = /^(-?)(\d+)\.(\d{2})$/;
 79	
 80	/** Text whose element is never a displayed figure: an <option>'s text is its value, a textarea's its content. */
 81	const SKIP = new Set(['OPTION', 'TEXTAREA', 'SCRIPT', 'STYLE']);
 82	
 83	export function showFigure(raw: string, locale: Locale): string {
 84	  const m = locale === 'de' ? FIGURE.exec(raw) : null;
 85	  if (!m) return raw;
 86	  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+$)/g, '.')},${m[3]}`;
 87	}
