 89	/** Shows every figure under `root` in the locale, now and as the screen changes, until the returned stop is called
 90	 *  (which puts every figure back as rendered). React writes a text node's value only when its own value changes,
 91	 *  so a node shown in the locale stays so until React writes a new value, which is then shown in turn. */
 92	export function showFiguresIn(root: Node, locale: Locale): () => void {
 93	  // What each changed node was rendered as, and what it is shown as.
 94	  const shown = new Map<Text, { raw: string; text: string }>();
 95	
 96	  const apply = (node: Text) => {
 97	    const was = shown.get(node);
 98	    if (was && node.nodeValue === was.text) return; // our own write
 99	    const raw = node.nodeValue ?? '';
100	    const parent = node.parentElement;
101	    // Only an element whose whole text is the figure: not a figure inside a sentence.
102	    const whole = parent !== null && !SKIP.has(parent.tagName) && parent.textContent === raw;
103	    const text = whole ? showFigure(raw, locale) : raw;
104	    if (text === raw) {
105	      shown.delete(node);
106	      return;
107	    }
108	    shown.set(node, { raw, text });
109	    node.nodeValue = text;
110	  };
111	  const applyAll = (under: Node) => {
112	    if (under.nodeType === Node.TEXT_NODE) {
113	      apply(under as Text);
114	      return;
115	    }
116	    const walker = document.createTreeWalker(under, NodeFilter.SHOW_TEXT);
117	    for (let n = walker.nextNode(); n; n = walker.nextNode()) apply(n as Text);
118	  };
119	
120	  if (locale === 'en') return () => {};
121	  applyAll(root);
122	  const observer = new MutationObserver((records) => {
123	    for (const r of records) {
124	      if (r.type === 'characterData') apply(r.target as Text);
125	      else r.addedNodes.forEach(applyAll);
126	    }
127	    for (const node of shown.keys()) if (!node.isConnected) shown.delete(node);
128	  });
129	  observer.observe(root, { subtree: true, childList: true, characterData: true });
130	  return () => {
131	    observer.disconnect();
132	    for (const [node, { raw, text }] of shown) if (node.nodeValue === text) node.nodeValue = raw;
133	    shown.clear();
134	  };
135	}
