232	/** The sheet's today as figures are shown on it (YYYY-MM-DD; the as-of date while one is set, else the preview date while
233	 *  one is set). Every date decision and default date on screen reads this — never `new Date()`. Undefined while loading. */
234	export function useSheetToday(sheet: string): string | undefined {
235	  const preview = usePreview();
