241	/** The sheet's today whatever the preview date (the as-of date while one is set): what changes, and the rules
242	 *  the server judges them by, go on. Undefined while loading. */
243	export function useRealSheetToday(sheet: string): string | undefined {
244	  const asOf = useAsOf();
245	  const { data } = useQuery({
246	    queryKey: sheetTodayKey(sheet, asOf),
247	    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
248	    enabled: sheet !== '',
249	  });
250	  return data?.today;
251	}
