55	    /** Fills in each person's holds, in the order they were added. */
56	    private List<Person> withHolds(String sheetId, List<Person> found) {
57	        if (found.isEmpty()) {
58	            return found;
59	        }
60	        java.util.Map<Long, java.util.List<Person.Hold>> holds = new java.util.HashMap<>();
61	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY seq", rs -> {
62	            java.sql.Date to = rs.getDate("to_date");
63	            holds.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>())
64	                    .add(new Person.Hold(rs.getDate("from_date").toLocalDate(), to == null ? null : to.toLocalDate()));
65	        }, sheetId);
66	        for (Person person : found) {
67	            person.setHolds(new java.util.ArrayList<>(holds.getOrDefault(person.getId(), List.of())));
68	        }
69	        java.util.Map<Long, java.util.List<Person.Retirement>> retirements = new java.util.HashMap<>();
70	        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ? ORDER BY seq", rs -> {
71	            retirements.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>())
72	                    .add(new Person.Retirement(rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate()));
73	        }, sheetId);
74	        for (Person person : found) {
75	            person.setRetirements(new java.util.ArrayList<>(retirements.getOrDefault(person.getId(), List.of())));
76	        }
77	        java.util.Map<Long, java.util.List<String>> snapshots = new java.util.HashMap<>();
78	        jdbc.query("SELECT person_id, set_on, due_total FROM person_snapshot WHERE sheet_id = ? ORDER BY seq", rs -> {
79	            snapshots.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>())
80	                    .add(rs.getDate("set_on").toLocalDate() + " " + rs.getString("due_total"));
81	        }, sheetId);
82	        for (Person person : found) {
83	            person.setSnapshots(new java.util.ArrayList<>(snapshots.getOrDefault(person.getId(), List.of())));
84	        }
85	        java.util.Map<Long, java.util.List<String>> statements = new java.util.HashMap<>();
86	        jdbc.query("SELECT person_id, statement_date, stated_total FROM person_statement WHERE sheet_id = ? AND NOT cancelled"
87	                + " ORDER BY set_on NULLS FIRST, seq", rs -> {
88	            statements.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>())
89	                    .add(Person.statementLine(rs.getDate("statement_date"), rs.getBigDecimal("stated_total")));
90	        }, sheetId);
91	        for (Person person : found) {
92	            person.setStatements(new java.util.ArrayList<>(statements.getOrDefault(person.getId(), List.of())));
93	        }
94	        return found;
95	    }
