104	    /** Fills in each person's dated grades and the sheet's today (the grade in force on it is shown). */
105	    private List<Person> withGrades(String sheetId, List<Person> found) {
106	        if (found.isEmpty()) {
107	            return found;
108	        }
109	        java.time.LocalDate today = sheets.today(sheetId);
110	        java.util.Map<Long, java.util.Map<java.time.LocalDate, String>> grades = new java.util.HashMap<>();
111	        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ? ORDER BY seq", rs -> {
112	            java.sql.Date from = rs.getDate("from_date");
113	            grades.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.HashMap<>())
114	                    .put(from == null ? Person.BEGINNING : from.toLocalDate(), rs.getString("grade"));
115	        }, sheetId);
116	        java.util.Map<Long, java.util.Map<java.time.LocalDate, Integer>> terms = new java.util.HashMap<>();
117	        jdbc.query("SELECT person_id, from_date, terms FROM person_terms WHERE sheet_id = ? ORDER BY seq", rs -> {
118	            int days = rs.getInt("terms");
119	            Integer value = rs.wasNull() ? null : days;
120	            terms.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.HashMap<>())
121	                    .put(rs.getDate("from_date").toLocalDate(), value);
122	        }, sheetId);
123	        withHolds(sheetId, found);
124	        for (Person person : found) {
125	            person.setGrades(grades.getOrDefault(person.getId(), java.util.Map.of()));
126	            person.setDatedTerms(terms.getOrDefault(person.getId(), java.util.Map.of()));
127	            person.setToday(today);
128	        }
129	        return found;
130	    }
