132	    /** Writes the grade the person's edit recorded, replacing any recorded from the same date. */
133	    private void writeRecordedGrade(Person person) {
134	        java.util.Map.Entry<java.time.LocalDate, String> recorded = person.getRecordedGrade();
135	        if (recorded == null) {
136	            return;
137	        }
138	        java.sql.Date from = recorded.getKey().equals(Person.BEGINNING) ? null : java.sql.Date.valueOf(recorded.getKey());
139	        if (from == null) {
140	            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NULL",
141	                    person.getSheetId(), person.getId());
142	        } else {
143	            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
144	                    person.getSheetId(), person.getId(), from);
145	        }
146	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
147	                person.getSheetId(), person.getId(), from, recorded.getValue());
148	        jdbc.update("INSERT INTO grade_history (sheet_id, person_id, set_on, from_date, grade) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)",
149	                person.getSheetId(), person.getId(), person.getSheetId(), from, recorded.getValue());
150	        person.clearRecordedGrade();
151	    }
