153	    /** Makes every grade record of the person on one grade the other grade, whatever its from-date (a retroactive
154	     *  grade merge), each recorded in the grade history as set on the sheet's today. */
155	    public void regrade(Person person, String from, String into) {
156	        java.util.List<java.time.LocalDate> dates = new java.util.ArrayList<>();
157	        person.getGrades().forEach((on, grade) -> {
158	            if (from.equals(grade)) dates.add(on);
159	        });
160	        for (java.time.LocalDate on : dates) {
161	            person.recordGrade(on, into);
162	            writeRecordedGrade(person);
163	        }
164	    }
