191	    /** Swaps the person's place with their neighbour's, above (up) or below; returns the person's new position in
192	     *  the list counting from 1, or 0 (nothing written) when they have no neighbour that way. */
193	    public int move(Person person, boolean up) {
194	        List<long[]> places = jdbc.query("SELECT id, place FROM person WHERE sheet_id = ? ORDER BY place, id",
195	                (rs, i) -> new long[] { rs.getLong(1), rs.getLong(2) }, person.getSheetId());
196	        int at = -1;
197	        for (int i = 0; i < places.size(); i++) {
198	            if (places.get(i)[0] == person.getId()) {
199	                at = i;
200	            }
201	        }
202	        int to = up ? at - 1 : at + 1;
203	        if (at < 0 || to < 0 || to >= places.size()) {
204	            return 0;
205	        }
206	        long[] mine = places.get(at);
207	        long[] theirs = places.get(to);
208	        jdbc.update("UPDATE person SET place = ? WHERE sheet_id = ? AND id = ?", theirs[1], person.getSheetId(), mine[0]);
209	        jdbc.update("UPDATE person SET place = ? WHERE sheet_id = ? AND id = ?", mine[1], person.getSheetId(), theirs[0]);
210	        return to + 1;
211	    }
