223	    /** The sheets of the sheet's tree: the sheet itself, its ancestors among the sheets that exist, and its descendants. */
224	    public List<String> tree(String sheetId) {
225	        java.util.LinkedHashSet<String> tree = new java.util.LinkedHashSet<>();
226	        tree.add(sheetId);
227	        for (String at = sheets.parent(sheetId); at != null && sheets.exists(at) && tree.add(at); at = sheets.parent(at)) {
228	            // climbs to the root, stopping at a loop
229	        }
230	        tree.addAll(sheets.descendants(sheetId));
231	        return new java.util.ArrayList<>(tree);
232	    }
