234	    /** Every name and alias used on the sheets, as names are compared, with who holds it. */
235	    private java.util.Map<String, java.util.Set<String>> uses(List<String> sheetIds) {
236	        java.util.Map<String, java.util.Set<String>> uses = new java.util.HashMap<>();
237	        for (String sheetId : sheetIds) {
238	            jdbc.query("SELECT id, name FROM person WHERE sheet_id = ?", rs -> {
239	                uses.computeIfAbsent(key(rs.getString("name")), k -> new java.util.HashSet<>()).add(holder(sheetId, rs.getLong("id")));
240	            }, sheetId);
241	            jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ?", rs -> {
242	                uses.computeIfAbsent(key(rs.getString("alias")), k -> new java.util.HashSet<>()).add(holder(sheetId, rs.getLong("person_id")));
243	            }, sheetId);
244	        }
245	        return uses;
246	    }
247	
248	    /** Whether anyone but the person holds the name in the uses. */
249	    private static boolean usedByOther(java.util.Map<String, java.util.Set<String>> uses, String name, Person person) {
250	        java.util.Set<String> holders = uses.getOrDefault(key(name), java.util.Set.of());
251	        return holders.stream().anyMatch(h -> !h.equals(holder(person.getSheetId(), person.getId())));
252	    }
253	
254	    /** Marks each person clashing when their name or an alias is used by anyone else on a sheet of the sheet's tree. */
255	    private List<Person> withClashing(String sheetId, List<Person> found) {
256	        if (found.isEmpty()) {
257	            return found;
258	        }
259	        java.util.Map<String, java.util.Set<String>> uses = uses(tree(sheetId));
260	        for (Person person : found) {
261	            boolean clashing = usedByOther(uses, person.getName(), person);
262	            for (String alias : person.getAliases()) {
263	                clashing |= usedByOther(uses, alias, person);
264	            }
265	            person.setClashing(clashing);
266	        }
267	        return found;
268	    }
269	
270	    /** Whether the person, named this, would clash: the name or one of their aliases is used by anyone else on a
271	     *  sheet of their sheet's tree. */
272	    public boolean wouldClash(Person person, String name) {
273	        java.util.Map<String, java.util.Set<String>> uses = uses(tree(person.getSheetId()));
274	        if (usedByOther(uses, name, person)) {
275	            return true;
276	        }
277	        for (String alias : person.getAliases()) {
278	            if (usedByOther(uses, alias, person)) {
279	                return true;
280	            }
281	        }
282	        return false;
283	    }
284	
285	    /** Whether anyone on another sheet of the sheet's tree uses the name as a name or alias, leaving out the person
286	     *  (null for no one). */
287	    public boolean nameUsedInTree(String sheetId, String name, Person except) {
288	        List<String> others = new java.util.ArrayList<>(tree(sheetId));
289	        others.remove(sheetId);
290	        java.util.Set<String> holders = uses(others).getOrDefault(key(name), java.util.Set.of());
291	        return holders.stream().anyMatch(h -> except == null || !h.equals(holder(except.getSheetId(), except.getId())));
292	    }
