294	    /** Fills in each person's patrons (ids in the order named, names sorted). */
295	    private List<Person> withPatrons(String sheetId, List<Person> found) {
296	        if (found.isEmpty()) {
297	            return found;
298	        }
299	        java.util.Map<Long, java.util.List<Long>> ids = new java.util.HashMap<>();
300	        java.util.Map<Long, java.util.List<String>> names = new java.util.HashMap<>();
301	        jdbc.query("SELECT pp.person_id, pp.patron_id, p.name FROM person_patron pp"
302	                + " JOIN person p ON p.sheet_id = pp.sheet_id AND p.id = pp.patron_id"
303	                + " WHERE pp.sheet_id = ? ORDER BY pp.seq", rs -> {
304	                    long person = rs.getLong("person_id");
305	                    ids.computeIfAbsent(person, k -> new java.util.ArrayList<>()).add(rs.getLong("patron_id"));
306	                    names.computeIfAbsent(person, k -> new java.util.ArrayList<>()).add(rs.getString("name"));
307	                }, sheetId);
308	        for (Person person : found) {
309	            java.util.List<String> sorted = new java.util.ArrayList<>(names.getOrDefault(person.getId(), List.of()));
310	            sorted.sort(BY_NAME);
311	            person.setPatrons(new java.util.ArrayList<>(ids.getOrDefault(person.getId(), List.of())), sorted);
312	        }
313	        return found;
314	    }
