351	    /** Merges the person into another (their claims already moved): their name and aliases become the other's
352	     *  aliases; their patrons are added to the other's and whoever named them names the other instead (never
353	     *  themselves, never twice); their pool memberships move to the other, shares added where the other is already
354	     *  a member; their fixed period figures add to the other's; their statement count adds to the other's (see
355	     *  {@link #takeStatements}). Their holds, watchers and contact go with them as they leave the sheet. */
356	    public void merge(Person from, Person into) {
357	        String sheetId = from.getSheetId();
358	        long fromId = from.getId();
359	        long intoId = into.getId();
360	        // Names.
361	        java.util.List<String> names = new java.util.ArrayList<>();
362	        names.add(from.getName());
363	        names.addAll(jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY seq",
364	                String.class, sheetId, fromId));
365	        jdbc.update("INSERT INTO person_alias_merged SELECT * FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY seq",
366	                sheetId, fromId);
367	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
368	        for (String name : names) {
369	            addAlias(into, name);
370	        }
371	        // Patrons the merged person named.
372	        for (Long patron : from.getPatronIds()) {
373	            if (patron != intoId && !into.getPatronIds().contains(patron)) {
374	                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, set_on) VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
375	                        sheetId, intoId, patron, sheetId);
376	                into.getPatronIds().add(patron);
377	            }
378	        }
379	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
380	        // Whoever named the merged person names the other instead.
381	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN"
382	                + " (SELECT person_id FROM person_patron WHERE sheet_id = ? AND patron_id = ?))",
383	                sheetId, fromId, intoId, sheetId, intoId);
384	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?", intoId, sheetId, fromId);
385	        // Pool memberships.
386	        jdbc.update("UPDATE pool_member m SET share = share + (SELECT f.share FROM pool_member f WHERE f.sheet_id = m.sheet_id"
387	                + " AND f.pool_name = m.pool_name AND f.person_id = ?) WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS"
388	                + " (SELECT 1 FROM pool_member f WHERE f.sheet_id = m.sheet_id AND f.pool_name = m.pool_name AND f.person_id = ?)",
389	                fromId, sheetId, intoId, fromId);
390	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ? AND pool_name IN"
391	                + " (SELECT pool_name FROM pool_member WHERE sheet_id = ? AND person_id = ?)", sheetId, fromId, sheetId, intoId);
392	        jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
393	        // Crews (each a pool of its lead and members): a crew they lead is led by the other, who is then no member of
394	        // it; a crew they are a member of has the other as member instead (never twice, never its lead).
395	        jdbc.update("UPDATE crew SET lead_person_id = ? WHERE sheet_id = ? AND lead_person_id = ?", intoId, sheetId, fromId);
396	        jdbc.update("DELETE FROM crew_member m WHERE m.sheet_id = ? AND m.person_id IN (?, ?) AND EXISTS (SELECT 1 FROM crew c"
397	                + " WHERE c.sheet_id = m.sheet_id AND c.name = m.crew_name AND c.lead_person_id = ?)", sheetId, fromId, intoId, intoId);
398	        jdbc.update("DELETE FROM crew_member WHERE sheet_id = ? AND person_id = ? AND crew_name IN"
399	                + " (SELECT crew_name FROM crew_member WHERE sheet_id = ? AND person_id = ?)", sheetId, fromId, sheetId, intoId);
400	        jdbc.update("UPDATE crew_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
401	        // Fixed period figures.
402	        jdbc.update("UPDATE period_person_total t SET (total, carried) = (SELECT t.total + f.total,"
403	                + " CASE WHEN t.carried IS NULL OR f.carried IS NULL THEN NULL ELSE t.carried + f.carried END"
404	                + " FROM period_person_total f WHERE f.sheet_id = t.sheet_id AND f.period_name = t.period_name AND f.person_id = ?) WHERE t.sheet_id = ? AND t.person_id = ? AND EXISTS"
405	                + " (SELECT 1 FROM period_person_total f WHERE f.sheet_id = t.sheet_id AND f.period_name = t.period_name AND f.person_id = ?)",
406	                fromId, sheetId, intoId, fromId);
407	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ? AND period_name IN"
408	                + " (SELECT period_name FROM period_person_total WHERE sheet_id = ? AND person_id = ?)", sheetId, fromId, sheetId, intoId);
409	        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
410	        // What is dropped with them.
411	        // Statements.
412	        takeStatements(from, into);
413	        for (String table : DROPPED_WITH_MERGE) {
414	            jdbc.update("INSERT INTO " + table + "_merged SELECT * FROM " + table + " WHERE sheet_id = ? AND person_id = ? ORDER BY seq",
415	                    sheetId, fromId);
416	        }
417	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
418	        jdbc.update("DELETE FROM person_retirement WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
419	        jdbc.update("DELETE FROM person_snapshot WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
420	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
421	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
422	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
423	        jdbc.update("DELETE FROM person_terms WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
424	        jdbc.update("INSERT INTO person_merged SELECT p.*, (SELECT today FROM sheet WHERE id = ?) FROM person p WHERE p.sheet_id = ? AND p.id = ?",
425	                sheetId, sheetId, fromId);
426	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, fromId);
427	    }
