429	    /** What a merge drops with the merged person and keeps (in {@code <table>_merged}) so an undo brings it back. */
430	    private static final List<String> DROPPED_WITH_MERGE = List.of("person_hold", "person_retirement", "person_snapshot",
431	            "person_watch", "person_statement", "person_grade", "person_terms");
432	
433	    /** Records that the user, on the sheet's today, merges the person into the other: which of their claims move
434	     *  and where each was listed, so the merge can be undone. Call before the claims move. */
435	    public void recordMerge(Person from, Person into, String user) {
436	        String sheetId = from.getSheetId();

437	        long aliasSeq = jdbc.queryForObject("SELECT COALESCE(MAX(seq), 0) FROM person_alias", Long.class);
438	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
439	        jdbc.update(con -> {
440	            PreparedStatement ps = con.prepareStatement("INSERT INTO person_merge (sheet_id, from_id, into_id, merged_by, merged_on, alias_seq)"
441	                    + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?)", new String[] { "SEQ" });
442	            ps.setString(1, sheetId);
443	            ps.setLong(2, from.getId());
444	            ps.setLong(3, into.getId());
445	            ps.setString(4, user);
446	            ps.setString(5, sheetId);
447	            ps.setLong(6, aliasSeq);
448	            return ps;
449	        }, keys);
450	        jdbc.update("INSERT INTO person_merge_claim (merge_seq, claim_id, listed_seq) SELECT ?, id, listed_seq FROM claim"
451	                + " WHERE sheet_id = ? AND person_id = ?", keys.getKey().longValue(), sheetId, from.getId());
452	    }
