468	    /** Undoes the merge into the person: the merged person is back, at the end of the list, as they stood when merged
469	     *  with what the merge dropped with them; the claims that came from them (still the other's) are theirs again,
470	     *  listed where they were; their name and own aliases leave the other's. Patron, pool, crew, period and statement
471	     *  changes stay. Returns the person restored. */
472	    public Person undoMerge(Person into, Merge merge) {
473	        String sheetId = into.getSheetId();
474	        long fromId = merge.fromId();
475	        long place = jdbc.queryForObject("SELECT COALESCE(MAX(COALESCE(place, id)), 0) + 1 FROM person WHERE sheet_id = ?",
476	                Long.class, sheetId);
477	        String columns = String.join(", ", columns("person"));
478	        jdbc.update("INSERT INTO person (" + columns + ") SELECT " + columns + " FROM person_merged WHERE sheet_id = ? AND id = ?"
479	                + " ORDER BY merged_on DESC LIMIT 1", sheetId, fromId);
480	        jdbc.update("DELETE FROM person_merged WHERE sheet_id = ? AND id = ?", sheetId, fromId);
481	        jdbc.update("UPDATE person SET place = ? WHERE sheet_id = ? AND id = ?", place, sheetId, fromId);
482	        Person from = find(sheetId, fromId);
483	        // Their name and own aliases leave the other's.
484	        List<String> names = new java.util.ArrayList<>();
485	        names.add(from.getName());
486	        names.addAll(jdbc.queryForList("SELECT alias FROM person_alias_merged WHERE sheet_id = ? AND person_id = ? ORDER BY seq",
487	                String.class, sheetId, fromId));
488	        for (String name : names) {
489	            jdbc.update("DELETE FROM person_alias WHERE seq = (SELECT MIN(seq) FROM person_alias WHERE sheet_id = ? AND person_id = ?"
490	                    + " AND seq > ? AND alias = ?)", sheetId, into.getId(), merge.aliasSeq(), name);
491	        }
492	        List<String> restored = new java.util.ArrayList<>(DROPPED_WITH_MERGE);
493	        restored.add("person_alias");
494	        for (String table : restored) {
495	            String kept = String.join(", ", columns(table).stream().filter(c -> !c.equalsIgnoreCase("seq")).toList());
496	            jdbc.update("INSERT INTO " + table + " (" + kept + ") SELECT " + kept + " FROM " + table + "_merged"
497	                    + " WHERE sheet_id = ? AND person_id = ? ORDER BY seq", sheetId, fromId);
498	            jdbc.update("DELETE FROM " + table + "_merged WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
499	        }
500	        jdbc.update("UPDATE person_merge SET undone = TRUE WHERE seq = ?", merge.seq());
501	        return find(sheetId, fromId);
502	    }
