563	    /** The person receiving another (merged or transferred into them, or arriving as them) takes their statements:
564	     *  the count becomes their own plus the other's and the other's statement history joins theirs; their last
565	     *  statement stays theirs (the other's come over as brought), or, having none, becomes the other's (so it can be
566	     *  cancelled as the other's could). */
567	    private void takeStatements(Person from, Person into) {
568	        if (from.getStatementCount() == 0) {
569	            return;
570	        }
571	        boolean hadNone = into.getStatementCount() == 0;
572	        into.setStatementCount(into.getStatementCount() + from.getStatementCount());
573	        if (hadNone) {
574	            into.setStatedTotal(from.getStatedTotal());
575	            into.setStatementDate(from.getStatementDate());
576	        }
577	        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, set_on, cancelled, cancelled_on, brought)"
578	                + " SELECT ?, ?, stated_total, statement_date, set_on, cancelled, cancelled_on, " + (hadNone ? "brought" : "TRUE")
579	                + " FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY seq",
580	                into.getSheetId(), into.getId(), from.getSheetId(), from.getId());
581	        saveStatement(into);
582	    }
