671	    /** Adds a person with their own terms in days, contact and tags (comma separated); each null for none. */
672	    public Person add(String sheetId, String name, String grade, Integer terms, String contact, String tags) {
673	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
674	        jdbc.update(con -> {
675	            PreparedStatement ps = con.prepareStatement(
676	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, tags, added_on) VALUES (?, ?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
677	                    Statement.RETURN_GENERATED_KEYS);
678	            ps.setString(1, sheetId);
679	            ps.setString(2, name);
680	            ps.setString(3, grade);
681	            ps.setObject(4, terms, java.sql.Types.INTEGER);
682	            ps.setString(5, contact);
683	            ps.setString(6, tags);
684	            ps.setString(7, sheetId);
685	            return ps;
686	        }, keys);
687	        Person person = new Person(keys.getKey().longValue(), sheetId, name, grade);
688	        // A new person goes to the end of the list.
689	        jdbc.update("UPDATE person SET place = id WHERE id = ?", person.getId());
690	        person.setPlace(person.getId());
691	        person.setTerms(terms);
692	        person.setContact(contact);
693	        person.setTags(tags);
694	        recordTags(sheetId, tags);
695	        writeHistory(person);
696	        // The first grade a person is given applies from the beginning of time.
697	        person.recordGrade(Person.BEGINNING, grade);
698	        writeRecordedGrade(person);
699	        person.setToday(sheets.today(sheetId));
700	        return person;
701	    }
