4	
5	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
6	
7	/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
8	 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
9	 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
10	 *  rate) or bound to n/a; `stated` is whether the last statement bound it. A claim with a negative
11	 *  amount is a correction: its due has no floor and no late charge. */
12	export type Claim = {
13	  id: string;
14	  personId: string;
15	  amount: string;
16	  date: string;
17	  note: string;
18	  status: ClaimStatus;
19	  number: string;
20	  due: string;
21	  /** The user who opened the claim, "" if it was never opened. */
22	  openedBy: string;
23	  stated: boolean;
24	  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
25	  corrects: string;
26	  /** The claim's external reference, unique on the sheet regardless of case; "" for none. */
27	  ref: string;
28	  /** The claim's tags, lower-cased, sorted and comma separated ("a,b"); "" for none. */
29	  tags?: string;
