72	/** OPEN and PENDING claims are open: their due is live (unless bound), they go overdue and a hold
73	 *  takes them out of the totals. */
74	export const isOpen = (c: { status?: string }) => c.status === 'OPEN' || c.status === 'PENDING';
75	
76	/** Only OPEN, PENDING and SETTLED claims count toward claimed, due-total and every total. */
77	export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';
78	
79	/** Whether a statement binds the claim's figure now (a PENDING claim included). */
80	export const isBound = (c: Claim) => c.stated;
81	
82	/** Whether the row shows the claim as deferred: it was deferred until a date after the sheet's today and no statement
83	 *  binds it now, whatever its status (a deferred claim later voided still shows it). Only an OPEN one is held back from
84	 *  the totals (`isDeferred`), or a SETTLED one settled while a statement bound it. */
85	export const deferredShown = (c: { deferredUntil?: string; stated?: boolean }, today: string | undefined) =>
86	  !c.stated && !!c.deferredUntil && today !== undefined && today < c.deferredUntil;
87	
88	/** Whether a claim is deferred on the sheet's today: OPEN (or SETTLED while a statement bound it), deferred until a later date and not bound by a statement
89	 *  (a deferral takes effect only once the binding ends). A deferred claim counts in no total, is not overdue, cannot
90	 *  be settled and is left unbound by a statement. */
91	export const isDeferred = (c: { status?: string; deferredUntil?: string; stated?: boolean }, today: string | undefined) =>
92	  (c.status === 'OPEN' || c.status === 'SETTLED') && !c.stated && !!c.deferredUntil && today !== undefined && today < c.deferredUntil;
93	
94	/** Whether a claim counts in the live totals: it counts, is not deferred on the sheet's today, and is not
95	 *  open, unbound and its person retired (`retiredOn`). A hold does not take it out — it only matters to the pools' cuts. */
96	export const countsLive = (c: Claim, retired: boolean, today: string | undefined) =>
97	  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && retired);
98	
99	/** Whether a claim counts toward claimed: as `countsLive` (a hold does not take it out). `retiredOn` tells whether its person is retired today. */
100	export const countsClaimed = (c: Claim, retired: boolean, today: string | undefined) =>
101	  counts(c) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && retired);
102	
103	/** The status a claim had at the end of the day, as its status log records it (each line dated the sheet's today
104	 *  when the change was made); undefined when it was added after that day. */
105	export function statusAt(c: Claim, end: string): ClaimStatus | undefined {
106	  let at: ClaimStatus | undefined;
107	  for (const line of c.log ?? []) {
108	    const m = / on (\d{4}-\d{2}-\d{2}) due=[^ ]*$/.exec(line);
109	    if (m && m[1] <= end) at = line.slice(0, line.indexOf(' ')) as ClaimStatus;
110	  }
111	  return at;
112	}
113	
114	/** Whether a claim counts in a period ending on `end`: by the status it had at the end of that day, and, as in the
115	 *  live totals, not deferred on the sheet's today and not open, unbound and its person retired. */
116	export const countsAtEnd = (c: Claim, end: string, retired: boolean, today: string | undefined) => {
117	  const then = statusAt(c, end);
118	  return then !== undefined && counts({ ...c, status: then }) && !isDeferred(c, today) && !(isOpen(c) && !isBound(c) && retired);
119	};
