147	/** The amounts of the claims that count added up, leaving out corrections (claims that correct another),
148	 *  shown with two decimals. Summed in whole cents so no float drift shows. */
149	export function sumAmounts(claims: Claim[]): string {
150	  const cents = claims.filter((c) => counts(c) && !c.corrects).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
151	  return (cents / 100).toFixed(2);
152	}
