6	/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
7	 *  "" for from the beginning of time) through a date ("" for no end), and its version: how many times a
8	 *  rate has been set for the grade and from-date, this the newest. One inherited from an ancestor
9	 *  sheet has its level: 1 the parent, 2 the parent's parent, 3 the one above, then a clone's source and its own
10	 *  ancestors in turn; the sheet's own have none.
11	 *  afterMark is 0 for a rate applying to every claim; a forward-only one (saved with a from-date on or after the
12	 *  sheet's today) applies only to claims whose rateMark is greater, the others falling back to the older versions
13	 *  it replaced (earlier, newest first). */
14	export type Rate = {
15	  grade: string;
16	  rate: string;
17	  from: string;
18	  to: string;
19	  version: number;
20	  level?: number;
21	  afterMark?: number;
22	  earlier?: { rate: string; to: string; afterMark: number }[];
23	};
24	
25	/** Whether a rate (version) with this mark applies to a claim with that one; no claim mark: the rate in force,
26	 *  without regard to forward-only rates (as the rates panel, the rate preview and the rate calendar show it). */
27	function applies(afterMark: number | undefined, claimMark: number | undefined): boolean {
28	  return !afterMark || claimMark === undefined || claimMark > afterMark;
29	}
30	
31	export const ratesKey = (sheet: string, asOf = '') => ['sheet', sheet, 'rates', asOf] as const;
32	
33	export const inheritedRatesKey = (sheet: string, asOf = '') => ['sheet', sheet, 'inherited-rates', asOf] as const;
34	
35	/** The sheet's own rates, by grade then from-date (from the beginning of time first), followed by
36	 *  its ancestors' (nearest first), each with its level. */
37	export function useRates(sheet: string): Rate[] {
38	  const asOf = useAsOf();
39	  const { data } = useQuery({
40	    queryKey: ratesKey(sheet, asOf),
41	    queryFn: () => getJson<Rate[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/rates`, asOf)),
42	    enabled: sheet !== '',
43	  });
44	  const { data: inherited } = useQuery({
45	    queryKey: inheritedRatesKey(sheet, asOf),
46	    queryFn: () => getJson<Rate[][]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/inherited-rates`, asOf)),
47	    enabled: sheet !== '',
48	  });
49	  return useMemo(
50	    () => [...(data ?? []), ...(inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 })))],
51	    [data, inherited],
52	  );
53	}
54	
55	/** One sheet's grade rate in force on a date (for a claim with a mark: of the versions that apply to it): the one with
56	 *  the latest from-date on or before it; undefined when none applies, or when that one's to-date is before the date. */
57	function ownRateOn(rates: Rate[], grade: string, date: string, level: number, mark?: number): string | undefined {
58	  let found: { from: string; rate: string; to: string } | undefined;
59	  for (const r of rates) {
60	    if ((r.level ?? 0) !== level || r.grade !== grade || r.from > date || (found !== undefined && r.from < found.from)) continue;
61	    const version = [r, ...(r.earlier ?? [])].find((v) => applies(v.afterMark, mark));
62	    if (version !== undefined) found = { from: r.from, rate: version.rate, to: version.to };
63	  }
64	  if (found === undefined || (found.to !== '' && found.to < date)) return undefined;
65	  return found.rate;
66	}
67	
68	/** The grade's rate in force on a date: the sheet's own (see ownRateOn); when it has none, its parent's,
69	 *  then the parent's parent's, up to three levels up, then a clone's source's and so on (each a level further);
70	 *  undefined when none has one (or the date is not known yet). */
71	export function rateOn(rates: Rate[], grade: string, date: string | undefined, mark?: number): string | undefined {
72	  if (date === undefined) return undefined;
73	  const levels = rates.reduce((max, r) => Math.max(max, r.level ?? 0), 0);
74	  for (let level = 0; level <= levels; level++) {
75	    const found = ownRateOn(rates, grade, date, level, mark);
76	    if (found !== undefined) return found;
77	  }
78	  return undefined;
79	}
80	
81	/** The grade's rate that applies to a claim on its date (see rateOn): a forward-only rate only when the claim
82	 *  arrived on the sheet after it was saved. */
83	export function claimRate(rates: Rate[], grade: string, claim: { date: string; rateMark?: number }): string | undefined {
84	  return rateOn(rates, grade, claim.date, claim.rateMark ?? 0);
85	}
