 147	    /** Add a period, refusing a name already on the sheet or dates overlapping another period. */
 148	    public void add(String sheetId, ValidPeriod period) throws InvalidPeriodException {
 149	        // Lock the sheet's row so two periods added at once cannot both pass the overlap check.
 150	        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, i) -> rs.getString(1), sheetId);
 151	        Integer named = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name = ?",
 152	                Integer.class, sheetId, period.name());
 153	        if (named != null && named > 0) {
 154	            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
 155	        }
 156	        Integer overlapping = jdbc.queryForObject(
 157	                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
 158	                Integer.class, sheetId, Date.valueOf(period.to()), Date.valueOf(period.from()));
 159	        if (overlapping != null && overlapping > 0) {
 160	            throw new InvalidPeriodException("The period's dates overlap another period");
 161	        }
 162	        try {
 163	            jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, added_on, claim_cap) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?)",
 164	                    sheetId, period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()), sheetId, period.cap());
 165	        } catch (DuplicateKeyException raced) {
 166	            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
 167	        }
 168	    }
