 205	/** Closes a period, fixing its due-total as it is now: the dues as shown now of the claims whose due-by is in it that counted
 206	 *  at the end of its last day (see {@link Person#countsAtEnd}), each with its late charge, and each person's share of it (a hold takes no claim out; a claim whose due is n/a adds nothing),
 207	 *  and every pool member's cut as it stands now (see {@link Pools#liveCuts}).
 208	 *  Used by a close by hand and by the auto close when the sheet's today is changed (see {@link #closeDue}). */
 209	@Service
 210	public class PeriodCloser {
 211	
 212	    private final Periods periods;
 213	    private final People people;
 214	    private final Claims claims;
 215	    private final Rates rates;
 216	    private final Settings settings;
 217	    private final Sheets sheets;
 218	    private final Audit audit;
 219	    private final Openings openings;
 220	    private final Pools pools;
 221	
 222	    public PeriodCloser(Periods periods, People people, Claims claims, Rates rates, Settings settings, Sheets sheets,
 223	            Audit audit, Openings openings, Pools pools) {
 224	        this.openings = openings;
 225	        this.pools = pools;
 226	        this.periods = periods;
 227	        this.people = people;
 228	        this.claims = claims;
 229	        this.rates = rates;
 230	        this.settings = settings;
 231	        this.sheets = sheets;
 232	        this.audit = audit;
 233	    }
 234	
 235	    /** Close the open (or soft-closed) period, auditing PERIOD_CLOSED (with auto=yes when closed by the auto close). */
 236	    public void close(String sheetId, PeriodResponse period, String user, boolean auto) {
 237	        close(sheetId, period, user, auto, false);
 238	    }
 239	
 240	    /** Soft-close the open period: its figures are fixed as by a close, but its claims stay open to change.
 241	     *  Audits PERIOD_SOFT_CLOSED. */
 242	    public void softClose(String sheetId, PeriodResponse period, String user) {
 243	        close(sheetId, period, user, false, true);
 244	    }
 245	
 246	    private void close(String sheetId, PeriodResponse period, String user, boolean auto, boolean soft) {
 247	        LocalDate from = LocalDate.parse(period.from());
 248	        LocalDate to = LocalDate.parse(period.to());
 249	        BigDecimal total = BigDecimal.ZERO.setScale(2);
 250	        LocalDate policyDate = settings.policyDate(sheetId);
 251	        LocalDate today = sheets.today(sheetId);
 252	        List<Claim> all = claims.list(sheetId);
 253	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
 254	        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
 255	        List<PeriodResponse> allPeriods = periods.list(sheetId);
 256	        Map<Long, BigDecimal> opening = openings.forPeriod(sheetId, period.name());
 257	        for (Person person : people.list(sheetId)) {
 258	            personCarried.put(person.getId(), carried(sheetId, person, all, allPeriods, from, to, policyDate, today)
 259	                    .add(opening.getOrDefault(person.getId(), BigDecimal.ZERO.setScale(2))));
 260	            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
 261	            for (Claim claim : all) {
 262	                if (claim.getPersonId() != person.getId() || !person.countsAtEnd(claim, to, today)
 263	                        || claim.getPeriodDate().isBefore(from) || claim.getPeriodDate().isAfter(to)) {
 264	                    continue;
 265	                }
 266	                personTotal = personTotal.add(due(sheetId, person, claim, policyDate, today));
 267	            }
 268	            personTotals.put(person.getId(), personTotal);
 269	            total = total.add(personTotal);
 270	        }
 271	        periods.close(sheetId, period.name(), total, personTotals, personCarried, soft, pools.liveCuts(sheetId));
 272	        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user
 273	                + " period=" + period.name() + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
 274	    }
 275	
 276	    /** A claim's due as shown now, its late charge included; 0.00 when it is n/a. */
 277	    private BigDecimal due(String sheetId, Person person, Claim claim, LocalDate policyDate, LocalDate today) {
 278	        RoundingMode rounding = Rounding.of(claim, policyDate, on -> settings.roundingMode(sheetId, on));
 279	        BigDecimal fixed = ClaimResponse.fixedDue(claim);
 280	        BigDecimal figure = fixed != null || claim.isBound() ? fixed
 281	                : Rates.due(claim.getAmount(), rates.find(claim, person.gradeOn(claim.getDate())), rounding);
 282	        if (figure == null) {
 283	            return BigDecimal.ZERO.setScale(2);
 284	        }
 285	        return LateCharge.due(claim, figure, settings.floor(sheetId, claim.getDate()), on -> settings.latePct(sheetId, on),
 286	                today, rounding, settings.grace(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
 287	    }
 288	
 289	    /** A person's carried figure for the period from-to: the dues as shown now of their claims whose due-by falls in a
 290	     *  period ending before this one starts that counted at the end of its last day and were then still OPEN or PENDING
 291	     *  (the person's opening balance for the period is added to it by the close). */
 292	    private BigDecimal carried(String sheetId, Person person, List<Claim> all, List<PeriodResponse> allPeriods,
 293	            LocalDate from, LocalDate to, LocalDate policyDate, LocalDate today) {
 294	        BigDecimal carried = BigDecimal.ZERO.setScale(2);
 295	        for (Claim claim : all) {
 296	            if (claim.getPersonId() != person.getId()) {
 297	                continue;
 298	            }
 299	            LocalDate dueBy = claim.getPeriodDate();
 300	            boolean earlier = allPeriods.stream().anyMatch(p -> !LocalDate.parse(p.from()).isAfter(dueBy)
 301	                    && !LocalDate.parse(p.to()).isBefore(dueBy) && LocalDate.parse(p.to()).isBefore(from));
 302	            ClaimStatus then = claim.statusAt(to);
 303	            if (!earlier || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) || !person.countsAtEnd(claim, to, today)) {
 304	                continue;
 305	            }
 306	            carried = carried.add(due(sheetId, person, claim, policyDate, today));
 307	        }
 308	        return carried;
 309	    }
 310	
 311	    /** A person's open figure at the end date: the dues as shown now of their claims whose due-by falls in one of the
 312	     *  periods that counted at the end date (see {@link Person#countsAtEnd}) and were then still OPEN or PENDING. */
 313	    public BigDecimal openAt(String sheetId, Person person, List<Claim> all, List<PeriodResponse> in, LocalDate end) {
 314	        LocalDate policyDate = settings.policyDate(sheetId);
 315	        LocalDate today = sheets.today(sheetId);
 316	        BigDecimal open = BigDecimal.ZERO.setScale(2);
 317	        for (Claim claim : all) {
 318	            if (claim.getPersonId() != person.getId()) {
 319	                continue;
 320	            }
 321	            LocalDate dueBy = claim.getPeriodDate();
 322	            boolean inside = in.stream().anyMatch(p -> !LocalDate.parse(p.from()).isAfter(dueBy)
 323	                    && !LocalDate.parse(p.to()).isBefore(dueBy));
 324	            ClaimStatus then = claim.statusAt(end);
 325	            if (!inside || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) || !person.countsAtEnd(claim, end, today)) {
 326	                continue;
 327	            }
 328	            open = open.add(due(sheetId, person, claim, policyDate, today));
 329	        }
 330	        return open;
 331	    }
 332	
 333	    /** The auto close, once the sheet's today is set: with grace days set, every open period whose to-date plus
 334	     *  them is before the sheet's today is closed, in order of their to-dates; a soft-closed period is left as it is. */
 335	    public void closeDue(String sheetId, String user) {
 336	        Integer grace = settings.graceDays(sheetId);
 337	        if (grace == null) {
 338	            return;
 339	        }
 340	        LocalDate today = sheets.today(sheetId);
 341	        List<PeriodResponse> due = periods.list(sheetId).stream()
 342	                .filter(p -> !p.closed() && !p.softClosed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
 343	                .sorted(java.util.Comparator.comparing(PeriodResponse::to))
 344	                .toList();
 345	        for (PeriodResponse period : due) {
 346	            PeriodResponse locked = periods.lock(sheetId, period.name());
 347	            if (locked != null && !locked.closed() && !locked.softClosed()) {
 348	                close(sheetId, locked, user, true);
 349	            }
 350	        }
 351	    }
 352	}

