18	 *  a claim opened is numbered within its period), the roles set and each grade's own terms in days, by grade
19	 *  (a grade not listed uses the sheet's terms), the cap with two decimals ("" for none: a person's due-total is at most it) and the
20	 *  proof threshold with two decimals ("" for none: above the one in force on its date a claim needs a proof to be settled or approved)
21	 *  and each action's permission, by action: the roles that may take it, comma separated ("" for the standing rule),
22	 *  and every delegation of the steward role, in the order given, and the note threshold with two decimals ("" for none: above the one
23	 *  in force on its date a claim cannot be opened with an empty note), and the fiscal year start month, 1 to 12 ("1" unless set), and the rounding mode in force
24	 *  on the sheet's today (half-up or half-even; "" for none), and the review SLA in days ("" for none; not dated), and the pending SLA in days ("" for none; not dated), and the proof kinds,
25	 *  comma separated ("" for none; not dated): above the proof threshold a claim needs one proof of each to be settled or approved,
26	 *  and the score thresholds, whole numbers ("" for blank; not dated): while both are set each person shows a band (see scoreBand),
27	 *  and the score log ("on", or "" for off; not dated): while on, changing the sheet's today audits each person's score,
28	 *  and the from-date of each policy version, in the order made ("" for none; see usePolicyVersions), and each policy
29	 *  version, oldest first: its from-date, the setting it changed and the value set ("" for none). */
30	export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string; roles: Role[]; gradeTerms: Record<string, string>; cap: string; dated: Record<string, Dated[]>; proofThreshold: string; perms: Record<string, string>; graceDays: string; delegations: Delegation[]; noteThreshold: string; entryDate: string; pot: string; parent: string; fiscalStartMonth: string; alertThreshold: string; rounding: string; reviewThreshold: string; escalateAfter: string; reviewSla: string; proofKinds: string; defaultGrade: string; scoreMid: string; scoreHigh: string; scoreLog: string; maxOpen: string; pendingSla: string; policyVersions: string[]; policyLines: PolicyLine[] };
