36	/** A value recorded for a dated setting (clerk-limit, floor, terms, terms-<grade>, late-pct, cap): the date
37	 *  it is in force from and the value ("" for none). The figures shown in Settings are those in force on the
38	 *  sheet's today; these are every value recorded, oldest first. */
39	export type Dated = { from: string; value: string };
40	
41	/** The value of a dated setting in force on a date: the one with the latest from-date on or before it,
42	 *  else the sheet's starting value. */
43	export function inForce(settings: Settings | undefined, key: string, date: string, start: string): string {
44	  const before = (settings?.dated?.[key] ?? []).filter((d) => d.from <= date);
45	  const found = before[before.length - 1];
46	  return found === undefined || found.value === '' ? start : found.value;
47	}
