49	/** A person's band for their score: HIGH at or above the score-high, MID at or above the score-mid, else LOW;
50	 *  "" while either threshold is blank. */
51	export function scoreBand(settings: Settings | undefined, score: string): string {
52	  const mid = settings?.scoreMid ?? '';
53	  const high = settings?.scoreHigh ?? '';
54	  if (mid === '' || high === '') return '';
55	  const value = Number(score);
56	  return value >= Number(high) ? 'HIGH' : value >= Number(mid) ? 'MID' : 'LOW';
57	}
