59	/** The floor a sheet starts with, used until its settings have loaded. */
60	export const DEFAULT_FLOOR = '1.00';
61	
62	/** The actions the permission matrix covers; a blank entry keeps the standing rule: open, settle, void and close
63	 *  by clerk and steward, reassign and reopen by steward, today by anyone but a viewer. */
64	export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen', 'today'] as const;
65	
66	export const settingsKey = (sheet: string, asOf = '') => ['sheet', sheet, 'settings', asOf] as const;
67	
68	export function useSettings(sheet: string): Settings | undefined {
69	  const asOf = useAsOf();
70	  const { data } = useQuery({
71	    queryKey: settingsKey(sheet, asOf),
72	    queryFn: () => getJson<Settings>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/settings`, asOf)),
73	    enabled: sheet !== '',
74	  });
75	  return data;
76	}
