78	/** The sheet's floor in force on a date (a claim's: its date). */
79	export function useFloor(sheet: string): (date: string) => string {
80	  const settings = useSettings(sheet);
81	  return (date) => inForce(settings, 'floor', date, DEFAULT_FLOOR);
82	}
