84	/** The late percent a sheet starts with, used until its settings have loaded. */
85	export const DEFAULT_LATE_PCT = '0.00';
86	
87	/** The sheet's late percent in force on a date (a late charge's: each 30-day boundary of an overdue claim). */
88	export function useLatePct(sheet: string): (date: string) => string {
89	  const settings = useSettings(sheet);
90	  return (date) => inForce(settings, 'late-pct', date, DEFAULT_LATE_PCT);
91	}
