93	/** How the sheet's claims round: its policy date (the one set, or the sheet's today when it is blank; undefined while
94	 *  loading) and every rounding mode recorded, by from-date (see roundsHalfUp). */
95	export function usePolicy(sheet: string): Policy {
96	  const settings = useSettings(sheet);
97	  const today = useSheetToday(sheet);
98	  return { date: settings?.policyDate ? settings.policyDate : today, rounding: settings?.dated?.rounding ?? [] };
99	}
