101	/** The sheet's cap in force on a date ("" for none; a person's: the date of their latest claim that counts): a person's
102	 *  due-total is at most it. */
103	export function useCap(sheet: string): (date: string) => string {
104	  const settings = useSettings(sheet);
105	  return (date) => inForce(settings, 'cap', date, '');
106	}
