108	/** The policy settings (the rounding mode, the floor, the cap, the terms, the late percent and the clerk limit) are
109	 *  versioned together: every change to one of them is a new version, numbered from 1 in the order made. */
110	export function usePolicyVersions(sheet: string) {
111	  const versions = useSettings(sheet)?.policyVersions ?? [];
112	  return {
113	    /** The current version number. */
114	    current: versions.length,
115	    /** The version in force on a date (a claim's: its date): how many versions are from on or before it (one with no
116	     *  from-date counts always). */
117	    on: (date: string) => versions.filter((from) => from === '' || from <= date).length,
