103	function divHalfEven(n: bigint, d: bigint): bigint {
104	  const negative = n < 0n !== d < 0n;
105	  const a = n < 0n ? -n : n;
106	  const b = d < 0n ? -d : d;
107	  const whole = a / b;
108	  const twice = (a % b) * 2n;
