    19	/**
    20	 * Rolls the year over: generates the new fiscal year's monthly periods as {@link GeneratePeriods} does (PERIOD_ADDED
    21	 * each), then adds each person's open figure at the end of the old year's last period (see
    22	 * {@link PeriodCloser#openAt}) to their opening for the new year's first period (OPENING_SET, a person with nothing
    23	 * open is left out; not again when an earlier rollover of the year still stands), then ROLLOVER with the old year and how many periods were made,
    24	 * then soft-closes every period of the old year still open, in start-date order (PERIOD_SOFT_CLOSED each, see
    25	 * {@link PeriodCloser#softClose}).
    26	 */
    27	public class RollOver {
    28	    public void rollover(@PathVariable("sheetId") String sheetId, @Val ValidRollover request, Periods periods,
    29	            People people, Claims claims, Openings openings, PeriodCloser closer, Rollovers rollovers, Audit audit,
    30	            ObjectResponse<GenerateResponse> response) {
    31	        ValidGenerate next = request.next();
    32	        long rollover = rollovers.start(sheetId, request.user(), request.fiscalYear());
    33	        List<String> made = new ArrayList<>();
    34	        YearMonth last = YearMonth.from(next.to());
    35	        for (YearMonth month = YearMonth.from(next.from()); !month.isAfter(last); month = month.plusMonths(1)) {
    36	            ValidPeriod period = new ValidPeriod(month.toString(), month.atDay(1), month.atEndOfMonth(), request.user());
    37	            if (periods.addIfFree(sheetId, period)) {
    38	                made.add(period.name());
    39	                audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + period.user()
    40	                        + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
    41	            }
    42	        }
    43	        rollovers.generated(rollover, made);
    44	        int generated = made.size();
    45	        LocalDate end = request.periods().stream().map(p -> LocalDate.parse(p.to()))
    46	                .max(Comparator.naturalOrder()).orElseThrow();
    47	        PeriodResponse first = periods.list(sheetId).stream()
    48	                .filter(p -> !LocalDate.parse(p.from()).isBefore(next.from()) && !LocalDate.parse(p.from()).isAfter(next.to()))
    49	                .findFirst().orElse(null);
    50	        // A year already rolled over (and not undone) has had its openings carried: they are not carried again.
    51	        if (first != null && !rollovers.standsBefore(sheetId, request.fiscalYear(), rollover)) {
    52	            List<Claim> all = claims.list(sheetId);
    53	            for (Person person : people.list(sheetId)) {
    54	                BigDecimal open = closer.openAt(sheetId, person, all, request.periods(), end);
    55	                if (open.signum() == 0) {
    56	                    continue;
    57	                }
    58	                openings.addByRollover(sheetId, person.getId(), first.name(), open, rollover);
    59	                audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + request.user() + " name=" + person.getName()
    60	                        + " period=" + first.name() + " amount=" + open.toPlainString());
    61	            }
    62	        }
    63	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + request.user() + " fy=" + request.fiscalYear()
    64	                + " periods=" + generated);
    65	        // Then every period of the old year still open is soft-closed, in start-date order.
    66	        List<PeriodResponse> old = request.periods().stream()
    67	                .sorted(Comparator.comparing((PeriodResponse p) -> LocalDate.parse(p.from()))).toList();
    68	        for (PeriodResponse period : old) {
    69	            PeriodResponse locked = periods.lock(sheetId, period.name());
    70	            if (locked != null && !locked.closed() && !locked.softClosed()) {
    71	                closer.softClose(sheetId, locked, request.user());
    72	            }
    73	        }
    74	        response.send(new GenerateResponse(generated, periods.list(sheetId)));
    75	    }
    76	}
