    34	            throw new InvalidPeriodException("Only the steward who rolled the year over may undo it");
    35	        }
    36	        if (!last.madeOn().equals(sheets.today(sheetId))) {
    37	            throw new InvalidPeriodException("A rollover can be undone only on the day it was made");
    38	        }
    39	        for (String name : last.periods()) {
    40	            PeriodResponse period = periods.lock(sheetId, name);
    41	            if (period == null) {
    42	                continue;
    43	            }
