    45	                    "SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND claim_date >= ? AND claim_date <= ?", Integer.class,
    46	                    sheetId, Date.valueOf(period.from()), Date.valueOf(period.to()));
    47	            if (claimed != null && claimed > 0) {
    48	                throw new InvalidPeriodException("A claim belongs to period " + name + " the rollover generated");
    49	            }
