    52	        openings.removeByRollover(sheetId, last.id());
    53	        rollovers.undone(last.id());
    54	        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=" + last.fiscalYear());
