    34	    /** A person and their claims, with the date standing for the sheet's today and the figures in force then
    35	     *  (the rounding mode and the cap in force on a date: null for none). */
    36	    public record View(LocalDate today, LocalDate policyDate, Function<LocalDate, BigDecimal> cap, Person person, List<Claim> claims,
    37	            Rates.Lookup rate, Function<LocalDate, BigDecimal> floor,
    38	            Function<LocalDate, BigDecimal> latePct, Function<LocalDate, java.math.RoundingMode> rounding) {
