    50	    public AsOf(JdbcTemplate jdbc, Claims claims, Rates rates, Settings settings, Sheets sheets) {
    51	        this.jdbc = jdbc;
    52	        this.claims = claims;
    53	        this.rates = rates;
    54	        this.settings = settings;
    55	        this.sheets = sheets;
    56	    }
