    58	    /** The person and their claims as they stand now. */
    59	    public View now(Person person) {
    60	        String sheetId = person.getSheetId();
    61	        return new View(sheets.today(sheetId), settings.policyDate(sheetId), on -> settings.cap(sheetId, on), person,
    62	                claims.ofPerson(sheetId, person.getId()), (grade, on, mark) -> rates.find(sheetId, grade, on, mark),
    63	                on -> settings.floor(sheetId, on), on -> settings.latePct(sheetId, on), on -> settings.roundingMode(sheetId, on));
    64	    }
    65	
    66	    /** The person and the claims that were theirs as they stood at the end of the date. */
    67	    public View at(Person person, LocalDate date) {
    68	        String sheetId = person.getSheetId();
    69	        Date end = Date.valueOf(date);
    70	        String upTo = " AND (set_on IS NULL OR set_on <= ?) ORDER BY seq";
    71	
    72	        // The rates: the sheet's own, then (for a grade it has none in force for) its ancestors', each as set by the end of the date.
    73	        List<Rates.Lookup> levels = new ArrayList<>();
    74	        levels.add(ratesAt(sheetId, end));
    75	        for (String ancestor : rates.ancestors(sheetId)) {
    76	            levels.add(ratesAt(ancestor, end));
    77	        }
    78	        Rates.Lookup rate = (grade, on, mark) -> {
    79	            for (Rates.Lookup level : levels) {
    80	                BigDecimal found = level.rate(grade, on, mark);
    81	                if (found != null) return found;
    82	            }
    83	            return null;
    84	        };
    85	
    86	        // The dated settings: the latest recorded for each key and from-date (a null value: none from then).
    87	        Map<String, TreeMap<LocalDate, Object[]>> dated = new HashMap<>();
    88	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_history WHERE sheet_id = ?" + upTo,
    89	                (RowCallbackHandler) rs -> dated.computeIfAbsent(rs.getString(1), k -> new TreeMap<>())
    90	                        .put(rs.getDate(2).toLocalDate(), new Object[] { rs.getBigDecimal(3) }), sheetId, end);
    91	        BiFunction<String, LocalDate, BigDecimal> setting = (key, on) -> {
    92	            Map.Entry<LocalDate, Object[]> found = dated.getOrDefault(key, new TreeMap<>()).floorEntry(on);
    93	            return found == null ? null : (BigDecimal) found.getValue()[0];
    94	        };
    95	        Function<LocalDate, BigDecimal> floor = on -> {
    96	            BigDecimal value = setting.apply(ValidateSetting.FLOOR, on);
    97	            return value == null ? Settings.START_FLOOR : value;
    98	        };
    99	        Function<LocalDate, BigDecimal> latePct = on -> {
   100	            BigDecimal value = setting.apply(ValidateSetting.LATE_PCT, on);
   101	            return value == null ? Settings.START_LATE_PCT : value;
   102	        };
   103	        Function<LocalDate, BigDecimal> cap = on -> setting.apply(ValidateSetting.CAP, on);
   104	
   105	        // The policy date: the latest set (blank: the date itself).
   106	        List<LocalDate> policies = new ArrayList<>();
   107	        jdbc.query("SELECT policy_date FROM policy_history WHERE sheet_id = ?" + upTo,
   108	                (RowCallbackHandler) rs -> policies.add(local(rs.getDate(1))), sheetId, end);
   109	        LocalDate policy = policies.isEmpty() || policies.get(policies.size() - 1) == null ? date
   110	                : policies.get(policies.size() - 1);
   111	
   112	        return new View(date, policy, cap, personAt(person, end), claimsAt(person, end), rate, floor, latePct,
   113	                on -> net.officefloor.hq.app.claim.Rounding.mode(setting.apply(ValidateSetting.ROUNDING, on)));
   114	    }
   115	
   116	    /** A sheet's own rates as set by the end of a date: for a grade, a date and a claim's mark, of the rates set that apply
   117	     *  to the claim (see {@link Rates#applies}), the latest set for the latest from-date on or before the date; null when
   118	     *  none applies, or when that one's to-date is before the date. */
   119	    private Rates.Lookup ratesAt(String sheetId, Date end) {
   120	        Map<String, Map<LocalDate, List<RateRow>>> rateRows = new HashMap<>();
   121	        jdbc.query("SELECT grade, rate, from_date, to_date, after_mark FROM rate_history WHERE sheet_id = ? AND (set_on IS NULL OR set_on <= ?) ORDER BY seq",
   122	                (RowCallbackHandler) rs -> {
   123	                    LocalDate from = local(rs.getDate("from_date"));
   124	                    rateRows.computeIfAbsent(rs.getString("grade").trim(), g -> new HashMap<>())
   125	                            .computeIfAbsent(from == null ? LocalDate.MIN : from, f -> new ArrayList<>())
   126	                            .add(0, new RateRow(rs.getBigDecimal("rate"), from, local(rs.getDate("to_date")), rs.getLong("after_mark")));
   127	                }, sheetId, end);
   128	        return (grade, on, mark) -> {
   129	            TreeMap<LocalDate, List<RateRow>> byFrom = new TreeMap<>(rateRows.getOrDefault(grade, Map.of()));
   130	            for (List<RateRow> versions : byFrom.headMap(on, true).descendingMap().values()) {
   131	                for (RateRow row : versions) {
   132	                    if (Rates.applies(row.afterMark(), mark)) {
   133	                        return row.to() != null && row.to().isBefore(on) ? null : row.rate();
   134	                    }
   135	                }
   136	            }
   137	            return null;
   138	        };
   139	    }
   140	
   141	    /** The person with the grades, holds and retirement recorded by the end of the date. */
   142	    private Person personAt(Person now, Date end) {
   143	        String sheetId = now.getSheetId();
   144	        Map<LocalDate, String> grades = new LinkedHashMap<>();
   145	        jdbc.query("SELECT from_date, grade FROM grade_history WHERE sheet_id = ? AND person_id = ?"
   146	                + " AND (set_on IS NULL OR set_on <= ?) ORDER BY seq", (RowCallbackHandler) rs -> {
   147	                    LocalDate from = local(rs.getDate(1));
   148	                    grades.put(from == null ? Person.BEGINNING : from, rs.getString(2));
   149	                }, sheetId, now.getId(), end);
   150	        Person person = new Person(now.getId(), sheetId, now.getName(), now.getGrades().get(now.getGrades().firstKey()));
   151	        person.setGrades(grades);
   152	        person.setToday(end.toLocalDate());
   153	        List<Person.Hold> holds = new ArrayList<>();
   154	        jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? AND person_id = ?"
   155	                + " AND (set_on IS NULL OR set_on <= ?) ORDER BY seq", (RowCallbackHandler) rs -> holds.add(
   156	                        new Person.Hold(rs.getDate(1).toLocalDate(), local(rs.getDate(2)))), sheetId, now.getId(), end);
   157	        person.setHolds(holds);
   158	        List<LocalDate> retired = new ArrayList<>();
   159	        jdbc.query("SELECT retired_from FROM retire_history WHERE sheet_id = ? AND person_id = ?"
   160	                + " AND (set_on IS NULL OR set_on <= ?) ORDER BY seq", (RowCallbackHandler) rs -> retired.add(
   161	                        local(rs.getDate(1))), sheetId, now.getId(), end);
   162	        person.setRetiredFrom(retired.isEmpty() ? null : retired.get(retired.size() - 1));
   163	        return person;
   164	    }
   165	
   166	    /** The claims that were the person's at the end of the date, each as it stood then, newest first. */
   167	    private List<Claim> claimsAt(Person person, Date end) {
   168	        String sheetId = person.getSheetId();
   169	        Map<Long, Claim> latest = new LinkedHashMap<>();
   170	        jdbc.query("SELECT * FROM claim_history WHERE sheet_id = ? AND (set_on IS NULL OR set_on <= ?) ORDER BY seq",
   171	                (RowCallbackHandler) rs -> {
   172	                    Claim claim = new Claim(rs.getLong("claim_id"), sheetId, rs.getLong("person_id"),
   173	                            rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), "",
   174	                            ClaimStatus.valueOf(rs.getString("status")), null, rs.getBigDecimal("settled_due"), null);
   175	                    claim.setStated(rs.getBoolean("stated"));
   176	                    claim.setStatedDue(rs.getBigDecimal("stated_due"));
   177	                    claim.setDueBy(local(rs.getDate("due_by")));
   178	                    claim.setDeferredUntil(local(rs.getDate("deferred_until")));
   179	                    claim.setCorrects(rs.getString("corrects"));
   180	                    claim.setRateMark(rs.getLong("rate_mark"));
   181	                    claim.setWaived(rs.getBoolean("waived"));
   182	                    claim.setHeld(rs.getBoolean("held"));
   183	                    latest.put(claim.getId(), claim);
   184	                }, sheetId, end);
   185	        List<Claim> own = new ArrayList<>();
   186	        for (Claim claim : latest.values()) {
   187	            if (claim.getPersonId() == person.getId()) {
   188	                if (claim.getDueBy() == null) claim.setDueBy(claim.getDate());
   189	                claim.setCorrectedDate(claims.correctedDate(sheetId, person.getId(), claim.getCorrects()));
   190	                own.add(0, claim);
   191	            }
   192	        }
   193	        return own;
   194	    }
   195	
   196	    private static LocalDate local(Date date) {
   197	        return date == null ? null : date.toLocalDate();
   198	    }
   199	}
