/**
 * Adds a DRAFT claim dated the sheet's today, with an empty note, for the person of that name or alias (name
 * compared as the person form compares it), first adding the person with
 * the sheet's default grade when no one on the sheet has that name (refused when the name is used on another sheet of its tree). One change: a refused claim leaves no new person behind.
 */
public class SaveQuickClaim {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidQuickClaim request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup,
            net.officefloor.hq.app.setting.Settings settings, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays,
            net.officefloor.hq.app.grade.RetiredGrades grades,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        LocalDate date = settings.claimDate(sheetId);
        String grade = settings.defaultGrade(sheetId);
        if (grades.isRetired(sheetId, grade)) {
            grade = net.officefloor.hq.app.setting.Settings.START_DEFAULT_GRADE; // a retired default falls back to A
        }
        Person person = people.findByName(sheetId, request.name());
        // Refuse before anything is written: the claim's period goes by the due-by it would be fixed with.
        LocalDate dueBy = holidays.dueBy(sheetId, date, person != null
                ? settings.termsOnCreation(sheetId, person)
                : settings.termsFor(sheetId, grade, sheets.today(sheetId)));
        if (periods.isClosed(sheetId, dueBy)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        RollupFigures beforeClaim = before;
        if (person == null) {
            if (people.nameTaken(sheetId, request.name(), null)) {
                throw new InvalidClaimException("The name is already in use");
            }
            if (grades.isRetired(sheetId, grade)) {
                throw new InvalidClaimException("Grade " + grade + " is retired");
            }
            person = people.add(sheetId, request.name(), grade);
            audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                    + " name=" + person.getName() + " grade=" + person.getGrade());
            rollup.recordChanges(sheetId, request.user(), before);
            beforeClaim = rollup.figures(sheetId);
        }
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, "", dueBy);
        log.record(claim, person, request.user());
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        rollup.recordChanges(sheetId, request.user(), beforeClaim);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
=== ValidatePasteClaims
/**
 * Splits the paste into lines of name,amount,date,note (the note may hold commas, the date may be
 * blank, the note absent) and checks each by the claim form's rules. Blank lines are skipped; a paste
 * with no claim in it is refused.
 */
public class ValidatePasteClaims {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteClaimsRequest request, Out<ValidPasteClaims> body, Settings settings)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String text = request.text() == null ? "" : request.text();
        List<ValidPasteClaims.Line> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n")) {
            number++;
            if (raw.isBlank()) continue;
            String[] fields = raw.split(",", 4);
            if (fields.length < 2) {
                throw new InvalidClaimException("Line " + number + ": a line is name,amount,date,note");
            }
            String name = fields[0].trim();
            if (name.isEmpty()) {
                throw new InvalidClaimException("Line " + number + ": a name is required");
            }
            // A note ending " #<reference>" gives the claim's reference: that part is not the note.
            String note = fields.length > 3 ? fields[3].trim() : "";
            String ref = null;
            int hash = note.lastIndexOf(" #");
            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
                ref = note.substring(hash + 2);
                note = note.substring(0, hash);
            }
            ClaimRequest claim = new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "", note, request.user(), null, ref, null);
            try {
                lines.add(new ValidPasteClaims.Line(name, ValidateClaim.check(claim)));
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
            }
        }
        java.util.Set<String> refs = new java.util.HashSet<>();
        for (ValidPasteClaims.Line line : lines) {
            String ref = line.claim().ref();
            if (ref != null && !refs.add(ref.toLowerCase(java.util.Locale.ROOT))) {
                throw new InvalidClaimException("The reference " + ref + " is given twice in the paste");
            }
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Nothing to paste: give one claim per line");
        }
        body.set(new ValidPasteClaims(lines, request.user()));
    }
}
=== SavePasteClaims
/**
 * Takes the pasted claims in order, each arriving OPEN. Every line is checked against the sheet first
 * (the person is on the sheet, by name or alias, matched as names are compared; the date is not inside a
 * closed period nor after the person's retirement; a person flagged on the sheet's today only by a steward; the
 * person, counting the lines before it, is below the sheet's maximum of OPEN or PENDING claims). A line whose person, date and note match one of the
 * person's claims as they stood before the paste (not VOID nor DELETED) updates the newest such DRAFT to
 * the line's amount (CLAIM_EDITED when it changes) instead of adding one; matches with no DRAFT among
 * them refuse the paste. Any other line is added as a DRAFT (CLAIM_ADDED). Each is then opened by the
 * user exactly as the open button would; a refusal there refuses the whole paste, which writes nothing.
 */
public class SavePasteClaims {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidPasteClaims request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, Rollup rollup, Settings settings, Rates rates,
            ClaimNumbering numbering, ClaimLog log, Watches watches, net.officefloor.hq.app.holiday.Holidays holidays,
            org.springframework.transaction.PlatformTransactionManager transactions,
            ObjectResponse<PasteClaimsResponse> response) throws InvalidClaimException {
        LocalDate today = settings.claimDate(sheetId);
        List<Claim> existing = claims.list(sheetId);
        List<Person> persons = new ArrayList<>();
        List<LocalDate> dates = new ArrayList<>();
        List<Claim> matched = new ArrayList<>();
        boolean steward = Settings.STEWARD.equals(settings.role(sheetId, request.user()));
        // Every line is opened: a role that may not open refuses the paste before anything is written.
        if (!settings.allows(sheetId, request.user(), "open")) {
            throw new InvalidClaimException("Your role may not open a claim on this sheet");
        }
        // The sheet's maximum of open claims: each line opens one more for its person.
        Integer maxOpen = settings.maxOpen(sheetId);
        java.util.Map<Long, Long> held = new java.util.HashMap<>();
        int number = 0;
        for (ValidPasteClaims.Line line : request.lines()) {
            number++;
            Person person = people.findByName(sheetId, line.name());
            if (person == null) {
                throw new InvalidClaimException("Claim " + number + ": no one on the sheet is named " + line.name());
            }
            if (!steward && person.flaggedOn(sheets.today(sheetId))) {
                throw new InvalidClaimException("Claim " + number + ": only a steward can open a claim of a flagged person");
            }
            LocalDate date = line.claim().date() != null ? line.claim().date() : today;
            LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsOnCreation(sheetId, person));
            if (periods.isClosed(sheetId, dueBy)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be added inside a closed period");
            }
            if (!person.allowsClaimOn(date)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be dated after the person's retirement date");
            }
            Claim match = match(existing, person, date, line.claim().note(), number);
            if (match == null) {
                try {
                    ValidateClaim.checkRef(line.claim().ref(), sheetId, null, claims);
                } catch (InvalidClaimException e) {
                    throw new InvalidClaimException("Claim " + number + ": " + e.getMessage());
                }
            }
            if (maxOpen != null) {
                long open = held.computeIfAbsent(person.getId(), id -> existing.stream()
                        .filter(c -> c.getPersonId() == id)
                        .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                        .count());
                if (open >= maxOpen) {
                    throw new InvalidClaimException("Claim " + number + ": the person already has " + maxOpen
                            + " OPEN or PENDING claims, the sheet's maximum");
                }
                held.put(person.getId(), open + 1);
            }
            persons.add(person);
            dates.add(date);
            matched.add(match);
        }
        ValidClaimStatus open = new ValidClaimStatus(ClaimStatus.OPEN, request.user(), ValidClaimStatus.Decision.NONE, null);
        // The lines are written in one transaction: a refused open rolls back the lines added before it (and their audit).
        org.springframework.transaction.TransactionStatus transaction = transactions.getTransaction(
                new org.springframework.transaction.support.DefaultTransactionDefinition());
        try {
            write(sheetId, request, persons, dates, matched, open, people, claims, sheets, periods, audit, rollup, settings,
                    rates, numbering, log, watches, holidays);
        } catch (InvalidClaimException | RuntimeException e) {
            transactions.rollback(transaction);
            throw e;
        }
        transactions.commit(transaction);
        response.send(new PasteClaimsResponse(request.lines().size()));
    }
    /** Adds (or updates) and opens each line in order; throws on the first refusal. */
    private static void write(String sheetId, ValidPasteClaims request, List<Person> persons, List<LocalDate> dates,
            List<Claim> matched, ValidClaimStatus open, People people, Claims claims, Sheets sheets, Periods periods,
            Audit audit, Rollup rollup, Settings settings, Rates rates, ClaimNumbering numbering, ClaimLog log,
            Watches watches, net.officefloor.hq.app.holiday.Holidays holidays) throws InvalidClaimException {
        for (int i = 0; i < request.lines().size(); i++) {
            ValidClaim valid = request.lines().get(i).claim();
            Person person = persons.get(i);
            LocalDate date = dates.get(i);
            RollupFigures before = rollup.figures(sheetId);
            Claim claim = matched.get(i);
            if (claim == null) {
                claim = claims.add(sheetId, person.getId(), valid.amount(), date, valid.note(), null,
                        holidays.dueBy(sheetId, date, settings.termsOnCreation(sheetId, person)), valid.ref());
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
                LateEntry.mark(claim, person, request.user(), claims, periods, audit);
            } else {
                claim = claims.find(sheetId, claim.getId());
                if (claim.getStatus() != ClaimStatus.DRAFT) {
                    throw new InvalidClaimException("Claim " + (i + 1) + ": the claim it matches is no longer a DRAFT");
                }
                if (claim.getAmount().compareTo(valid.amount()) != 0) {
                    String lockedBy = claims.lockedBy(claim);
                    if (lockedBy != null && !lockedBy.equals(request.user())) {
                        throw new InvalidClaimException("Claim " + (i + 1) + ": the claim is being edited by " + lockedBy);
                    }
                    List<ClaimLine> lines = claims.lines(claim);
                    if (!lines.isEmpty() && valid.amount().compareTo(ClaimLine.sum(lines)) != 0) {
                        throw new InvalidClaimException("Claim " + (i + 1) + ": a claim with lines takes its amount from its lines");
                    }
                    claim.setAmount(valid.amount());
                    claim.setEditedBy(request.user());
                    claims.save(claim);
                    audit.recordOnCommit(ClaimAudit.line("CLAIM_EDITED", request.user(), person, claim, claim.getNumber()));
                }
            }
            ClaimNumber opened;
            try {
                ApplyClaimStatus.refuseOverCap(claim, periods, claims.list(sheetId));
                ApplyClaimStatus.refuseOverMaxOpen(claim, settings, claims.list(sheetId));
                opened = ApplyClaimStatus.change(open, claim, sheets, people, rates, periods, settings, numbering, log);
            } catch (ClaimStatusRefusedException e) {
                throw new InvalidClaimException("Claim " + (i + 1) + ": " + e.getMessage());
            }
            claims.save(claim);
            AuditClaimStatus.record(open, claim, opened, people, audit, before, rollup, log, watches);
        }
    }
    /** The newest DRAFT among the person's claims (not VOID nor DELETED) of that date and note; null when none
     *  match; refused when some match but none is a DRAFT. */
    private static Claim match(List<Claim> existing, Person person, LocalDate date, String note, int number)
            throws InvalidClaimException {
        String wanted = note == null ? "" : note.trim();
        boolean any = false;
        Claim draft = null;
        for (Claim c : existing) {
            if (c.getPersonId() != person.getId() || c.getStatus() == ClaimStatus.VOID || c.getStatus() == ClaimStatus.DELETED
                    || !date.equals(c.getDate()) || !wanted.equals(c.getNote() == null ? "" : c.getNote().trim())) {
                continue;
            }
            any = true;
            if (c.getStatus() == ClaimStatus.DRAFT && (draft == null || c.getId() > draft.getId())) {
                draft = c;
            }
        }
        if (any && draft == null) {
            throw new InvalidClaimException("Claim " + number + ": the claims it matches include no DRAFT to update");
        }
        return draft;
    }
}
=== BulkOpenClaims
/**
 * Opens the selected claims in list order (people in the order they were added, newest claim first
 * within a person), unnumbered until settled, and auditing it as a single open would be. A selected
 * claim that cannot be opened (not DRAFT, its due-by inside a closed period, the user's role may not open, its note is empty while its due is above the note threshold, its person is flagged and the user is not a steward, its person already has as many OPEN or
 * as refused; so is a selected id that is not a claim on the sheet. A claim whose due is above the review threshold goes to
 * REVIEW instead and counts as opened.
 */
public class BulkOpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @RequestBody BulkOpenRequest request,
            Claims claims, People people, Periods periods, Settings settings, Sheets sheets, Rates rates, Rollup rollup, Audit audit, ClaimLog log,
            ObjectResponse<BulkOpenResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        List<Claim> all = claims.list(sheetId);
        // A role the sheet's open permission does not allow opens none of them.
        boolean allowed = settings.allows(sheetId, request.user(), "open");
        boolean steward = Settings.STEWARD.equals(settings.role(sheetId, request.user()));
        int opened = 0;
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
                    continue;
                }
                if (!allowed || !claim.getStatus().canBecome(ClaimStatus.OPEN)
                        || periods.isClosed(sheetId, claim.getPeriodDate())) {
                    continue;
                }
                java.math.RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId), on -> settings.roundingMode(sheetId, on));
                try {
                    ApplyClaimStatus.refuseFlagged(claim, sheets, people, steward);
                    ApplyClaimStatus.refuseNoteless(claim, sheets, people, rates, settings, rounding);
                    ApplyClaimStatus.refuseOverCap(claim, periods, all);
                    ApplyClaimStatus.refuseOverMaxOpen(claim, settings, all);
                } catch (ClaimStatusRefusedException e) {
                    continue;
                }
                if (ApplyClaimStatus.needsReview(claim, sheets, people, rates, settings, rounding)) {
                    // Above the review threshold it goes to REVIEW, unnumbered, and counts as opened.
                    claim.setOpenedBy(request.user());
                    claim.setStatus(ClaimStatus.REVIEW);
                    claims.save(claim);
                    log.record(claim, person, request.user());
                    audit.recordOnCommit(ClaimAudit.line("CLAIM_REVIEW", request.user(), person, claim, null));
                    opened++;
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                claim.setOpenedBy(request.user());
                claim.setStatus(ClaimStatus.OPEN);
                claims.save(claim);
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.line("CLAIM_OPENED", request.user(), person, claim, claim.getNumber()));
                rollup.recordChanges(sheetId, request.user(), before);
                opened++;
            }
        }
        response.send(new BulkOpenResponse(opened, selected.size() - opened));
    }
}
