63	// How many people there are when those sharing a name or alias (directly or through others) are one.
64	function distinctPeople(people: string[][]): number {
65	  const parent = people.map((_, i) => i);
66	  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));
67	  const holder = new Map<string, number>();
68	  people.forEach((keys, i) =>
69	    keys.forEach((k) => {
70	      const j = holder.get(k);
71	      if (j === undefined) holder.set(k, i);
72	      else parent[find(i)] = find(j);
73	    }),
74	  );
75	  return people.filter((_, i) => find(i) === i).length;
76	}
