1	import { useIsFetching, useQuery } from '@tanstack/react-query';
2	import { useState } from 'react';
3	import { getJson } from '../../api/http';
4	import { gradeOn, type Person } from '../people/usePeople';
5	import { useGradeCodes } from '../grades/useGrades';
6	import { asString, useSearchParam } from '../../url/useSearchParam';
7	import { useSheetFigures } from '../people/useSheetFigures';
8	import { formatCents } from '../rates/due';
9	
10	type GradeDue = (g: string) => bigint;
11	
12	// A grade's due-total as the summary shows it: the due-totals of the people on it today (retired people
13	// left out, n/a skipped) added up.
14	const gradeDueOf =
15	  (people: Person[], today: string | undefined, totalOf: (p: Person) => bigint | null): GradeDue =>
16	  (g) =>
17	    people
18	      .filter((p) => !p.retired && gradeOn(p, today) === g)
19	      .reduce((sum, p) => sum + (totalOf(p) ?? 0n), 0n);
20	
21	// Compares this sheet with another: per grade, "<grade> <this sheet's summary due-total> <the other's>"
22	// (0.00 where the other has no one on it). A sheet that does not exist gives no lines, and is not started
23	// by asking. Lines are gone while a press is being worked out.
24	export function SheetCompare({ people, today, totalOf }: { people: Person[]; today: string | undefined; totalOf: (p: Person) => bigint | null }) {
25	  const [other, setOther] = useState('');
26	  const [asked, setAsked] = useState<{ sheet: string; press: number } | null>(null);
27	  const mine = gradeDueOf(people, today, totalOf);
28	  return (
29	    <div>
30	      Compare with sheet <input data-testid="compare-sheet" value={other} onChange={(e) => setOther(e.target.value)} />{' '}
31	      <button type="button" data-testid="compare" onClick={() => setAsked({ sheet: other.trim(), press: (asked?.press ?? 0) + 1 })}>
32	        Compare
33	      </button>
34	      {asked !== null && asked.sheet !== '' && <Compared key={asked.press} other={asked.sheet} mine={mine} />}
35	    </div>
36	  );
37	}
38	
39	function Compared({ other, mine }: { other: string; mine: GradeDue }) {
40	  const { data } = useQuery({
41	    queryKey: ['sheet-exists', other],
42	    queryFn: () => getJson<{ exists: boolean }>(`/api/sheets/${encodeURIComponent(other)}/exists`),
43	    staleTime: 0,
44	    gcTime: 0,
45	  });
46	  if (data === undefined || !data.exists) return null;
47	  return <OtherLines other={other} mine={mine} />;
48	}
49	
50	function OtherLines({ other, mine }: { other: string; mine: GradeDue }) {
51	  const [sheet] = useSearchParam('sheet', asString);
52	  const grades = useGradeCodes(sheet);
53	  const { people, today, totalOf } = useSheetFigures(other);
54	  const fetching = useIsFetching({ queryKey: ['sheet', other] });
55	  if (fetching > 0 || today === undefined) return null;
56	  const theirs = gradeDueOf(people, today, totalOf);
57	  return (
58	    <ul>
59	      {grades.map((g) => (
60	        <li key={g} data-testid="compare-line">
61	          {g} {formatCents(mine(g))} {formatCents(theirs(g))}
62	        </li>
63	      ))}
64	    </ul>
65	  );
66	}
