1	import { asString, useSearchParam } from '../../url/useSearchParam';
2	import { useDescendants } from '../consolidated/useDescendants';
3	import { useSheetFigures } from '../people/useSheetFigures';
4	import { useSettings } from '../settings/useSettings';
5	import { useRealSheetToday } from '../sheet/useSheetToday';
6	
7	type Counts = { pending: number; review: number; overdue: number };
8	
9	// The steward's dashboard: over the sheet and all its descendants, how many claims are PENDING and
10	// how many REVIEW (as each sheet's header counts them), and how many claims that count are overdue
11	// (as each sheet's overdue-total adds them up, on its own today), added up. Only a steward of the
12	// sheet sees the counts — the role set, or a delegation covering the sheet's today, as the server
13	// judges it; anyone else sees the cells empty. Under an as-of date the settings, claims and today are
14	// those as they stood then, so the counts and the role are the ones of then.
15	export function StewardDashboard() {
16	  const [sheet] = useSearchParam('sheet', asString);
17	  const [user] = useSearchParam('user', asString);
18	  const settings = useSettings(sheet);
19	  const today = useRealSheetToday(sheet);
20	  const descendants = useDescendants(sheet);
21	  const steward =
22	    settings !== undefined &&
23	    (settings.roles.some((r) => r.user === user && r.role === 'steward') ||
24	      settings.delegations.some((d) => d.user === user && today !== undefined && d.from <= today && today <= d.to));
25	  return <Add sheets={[sheet, ...descendants]} counts={{ pending: 0, review: 0, overdue: 0 }} steward={steward} />;
26	}
27	
28	// Adds the first sheet's counts and passes on to the rest: one sheet's hooks per component, so the
29	// number of sheets can change.
30	function Add({ sheets, counts, steward }: { sheets: string[]; counts: Counts; steward: boolean }) {
31	  if (sheets.length === 0) return <Shown counts={counts} steward={steward} />;
32	  return <AddSheet key={sheets[0]} sheets={sheets} counts={counts} steward={steward} />;
33	}
34	
35	function AddSheet({ sheets, counts, steward }: { sheets: string[]; counts: Counts; steward: boolean }) {
36	  const { statusCount, overdue } = useSheetFigures(sheets[0]);
37	  return (
38	    <Add
39	      sheets={sheets.slice(1)}
40	      steward={steward}
41	      counts={{
42	        pending: counts.pending + statusCount('PENDING'),
43	        review: counts.review + statusCount('REVIEW'),
44	        overdue: counts.overdue + overdue.length,
45	      }}
46	    />
47	  );
48	}
49	
50	function Shown({ counts, steward }: { counts: Counts; steward: boolean }) {
51	  return (
52	    <section data-testid="dashboard">
53	      Steward: pending <span data-testid="dash-pending-count">{steward ? counts.pending : ''}</span>
54	      {', '}review <span data-testid="dash-review-count">{steward ? counts.review : ''}</span>
55	      {', '}overdue <span data-testid="dash-overdue-count">{steward ? counts.overdue : ''}</span>
56	    </section>
57	  );
58	}
