1	import { useState } from 'react';
2	import { isOpen, useClaims } from '../claims/useClaims';
3	import { useGrace } from '../claims/useGrace';
4	import { gradeOn, usePeople } from '../people/usePeople';
5	import { useGradeCodes } from '../grades/useGrades';
6	import { useFloor, useLatePct, usePolicy } from '../settings/useSettings';
7	import { useSheetToday } from '../sheet/useSheetToday';
8	import { asString, useSearchParam } from '../../url/useSearchParam';
9	import { claimDue, formatCents } from './due';
10	import { claimRate, useRates } from './useRates';
11	
12	const PCT = /^\d+(\.\d{1,2})?$/;
13	
14	// A what-if on a grade's rate: how many OPEN and PENDING claims of people on the grade (the one in force
15	// on the claim's date) would show a different due if the candidate rate applied to it on every date, and
16	// the sum of new due minus current due. Worked here with the same figures the claim rows show, so a
17	// claim bound by a statement (or settled, which is left out) never moves. Nothing is saved.
18	export function RatePreview() {
19	  const [sheet] = useSearchParam('sheet', asString);
20	  const grades = useGradeCodes(sheet);
21	  const people = usePeople(sheet);
22	  const claims = useClaims(sheet);
23	  const rates = useRates(sheet);
24	  const today = useSheetToday(sheet);
25	  const floor = useFloor(sheet);
26	  const grace = useGrace(sheet);
27	  const late = { pct: useLatePct(sheet), today, grace };
28	  const policy = usePolicy(sheet);
29	  const [grade, setGrade] = useState<string>('A');
30	  const [pct, setPct] = useState('');
31	  const [result, setResult] = useState<{ count: number; diff: string } | null>(null);
32	  const [error, setError] = useState(false);
33	  const changed = () => {
34	    setResult(null);
35	    setError(false);
36	  };
37	  const preview = () => {
38	    const candidate = pct.trim();
39	    if (!PCT.test(candidate)) {
40	      setError(true);
41	      return;
42	    }
43	    const byId = new Map(people.map((p) => [p.id, p]));
44	    let count = 0;
45	    let diff = 0n;
46	    for (const c of claims) {
47	      const person = byId.get(c.personId);
48	      if (person === undefined || !isOpen(c) || gradeOn(person, c.date) !== grade) continue;
49	      const current = claimDue(c, claimRate(rates, grade, c), floor, late, policy);
50	      const next = claimDue(c, candidate, floor, late, policy);
51	      if (current === next) continue;
52	      count++;
53	      diff += (next ?? 0n) - (current ?? 0n);
54	    }
55	    setResult({ count, diff: formatCents(diff) });
56	  };
57	  return (
58	    <form
59	      data-testid="rate-preview-form"
60	      onSubmit={(e) => {
61	        e.preventDefault();
62	        changed();
63	        // The old count is gone while the preview is worked, so two presses with the same result differ.
64	        setTimeout(preview, 0);
65	      }}
66	    >
67	      <select
68	        data-testid="rate-preview-grade"
69	        value={grade}
70	        onChange={(e) => {
71	          setGrade(e.target.value);
72	          changed();
73	        }}
74	      >
75	        {grades.map((g) => (
76	          <option key={g} value={g}>{g}</option>
77	        ))}
78	      </select>{' '}
79	      <input
80	        data-testid="rate-preview-pct"
81	        value={pct}
82	        placeholder="Candidate rate %"
83	        onChange={(e) => {
84	          setPct(e.target.value);
85	          changed();
86	        }}
87	      />{' '}
88	      <button type="submit" data-testid="rate-preview">Preview</button>
89	      {result !== null && (
90	        <span>
91	          {' '}Would change <span data-testid="rate-preview-count">{result.count}</span> claim(s) by{' '}
92	          <span data-testid="rate-preview-diff">{result.diff}</span>
93	        </span>
94	      )}
95	      {error && <span data-testid="rate-preview-error" role="alert"> Could not preview: the rate must be a percent of 0.00 or more with at most two decimals.</span>}
96	    </form>
97	  );
98	}
