22	  const key = (name: string) => name.trim().toLowerCase();
23	  const me = user === '' ? undefined : people.find((p) => [p.name, ...p.aliases].some((n) => key(n) === key(user)));
24	  const led = me ? crews.filter((c) => c.leadId === me.id) : [];
25	  const watched = useWatches(sheet, user);
26	  const watchedTotal = formatCents(
27	    watched.reduce((sum, id) => {
28	      const person = byId.get(id);
29	      const due = person === undefined ? null : totalOf(person);
30	      return due === null ? sum : sum + due;
31	    }, 0n),
32	  );
33	  const crewTotal = led.length === 0 ? '' : formatCents(led.reduce((sum, c) => sum + crewDueCents(c, byId, totalOf), 0n));
34	  return (
35	    <header data-testid="header">
36	      People: <span data-testid="header-people-count">{people.length}</span>
