 19	/** The person's timeline: one line per dated thing about them, by date, and on one date their grade changes, then
 20	 *  their claims, then holds, then retirements, then unretirements, each kind by its line's text:
 21	 *  "<date> grade <grade>", "<date> claim <amount> <status>", "<date> hold [to <date>]", "<date> retired",
 22	 *  "<date> unretired". The grade from the beginning of time has no date and no line. */
 23	export function timelineOf(person: Person, claims: Claim[]): string[] {
 24	  const entries: { date: string; kind: number; seq: number; line: string }[] = [];
 25	  const add = (date: string, kind: number, line: string) => entries.push({ date, kind, seq: entries.length, line: `${date} ${line}` });
 26	  for (const g of person.grades) if (g.from !== '') add(g.from, 0, `grade ${g.grade}`);
 27	  for (const c of claims.filter((c) => c.personId === person.id)) add(c.date, 1, `claim ${formatCents(toCents(c.amount))} ${c.status}`);
 28	  for (const h of person.holds) add(h.from, 2, h.to === '' ? 'hold' : `hold to ${h.to}`);
 29	  const unretired: string[] = [];
 30	  for (const r of person.retirements ?? []) {
 31	    const [from, to] = r.split(' to ');
 32	    add(from, 3, 'retired');
 33	    unretired.push(to);
 34	  }
 35	  if (person.retired && person.retiredFrom !== '') add(person.retiredFrom, 3, 'retired');
 36	  for (const to of unretired) add(to, 4, 'unretired');
 37	  entries.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.kind - b.kind || (a.line < b.line ? -1 : a.line > b.line ? 1 : a.seq - b.seq)));
 38	  return entries.map((e) => e.line);
 39	}
