 44	/** The due-total of the person's SNAPSHOT taken when the sheet's today was changed away from the date (the
 45	 *  latest when there are several); "" when there is none. */
 46	function snapshotOn(person: Person, date: string): string {
 47	  let found = '';
 48	  for (const line of person.snapshots ?? []) {
 49	    const at = line.indexOf(' ');
 50	    if (line.slice(0, at) === date) found = line.slice(at + 1);
 51	  }
 52	  return found;
 53	}
