 55	// Compares two snapshot dates: per person in list order, "<name> <then> <now>" — then the snapshot for the
 56	// from-date, now the snapshot for the to-date or, with the to-date blank, the person's due-total now. Each
 57	// line is trimmed, so an empty figure leaves no trailing space.
 58	export function SnapshotCompare({ people, totalOf }: { people: Person[]; totalOf: (p: Person) => bigint | null }) {
