 63	    asked === null
 64	      ? []
 65	      : people.map((p) =>
 66	          [p.name, snapshotOn(p, asked.from), asked.to === '' ? showDue(totalOf(p)) : snapshotOn(p, asked.to)]
 67	            .join(' ')
 68	            .trim(),
 69	        );
 70	  return (
 71	    <div>
 72	      From <input type="date" data-testid="snapshot-from" value={from} onChange={(e) => setFrom(e.target.value)} /> to{' '}
