 95	// Shows the active sheet's today and changes it. A blank date resets it to the real date.
 96	// Also shows whether the sheet is archived, and archives it (a steward only), and its parent sheet (nothing when none),
 97	// and clones it to another id never used (a steward only), showing the id cloned to once done.
 98	export function SheetToday() {
 99	  const [sheet] = useSearchParam('sheet', asString);
100	  const [user] = useSearchParam('user', asString);
101	  const today = useRealSheetToday(sheet);
102	  const archived = useSheetArchived(sheet);
103	  const settings = useSettings(sheet);
104	  const [date, setDate] = useState('');
105	  const [cloneTo, setCloneTo] = useState('');
106	  const queryClient = useQueryClient();
107	  const submitOnce = useSubmitOnce();
108	  const save = useMutation({
109	    mutationFn: (value: string) =>
110	      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today: value, user }),
111	    onSuccess: (saved) => {
112	      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
113	      // Everything on the sheet may depend on its date: re-read it all.
114	      void queryClient.invalidateQueries({ queryKey: ['sheet', saved.sheet] });
115	    },
116	  });
117	  const archive = useMutation({
118	    mutationFn: () =>
119	      postJson<SheetTodayDto>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
120	    onSuccess: (saved) => {
121	      queryClient.setQueryData(sheetTodayKey(saved.sheet), saved);
122	    },
123	  });
124	  const clone = useMutation({
125	    mutationFn: (to: string) =>
126	      postJson<{ sheet: string; toSheet: string }>(`/api/sheets/${encodeURIComponent(sheet)}/clone`, { toSheet: to, user }),
127	  });
128	  const resetAll = () => {
129	    save.reset();
130	    archive.reset();
131	    clone.reset();
132	  };
133	  const { reset: resetClone } = clone;
134	  // A clone made from another sheet is not this one's.
135	  useEffect(() => resetClone(), [sheet, resetClone]);
136	  return (
137	    <form
138	      data-testid="sheet-today-form"
139	      onSubmit={(e) => {
140	        e.preventDefault();
141	        archive.reset();
142	        clone.reset();
143	        submitOnce(() => save.mutateAsync(date.trim()));
144	      }}
145	    >
146	      Today: <span data-testid="sheet-today">{today ?? ''}</span>{' '}
147	      <input
148	        type="date"
149	        data-testid="sheet-today-input"
150	        value={date}
151	        onChange={(e) => {
152	          setDate(e.target.value);
153	          resetAll();
154	        }}
155	      />
156	      <button type="submit" data-testid="sheet-today-save">Set today</button>
157	      {' '}Parent: <span data-testid="sheet-parent">{settings?.parent ?? ''}</span>
158	      {' '}Archived: <span data-testid="sheet-archived">{archived === undefined ? '' : archived ? 'yes' : 'no'}</span>{' '}
159	      <button
160	        type="button"
161	        data-testid="sheet-archive"
162	        onClick={() => {
163	          resetAll();
164	          submitOnce(() => archive.mutateAsync());
165	        }}
166	      >
167	        Archive sheet
168	      </button>
169	      {' '}Clone to:{' '}
170	      <input
171	        data-testid="sheet-clone-to"
172	        value={cloneTo}
173	        onChange={(e) => {
174	          setCloneTo(e.target.value);
175	          resetAll();
176	        }}
177	      />
178	      <button
179	        type="button"
180	        data-testid="sheet-clone"
181	        onClick={() => {
182	          resetAll();
183	          submitOnce(() => clone.mutateAsync(cloneTo.trim()));
184	        }}
185	      >
186	        Clone sheet
187	      </button>{' '}
188	      <span data-testid="sheet-cloned-to">{clone.data?.toSheet ?? ''}</span>
189	      {save.isError && <span data-testid="sheet-error" role="alert"> Could not change today.</span>}
190	      {archive.isError && <span data-testid="sheet-error" role="alert"> Could not archive the sheet.</span>}
191	      {clone.isError && <span data-testid="sheet-error" role="alert"> Could not clone the sheet.</span>}
192	    </form>
193	  );
194	}

