87	    /** The people on the sheet by the end of the date, each as they stood then, in list order (by place). */
88	    public List<PersonResponse> people(String sheetId, LocalDate date) {
89	        Date end = Date.valueOf(date);
90	        List<Person> found = new ArrayList<>();
91	        for (Person now : people.list(sheetId)) {
92	            if (now.getAddedOn() == null || !now.getAddedOn().isAfter(date)) found.add(now);
93	        }
94	        // Those merged away since still stood on the sheet.
95	        for (Person merged : people.mergedAfter(sheetId, date)) {
96	            if (merged.getAddedOn() == null || !merged.getAddedOn().isAfter(date)) found.add(merged);
97	        }
98	        found.sort(Comparator.comparingLong(Person::getPlace).thenComparingLong(Person::getId));
99	        Map<Long, Person> byId = new LinkedHashMap<>();
100	        for (Person now : found) {
101	            Person then = new Person(now.getId(), sheetId, now.getName(), now.getGrades().get(now.getGrades().firstKey()),
102	                    now.getVersion());
103	            then.setTerms(now.getTerms());
104	            then.setContact(now.getContact());
105	            // A person's tags are not kept in their history: they show as they are now.
106	            then.setTags(now.getTags());
107	            // Nor are their dated terms: those recorded from a date show as they are now.
108	            then.setDatedTerms(now.getDatedTerms());
109	            byId.put(now.getId(), then);
110	        }
111	        jdbc.query("SELECT person_id, name, terms, contact FROM person_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
112	                (RowCallbackHandler) rs -> {
113	                    Person then = byId.get(rs.getLong(1));
114	                    if (then == null) return;
115	                    then.setName(rs.getString(2));
116	                    int terms = rs.getInt(3);
117	                    then.setTerms(rs.wasNull() ? null : terms);
118	                    then.setContact(rs.getString(4));
119	                }, sheetId, end);
120	        Map<Long, Map<LocalDate, String>> grades = new HashMap<>();
121	        jdbc.query("SELECT person_id, from_date, grade FROM grade_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
122	                (RowCallbackHandler) rs -> {
123	                    LocalDate from = local(rs.getDate(2));
124	                    grades.computeIfAbsent(rs.getLong(1), k -> new LinkedHashMap<>())
125	                            .put(from == null ? Person.BEGINNING : from, rs.getString(3));
126	                }, sheetId, end);
127	        Map<Long, List<Person.Hold>> holds = new HashMap<>();
128	        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
129	                (RowCallbackHandler) rs -> holds.computeIfAbsent(rs.getLong(1), k -> new ArrayList<>())
130	                        .add(new Person.Hold(rs.getDate(2).toLocalDate(), local(rs.getDate(3)))), sheetId, end);
131	        Map<Long, List<Person.Retirement>> retirements = new HashMap<>();
132	        jdbc.query("SELECT person_id, from_date, to_date FROM person_retirement WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
133	                (RowCallbackHandler) rs -> retirements.computeIfAbsent(rs.getLong(1), k -> new ArrayList<>())
134	                        .add(new Person.Retirement(rs.getDate(2).toLocalDate(), rs.getDate(3).toLocalDate())), sheetId, end);
135	        // A snapshot is taken on the day the sheet moves to (dated the day it left): one taken after the date was not yet
136	        // taken at its end (a line kept without that day: taken once its own day was left).
137	        Map<Long, List<String>> snapshots = new HashMap<>();
138	        jdbc.query("SELECT person_id, set_on, due_total FROM person_snapshot WHERE sheet_id = ?"
139	                + " AND (taken_on <= ? OR (taken_on IS NULL AND set_on < ?)) ORDER BY seq",
140	                (RowCallbackHandler) rs -> snapshots.computeIfAbsent(rs.getLong(1), k -> new ArrayList<>())
141	                        .add(rs.getDate(2).toLocalDate() + " " + rs.getString(3)), sheetId, end, end);
142	        Map<Long, LocalDate> retired = new HashMap<>();
143	        jdbc.query("SELECT person_id, retired_from FROM retire_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
144	                (RowCallbackHandler) rs -> retired.put(rs.getLong(1), local(rs.getDate(2))), sheetId, end);
145	        // The statements taken by the end of the date and not cancelled by then: how many, and the last one's figures.
146	        // (A statement a merge or a transfer brought over counts, and shows among the lines, but is never the last one.)
147	        Map<Long, Integer> statementCount = new HashMap<>();
148	        jdbc.query("SELECT person_id, stated_total, statement_date, brought FROM person_statement WHERE sheet_id = ?" + UP_TO
149	                + " AND NOT (cancelled AND cancelled_on <= ?) ORDER BY seq", (RowCallbackHandler) rs -> {
150	                    Person then = byId.get(rs.getLong(1));
151	                    if (then == null) return;
152	                    statementCount.merge(then.getId(), 1, Integer::sum);
153	                    if (rs.getBoolean(4)) return;
154	                    then.setStatedTotal(rs.getBigDecimal(2));
155	                    then.setStatementDate(local(rs.getDate(3)));
156	                }, sheetId, end, end);
157	        Map<Long, List<String>> statements = new HashMap<>();
158	        jdbc.query("SELECT person_id, statement_date, stated_total FROM person_statement WHERE sheet_id = ?" + UP_TO
159	                + " AND NOT (cancelled AND cancelled_on <= ?) ORDER BY set_on NULLS FIRST, seq",
160	                (RowCallbackHandler) rs -> statements.computeIfAbsent(rs.getLong(1), k -> new ArrayList<>())
161	                        .add(Person.statementLine(rs.getDate(2), rs.getBigDecimal(3))), sheetId, end, end);
162	        Map<Long, List<Long>> patrons = new HashMap<>();
163	        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
164	                (RowCallbackHandler) rs -> patrons.computeIfAbsent(rs.getLong(1), k -> new ArrayList<>()).add(rs.getLong(2)),
165	                sheetId, end);
166	        Map<Long, List<String>> aliases = new HashMap<>();
167	        jdbc.query("SELECT person_id, alias FROM person_alias WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
168	                (RowCallbackHandler) rs -> aliases.computeIfAbsent(rs.getLong(1), k -> new ArrayList<>()).add(rs.getString(2)),
169	                sheetId, end);
170	        for (Person then : byId.values()) {
171	            List<String> aliasNames = new ArrayList<>(aliases.getOrDefault(then.getId(), List.of()));
172	            aliasNames.sort(BY_NAME);
173	            then.setAliases(aliasNames);
174	            then.setGrades(grades.getOrDefault(then.getId(), Map.of()));
175	            then.setToday(date);
176	            then.setHolds(new ArrayList<>(holds.getOrDefault(then.getId(), List.of())));
177	            then.setRetiredFrom(retired.get(then.getId()));
178	            then.setRetirements(new ArrayList<>(retirements.getOrDefault(then.getId(), List.of())));
179	            then.setSnapshots(new ArrayList<>(snapshots.getOrDefault(then.getId(), List.of())));
180	            then.setStatementCount(statementCount.getOrDefault(then.getId(), 0));
181	            then.setStatements(new ArrayList<>(statements.getOrDefault(then.getId(), List.of())));
182	            List<Long> ids = new ArrayList<>();
183	            List<String> names = new ArrayList<>();
184	            for (Long patronId : patrons.getOrDefault(then.getId(), List.of())) {
185	                Person patron = byId.get(patronId);
186	                if (patron == null) continue;
187	                ids.add(patronId);
188	                names.add(patron.getName());
189	            }
190	            names.sort(BY_NAME);
191	            then.setPatrons(ids, names);
192	        }
193	        return PersonResponse.from(new ArrayList<>(byId.values()));
194	    }
