196	    /** The claims on the sheet by the end of the date, each as it stood then (its log as written by then), newest first. */
197	    public List<ClaimResponse> claims(String sheetId, LocalDate date) {
198	        Map<Long, Claim> now = new LinkedHashMap<>();
199	        // Those transferred away since still stood on the sheet.
200	        claims.listWithTransferredAfter(sheetId, date).forEach(claim -> now.put(claim.getId(), claim));
201	        Map<Long, Claim> latest = then(sheetId, date, now);
202	        List<ClaimResponse> shown = new ArrayList<>();
203	        for (Claim current : now.values()) {
204	            Claim then = latest.get(current.getId());
205	            if (then == null) continue;
206	            then.setCorrectedDate(claims.correctedDate(sheetId, then.getPersonId(), then.getCorrects()));
207	            List<String> log = new ArrayList<>();
208	            for (String line : current.getLog()) {
209	                java.util.regex.Matcher on = LOG_DATE.matcher(line);
210	                if (!on.find() || !LocalDate.parse(on.group(1)).isAfter(date)) log.add(line);
211	            }
212	            then.setLog(log);
213	            then.setComments(current.getComments().stream().filter(comment -> !comment.date().isAfter(date)).toList());
214	            then.setShares(current.getShares().stream().filter(share -> !share.sharedOn().isAfter(date)).toList());
215	            shown.add(ClaimResponse.from(then));
216	        }
217	        return shown;
218	    }
