220	    /** The claims as they stood at the end of the date, by id, built from their history (see V45) over the claims as they
221	     *  are now; a claim with no history by then is left out. */
222	    private Map<Long, Claim> then(String sheetId, LocalDate date, Map<Long, Claim> now) {
223	        Date end = Date.valueOf(date);
224	        Map<Long, Claim> latest = new HashMap<>();
225	        jdbc.query("SELECT * FROM claim_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq", (RowCallbackHandler) rs -> {
226	            Claim current = now.get(rs.getLong("claim_id"));
227	            if (current == null) return;
228	            String note = rs.getString("note");
229	            Claim then = new Claim(current.getId(), sheetId, rs.getLong("person_id"), rs.getBigDecimal("amount"),
230	                    rs.getDate("claim_date").toLocalDate(), note == null ? current.getNote() : note,
231	                    ClaimStatus.valueOf(rs.getString("status")), rs.getString("claim_number"),
232	                    rs.getBigDecimal("settled_due"), rs.getString("opened_by"));
233	            then.setStated(rs.getBoolean("stated"));
234	            then.setStatedDue(rs.getBigDecimal("stated_due"));
235	            LocalDate dueBy = local(rs.getDate("due_by"));
236	            then.setDueBy(dueBy == null ? then.getDate() : dueBy);
237	            then.setDeferredUntil(local(rs.getDate("deferred_until")));
238	            then.setCorrects(rs.getString("corrects"));
239	            int proofs = rs.getInt("proofs");
240	            then.setProofs(rs.wasNull() ? current.getProofs() : proofs);
241	            int photos = rs.getInt("proof_photos");
242	            then.setProofPhotos(rs.wasNull() ? current.getProofPhotos() : photos);
243	            then.setSplitFrom(rs.getString("split_from"));
244	            then.setLateEntry(rs.getBoolean("late_entry"));
245	            then.setWaived(rs.getBoolean("waived"));
246	            then.setHeld(rs.getBoolean("held"));
247	            int batch = rs.getInt("settle_batch");
248	            then.setSettleBatch(rs.wasNull() ? null : batch);
249	            // A claim's ref and tags are not kept in its history: they show as they are now.
250	            then.setRef(current.getRef());
251	            then.setTags(current.getTags());
252	            then.setRateMark(current.getRateMark());
253	            // Nor is its reminded date: it shows its last reminder when that was by the date.
254	            LocalDate reminded = current.getRemindedOn();
255	            then.setRemindedOn(reminded != null && !reminded.isAfter(date) ? reminded : null);
256	            // Nor is its void reason: a claim void by then shows the reason it was voided with.
257	            if (then.getStatus() == ClaimStatus.VOID) then.setVoidReason(current.getVoidReason());
258	            latest.put(then.getId(), then);
259	        }, sheetId, end);
260	        return latest;
261	    }
