263	    /** The claim as it stood at the end of the date; null when it was not on the sheet by then. */
264	    public Claim claim(String sheetId, long claimId, LocalDate date) {
265	        Map<Long, Claim> now = new LinkedHashMap<>();
266	        claims.listWithTransferredAfter(sheetId, date).stream().filter(claim -> claim.getId() == claimId)
267	                .forEach(claim -> now.put(claim.getId(), claim));
268	        Claim then = then(sheetId, date, now).get(claimId);
269	        if (then != null) then.setCorrectedDate(claims.correctedDate(sheetId, then.getPersonId(), then.getCorrects()));
270	        return then;
271	    }
