273	    /** A claim's due as shown at the end of the date, the claim as it stood then (see {@link #claim}): fixed (settled or
274	     *  bound), else its amount at the rate in force on its date for its person's grade then, with its late charge as of the
275	     *  date and raised to the floor, each by the rates and settings as they stood then; null for n/a. */
276	    public BigDecimal due(Claim then, LocalDate date) {
277	        String sheetId = then.getSheetId();
278	        String grade = gradeOn(sheetId, then.getPersonId(), then.getDate(), date);
279	        java.math.RoundingMode rounding = net.officefloor.hq.app.claim.Rounding.of(then, policyDate(sheetId, date),
280	                on -> net.officefloor.hq.app.claim.Rounding.mode(dated(sheetId, ValidateSetting.ROUNDING, on, date)));
281	        BigDecimal fixed = ClaimResponse.fixedDue(then);
282	        BigDecimal figure = fixed != null || then.isBound() ? fixed
283	                : Rates.due(then.getAmount(), rate(sheetId, grade, then.getDate(), then.getRateMark(), date), rounding);
284	        BigDecimal floor = dated(sheetId, ValidateSetting.FLOOR, then.getDate(), date);
285	        BigDecimal grace = grade == null ? null : dated(sheetId, ValidateSetting.GRADE_GRACE + grade, then.getDate(), date);
286	        return net.officefloor.hq.app.claim.LateCharge.due(then, figure, floor == null ? Settings.START_FLOOR : floor,
287	                on -> {
288	                    BigDecimal pct = dated(sheetId, ValidateSetting.LATE_PCT, on, date);
289	                    return pct == null ? Settings.START_LATE_PCT : pct;
290	                }, date, rounding, grace == null ? 0 : grace.intValue());
291	    }
