294	    private String gradeOn(String sheetId, long personId, LocalDate on, LocalDate date) {
295	        TreeMap<LocalDate, String> grades = new TreeMap<>();
296	        jdbc.query("SELECT from_date, grade FROM grade_history WHERE sheet_id = ? AND person_id = ?" + UP_TO + " ORDER BY seq",
297	                (RowCallbackHandler) rs -> {
298	                    LocalDate from = local(rs.getDate(1));
299	                    grades.put(from == null ? Person.BEGINNING : from, rs.getString(2));
300	                }, sheetId, personId, Date.valueOf(date));
301	        if (grades.isEmpty()) return people.find(sheetId, personId).gradeOn(on);
302	        Map.Entry<LocalDate, String> found = grades.floorEntry(on);
303	        return found == null ? grades.firstEntry().getValue() : found.getValue();
304	    }
