307	    private BigDecimal dated(String sheetId, String key, LocalDate on, LocalDate date) {
308	        List<BigDecimal> found = jdbc.query("SELECT setting_value FROM setting_history WHERE sheet_id = ? AND setting_key = ?"
309	                + " AND from_date <= ?" + UP_TO + " ORDER BY from_date DESC, seq DESC LIMIT 1", (rs, i) -> rs.getBigDecimal(1),
