315	    private LocalDate policyDate(String sheetId, LocalDate date) {
316	        List<LocalDate> policies = new ArrayList<>();
317	        jdbc.query("SELECT policy_date FROM policy_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
318	                (RowCallbackHandler) rs -> policies.add(local(rs.getDate(1))), sheetId, Date.valueOf(date));
