323	    /** The rate for a grade in force on a day for a claim with a mark, by the rates as set by the end of the date on the
324	     *  sheet, else on its ancestors then (as {@link Rates#find(String, String, LocalDate, long)} does live). */
325	    private BigDecimal rate(String sheetId, String grade, LocalDate on, long claimMark, LocalDate date) {
326	        if (grade == null) return null;
327	        List<String> asked = new ArrayList<>(List.of(sheetId));
328	        asked.addAll(ancestors(sheetId, date));
329	        for (String at : asked) {
330	            List<Object[]> found = jdbc.query("SELECT rate, to_date, after_mark FROM rate_history WHERE sheet_id = ?"
331	                    + " AND TRIM(grade) = ? AND (from_date IS NULL OR from_date <= ?)" + UP_TO
332	                    + " ORDER BY from_date DESC NULLS LAST, seq DESC",
333	                    (rs, i) -> new Object[] { rs.getBigDecimal(1), rs.getDate(2), rs.getLong(3) },
334	                    at, grade.trim(), Date.valueOf(on), Date.valueOf(date));
335	            for (Object[] row : found) {
336	                if (Rates.applies((Long) row[2], claimMark)) {
337	                    Date to = (Date) row[1];
338	                    BigDecimal rate = to != null && to.toLocalDate().isBefore(on) ? null : (BigDecimal) row[0];
339	                    if (rate != null) return rate;
340	                    break;
341	                }
342	            }
343	        }
344	        return null;
345	    }
