349	    /** The rates set by the end of the date, by grade then from-date (from the beginning of time first). */
350	    public List<RateResponse> rates(String sheetId, LocalDate date) {
351	        Map<String, TreeMap<LocalDate, RateResponse>> byGrade = new TreeMap<>();
352	        jdbc.query("SELECT grade, rate, from_date, to_date, after_mark FROM rate_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
353	                (RowCallbackHandler) rs -> {
354	                    LocalDate from = local(rs.getDate(3));
355	                    LocalDate to = local(rs.getDate(4));
356	                    String grade = rs.getString(1).trim();
357	                    TreeMap<LocalDate, RateResponse> byFrom = byGrade.computeIfAbsent(grade, g -> new TreeMap<>());
358	                    LocalDate key = from == null ? LocalDate.MIN : from;
359	                    RateResponse replaced = byFrom.get(key);
360	                    List<RateResponse.Earlier> earlier = new ArrayList<>();
361	                    if (replaced != null) {
362	                        earlier.add(new RateResponse.Earlier(replaced.rate(), replaced.to(), replaced.afterMark()));
363	                        earlier.addAll(replaced.earlier());
364	                    }
365	                    byFrom.put(key, new RateResponse(grade, rs.getBigDecimal(2).setScale(2).toPlainString(),
366	                            from == null ? "" : from.toString(), to == null ? "" : to.toString(),
367	                            replaced == null ? 1 : replaced.version() + 1, rs.getLong(5), earlier));
368	                }, sheetId, Date.valueOf(date));
369	        List<RateResponse> rates = new ArrayList<>();
370	        byGrade.values().forEach(byFrom -> rates.addAll(byFrom.values()));
371	        return rates;
372	    }
