382	    private String parentOn(String sheetId, LocalDate date) {
383	        List<String> set = jdbc.query("SELECT setting_value FROM plain_setting_history WHERE sheet_id = ? AND setting_key = ?"
384	                + UP_TO + " ORDER BY seq", (rs, i) -> rs.getString(1), sheetId, Settings.PARENT, Date.valueOf(date));
385	        if (!set.isEmpty()) {
386	            String last = set.get(set.size() - 1);
387	            return last.isBlank() ? null : last;
388	        }
389	        Integer recorded = jdbc.queryForObject("SELECT COUNT(*) FROM plain_setting_history WHERE sheet_id = ? AND setting_key = ?",
390	                Integer.class, sheetId, Settings.PARENT);
391	        return recorded != null && recorded > 0 ? null : sheets.parent(sheetId);
392	    }
