394	    /** The periods added by the end of the date, by from-date, each closed (or soft-closed) and locked as it stood then. */
395	    public List<PeriodResponse> periods(String sheetId, LocalDate date) {
396	        Date end = Date.valueOf(date);
397	        Map<String, Date> addedOn = new HashMap<>();
398	        jdbc.query("SELECT name, added_on FROM period WHERE sheet_id = ?", (RowCallbackHandler) rs -> addedOn.put(
399	                rs.getString(1), rs.getDate(2)), sheetId);
400	        Map<String, PeriodResponse> byName = new LinkedHashMap<>();
401	        for (PeriodResponse now : periods.list(sheetId)) {
402	            Date added = addedOn.get(now.name());
403	            if (added != null && added.toLocalDate().isAfter(date)) continue;
404	            byName.put(now.name(), new PeriodResponse(now.name(), now.from(), now.to(), false, "", new LinkedHashMap<>(), false, now.cap(),
405	                    new LinkedHashMap<>(), false, now.addedOrder()));
406	        }
407	        Map<String, Boolean> locked = new HashMap<>();
408	        jdbc.query("SELECT name, locked FROM period_lock_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
409	                (RowCallbackHandler) rs -> locked.put(rs.getString(1), rs.getBoolean(2)), sheetId, end);
410	        jdbc.query("SELECT name, closed, soft_closed, closed_total, person_totals, person_carried FROM period_history WHERE sheet_id = ?"
411	                + UP_TO + " ORDER BY seq", (RowCallbackHandler) rs -> {
412	                    PeriodResponse was = byName.get(rs.getString(1));
413	                    if (was == null) return;
414	                    BigDecimal total = rs.getBigDecimal(4);
415	                    byName.put(was.name(), new PeriodResponse(was.name(), was.from(), was.to(), rs.getBoolean(2),
416	                            total == null ? "" : total.setScale(2).toPlainString(), byPerson(rs.getString(5)), rs.getBoolean(3),
417	                            was.cap(), byPerson(rs.getString(6)), false, was.addedOrder()));
418	                }, sheetId, end);
419	        byName.replaceAll((name, was) -> !locked.getOrDefault(name, false) ? was : new PeriodResponse(was.name(), was.from(), was.to(),
420	                was.closed(), was.closedTotal(), was.closedPersonTotals(), was.softClosed(), was.cap(), was.closedPersonCarried(), true,
421	                was.addedOrder()));
422	        return new ArrayList<>(byName.values());
423	    }
