436	    /** The settings as they stood at the end of the date, each dated one as in force on it (see {@link Settings#load}). */
437	    public SettingsResponse settings(String sheetId, LocalDate date) {
438	        sheets.today(sheetId);
439	        Date end = Date.valueOf(date);
440	        // The dated settings: the latest recorded for each key and from-date.
441	        Map<String, TreeMap<LocalDate, BigDecimal[]>> dated = new TreeMap<>();
442	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_history WHERE sheet_id = ?" + UP_TO
443	                + " ORDER BY seq", (RowCallbackHandler) rs -> dated.computeIfAbsent(rs.getString(1), k -> new TreeMap<>())
444	                        .put(rs.getDate(2).toLocalDate(), new BigDecimal[] { rs.getBigDecimal(3) }), sheetId, end);
445	        java.util.function.Function<String, BigDecimal> on = key -> {
446	            Map.Entry<LocalDate, BigDecimal[]> found = dated.getOrDefault(key, new TreeMap<>()).floorEntry(date);
447	            return found == null ? null : found.getValue()[0];
448	        };
449	        Map<String, List<DatedValue>> datedShown = new TreeMap<>();
450	        dated.forEach((key, byFrom) -> byFrom.forEach((from, value) -> datedShown.computeIfAbsent(key, k -> new ArrayList<>())
451	                .add(new DatedValue(from.toString(), value[0] == null ? "" : ValidateSetting.ROUNDING.equals(key)
452	                        ? net.officefloor.hq.app.claim.Rounding.name(value[0]) : key.startsWith("terms")
453	                        ? String.valueOf(value[0].intValue()) : value[0].setScale(2).toPlainString()))));
454	        BigDecimal limit = on.apply(ValidateSetting.CLERK_LIMIT);
455	        BigDecimal cap = on.apply(ValidateSetting.CAP);
456	        BigDecimal threshold = on.apply(ValidateSetting.PROOF_THRESHOLD);
457	        BigDecimal noteThreshold = on.apply(ValidateSetting.NOTE_THRESHOLD);
458	        BigDecimal reviewThreshold = on.apply(ValidateSetting.REVIEW_THRESHOLD);
459	        BigDecimal floor = on.apply(ValidateSetting.FLOOR);
460	        BigDecimal terms = on.apply(ValidateSetting.TERMS);
461	        BigDecimal latePct = on.apply(ValidateSetting.LATE_PCT);
462	        Map<String, String> gradeTerms = new TreeMap<>();
463	        for (String grade : grades.codes(sheetId)) {
464	            BigDecimal own = on.apply(ValidateSetting.GRADE_TERMS + grade);
465	            if (own != null) gradeTerms.put(grade, String.valueOf(own.intValue()));
466	        }
467	        // The policy date: the latest set (null: blank).
468	        List<LocalDate> policies = new ArrayList<>();
469	        jdbc.query("SELECT policy_date FROM policy_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
470	                (RowCallbackHandler) rs -> policies.add(local(rs.getDate(1))), sheetId, end);
471	        LocalDate policy = policies.isEmpty() ? null : policies.get(policies.size() - 1);
472	        // The undated settings: the latest set for each key.
473	        Map<String, String> plain = new HashMap<>();
474	        jdbc.query("SELECT setting_key, setting_value FROM plain_setting_history WHERE sheet_id = ?" + UP_TO + " ORDER BY seq",
475	                (RowCallbackHandler) rs -> plain.put(rs.getString(1), rs.getString(2)), sheetId, end);
476	        List<RoleResponse> roles = new ArrayList<>();
477	        new TreeMap<>(plain).forEach((key, value) -> {
478	            if (key.startsWith(Settings.ROLE)) roles.add(new RoleResponse(key.substring(Settings.ROLE.length()), value));
479	        });
480	        Map<String, String> perms = new LinkedHashMap<>();
481	        for (String action : ValidateSetting.ACTIONS) {
482	            perms.put(action, plain.getOrDefault(Settings.PERM + action, ""));
483	        }
484	        List<DelegationResponse> delegations = jdbc.query("SELECT user_name, from_date, to_date, delegated_by FROM sheet_delegation"
485	                + " WHERE sheet_id = ?" + UP_TO + " ORDER BY seq", (rs, i) -> new DelegationResponse(rs.getString(1),
486	                        rs.getDate(2).toLocalDate().toString(), rs.getDate(3).toLocalDate().toString(), rs.getString(4)),
487	                sheetId, end);
488	        return new SettingsResponse(limit == null ? "" : limit.setScale(2).toPlainString(),
489	                (floor == null ? Settings.START_FLOOR : floor).setScale(2).toPlainString(),
490	                String.valueOf(terms == null ? Settings.START_TERMS : terms.intValue()),
491	                (latePct == null ? Settings.START_LATE_PCT : latePct).setScale(2).toPlainString(),
492	                policy == null ? "" : policy.toString(), plain.getOrDefault(Settings.NUMBERING, ""), roles, gradeTerms,
493	                cap == null ? "" : cap.setScale(2).toPlainString(), datedShown,
494	                threshold == null ? "" : threshold.setScale(2).toPlainString(), perms, plain.getOrDefault(Settings.GRACE, ""),
495	                delegations, noteThreshold == null ? "" : noteThreshold.setScale(2).toPlainString(),
496	                plain.getOrDefault(Settings.ENTRY, ""), plain.getOrDefault(Settings.POT, ""),
497	                Objects.toString(sheets.parent(sheetId), ""), // the parent is not dated: as it is now
498	                plain.getOrDefault(Settings.FISCAL, "1"), plain.getOrDefault(Settings.ALERT, ""),
499	                net.officefloor.hq.app.claim.Rounding.name(on.apply(ValidateSetting.ROUNDING)),
500	                reviewThreshold == null ? "" : reviewThreshold.setScale(2).toPlainString(),
501	                plain.getOrDefault(Settings.ESCALATE, ""), plain.getOrDefault(Settings.REVIEW_SLA, ""),
502	                plain.getOrDefault(Settings.PROOF_KINDS, ""), plain.getOrDefault(Settings.DEFAULT_GRADE, ""),
503	                plain.getOrDefault(ValidateSetting.SCORE_MID, ""), plain.getOrDefault(ValidateSetting.SCORE_HIGH, ""),
504	                plain.getOrDefault(ValidateSetting.SCORE_LOG, ""), plain.getOrDefault(Settings.MAX_OPEN, ""),
505	                plain.getOrDefault(Settings.PENDING_SLA, ""), jdbc.query("SELECT from_date FROM setting_history WHERE sheet_id = ?"
506	                        + " AND setting_key IN ('" + String.join("', '", Settings.POLICY_KEYS) + "')" + UP_TO + " ORDER BY seq",
507	                        (rs, i) -> rs.getDate(1) == null ? "" : rs.getDate(1).toLocalDate().toString(), sheetId, end),
508	                Settings.policyLines(jdbc, sheetId, UP_TO, end));
509	    }
