511	    /** Figures by person id from "<person id>=<figure>" joined by ";" (null or "": none). */
512	    private static Map<String, String> byPerson(String joined) {
513	        Map<String, String> figures = new LinkedHashMap<>();
514	        if (joined != null && !joined.isEmpty()) {
515	            for (String entry : joined.split(";")) {
516	                String[] pair = entry.split("=", 2);
517	                figures.put(pair[0], new BigDecimal(pair[1]).setScale(2).toPlainString());
518	            }
519	        }
520	        return figures;
521	    }
