 20	/** A crew's due-total in cents: the lead's and the members' due-totals added up, n/a skipped. */
 21	export function crewDueCents(crew: Crew, byId: Map<string, Person>, totalOf: (person: Person) => bigint | null): bigint {
 22	  return [crew.leadId, ...crew.members.map((m) => m.personId)].reduce((sum, id) => {
 23	    const person = byId.get(id);
 24	    const due = person === undefined ? null : totalOf(person);
 25	    return due === null ? sum : sum + due;
 26	  }, 0n);
 27	}
