167	/** A period: a name unique on the sheet, from and to dates (YYYY-MM-DD, both inclusive), whether it
168	 *  is closed, the due-total fixed when it was closed ("" while open), and each person's due-total for
169	 *  it fixed then, by person id (empty while open; a person added later has none). A soft-closed period
170	 *  has its figures fixed the same way, but its claims stay open to change. Its cap is the most OPEN or PENDING
171	 *  claims a person may have in it ("" for none): opening one more is refused. Each person's carried figure for it is
172	 *  fixed by a close or soft-close too, by person id (empty while open; none for a person added later, nor for a
173	 *  close made before carried figures were kept). A locked period cannot be reopened. Its added order is its place in the order the sheet's
174	 *  periods were added. */
175	export type Period = {
176	  name: string;
177	  from: string;
178	  to: string;
179	  closed: boolean;
180	  closedTotal: string;
181	  closedPersonTotals: Record<string, string>;
182	  softClosed: boolean;
183	  cap: string;
184	  closedPersonCarried: Record<string, string>;
185	  locked: boolean;
186	  addedOrder: number;
187	};
