189	export const periodsKey = (sheet: string, asOf = '') => ['sheet', sheet, 'periods', asOf] as const;
190	
191	/** The sheet's periods, by from-date. */
192	export function usePeriods(sheet: string): Period[] {
193	  const asOf = useAsOf();
194	  const { data } = useQuery({
195	    queryKey: periodsKey(sheet, asOf),
196	    queryFn: () => getJson<Period[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
197	    enabled: sheet !== '',
198	  });
199	  return data ?? [];
200	}
