202	/** The fiscal year a date falls in, named FY<yyyy> by the calendar year its first day falls in, for a
203	 *  fiscal year starting in the month (1 to 12). */
204	export function fiscalYearOf(date: string, startMonth: number): string {
205	  const year = Number(date.slice(0, 4));
206	  const month = Number(date.slice(5, 7));
207	  return `FY${month >= startMonth ? year : year - 1}`;
208	}
