        int redated = 0;
        if (valid != null) {
            for (Claim claim : ordered) {
                try {
                    ApplyRedate.refuse(claim, valid, settings, people, periods);
                } catch (ClaimStatusRefusedException e) {
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                LocalDate old = claim.getDate();
                claim.setDate(valid.date());
                claims.redate(claim);
                Person person = people.find(sheetId, claim.getPersonId());
                audit.recordOnCommit(ClaimAudit.line("CLAIM_REDATED", request.user(), person, claim, claim.getNumber())
                        + " old=" + old + " new=" + claim.getDate());
                rollup.recordChanges(sheetId, request.user(), before);
                redated++;
            }
        }
        response.send(new BulkRedateResponse(redated, selected.size() - redated));
    }
}
=== BulkReassignClaims
/**
 * Moves the selected claims to one person, in list order (people in the order they were added, newest
 * claim first within a person, as listed before any of them moved), each by the rules of moving one
 * claim — the roles the reassign permission allows, a DRAFT, OPEN or PENDING claim, no due-by inside a
 * closed period, and no claim dated after the person's retirement — renumbered as a single move would be,
 * and audited as a single move would
 * be. A selected claim that cannot move is left as it is and counted as refused; so is a selected id
 * that is not a claim on the sheet.
 */
public class BulkReassignClaims {
    public void reassign(@PathVariable("sheetId") String sheetId, @RequestBody BulkReassignRequest request,
            Claims claims, People people, Periods periods, Settings settings, ClaimNumbering numbering, Rollup rollup, Audit audit,
            ObjectResponse<BulkReassignResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        Person to = null;
        try {
            to = request.toPersonId() == null ? null : people.find(sheetId, Long.parseLong(request.toPersonId()));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        List<Person> listed = people.list(sheetId);
        List<Claim> all = claims.list(sheetId);
        List<Claim> ordered = new ArrayList<>();
        for (Person person : listed) {
            for (Claim claim : all) {
                if (claim.getPersonId() == person.getId() && selected.contains(String.valueOf(claim.getId()))) {
                    ordered.add(claim);
                }
            }
        }
        int reassigned = 0;
        if (to != null && settings.allows(sheetId, request.user(), "reassign")) {
            for (Claim claim : ordered) {
                ClaimStatus status = claim.getStatus();
                if (status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
                    continue;
                }
                if (periods.isClosed(sheetId, claim.getPeriodDate()) || !to.allowsClaimOn(claim.getDate())) {
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                Person from = people.find(sheetId, claim.getPersonId());
                claim.setPersonId(to.getId());
                claim.setStated(false);
                claim.setStatedDue(null);
                if (claim.getNumber() != null) {
                    claim.setNumber(numbering.next(sheetId, claim.getPeriodDate()));
                }
                claims.reassign(claim);
                audit.recordOnCommit(ClaimAudit.line("CLAIM_REASSIGNED", request.user(), to, claim, claim.getNumber())
                        + " from=" + from.getName() + " to=" + to.getName());
                rollup.recordChanges(sheetId, request.user(), before);
                reassigned++;
            }
        }
        response.send(new BulkReassignResponse(reassigned, selected.size() - reassigned));
    }
}
=== GeneratePlanClaims
/**
 * For every plan on the sheet, in the order they were added, makes a DRAFT claim of the plan's amount for each plan date (the
 * start, then every N days; or the day in every month from the start's month, on the month's last day when it is shorter,
 * dates before the start left out) up to the end and the sheet's today that has none yet, dated that day with an empty note, each
 * audited as CLAIM_ADDED. A date the claim form refuses (its due-by inside a closed period, after the person's retirement) is
 * skipped, and tried again on the next generate. A viewer changes nothing: their generate makes no claim (an archived sheet
 * refuses it). A plan naming a descendant sheet makes its claims there instead, for the person of the same name on that sheet (none
 * when there is no such person), by that sheet's rules and audited on that sheet; they still count towards what the plan made.
 */
public class GeneratePlanClaims {
    public void generate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateRequest request, Plans plans, People people,
            Claims claims, Sheets sheets, Periods periods, Holidays holidays, Settings settings, ClaimLog log, Audit audit,
            @Val RollupFigures before, Rollup rollup, ObjectResponse<GenerateResponse> response) {
        try {
            settings.refuseViewer(sheetId, request.user());
        } catch (ViewerRefusedException e) {
            response.send(new GenerateResponse(0));
            return;
        }
        LocalDate today = sheets.today(sheetId);
        int made = 0;
        Map<String, RollupFigures> targets = new LinkedHashMap<>();
        for (Plan plan : plans.list(sheetId)) {
            Person person = people.find(sheetId, plan.personId());
            if (person == null) continue;
            String on = sheetId;
            if (plan.target() != null) {
                on = plan.target();
                person = people.findByName(on, person.getName());
                if (person == null) continue;
                targets.computeIfAbsent(on, rollup::figures);
            }
            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
            for (LocalDate date : plan.dates(last)) {
                if (plans.made(plan.id(), date)) continue;
                LocalDate dueBy = holidays.dueBy(on, date, settings.termsOnCreation(on, person));
                if (periods.isClosed(on, dueBy) || !person.allowsClaimOn(date)) continue;
                Claim claim = claims.add(on, person.getId(), plan.amount(), date, "", null, dueBy, null);
                plans.recordMade(plan.id(), date, claim.getId());
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
                LateEntry.mark(claim, person, request.user(), claims, periods, audit);
                made++;
            }
        }
        rollup.recordChanges(sheetId, request.user(), before);
        targets.forEach((on, was) -> rollup.recordChanges(on, request.user(), was));
        response.send(new GenerateResponse(made));
    }
}
=== ChangePlanAmount
/** Changes the plan's amount on the sheet's today, audited as PLAN_CHANGED: the claims it generates from then on take the new
 *  amount. Those it already generated that are still DRAFT take it too, each as the claim form would edit it (by its rules, keeping
 *  the claim's date, note, ref and tags), audited as CLAIM_EDITED; a draft the form would refuse, and a claim in any other status,
 *  keeps its amount. An amount the claim form refuses is refused. */
public class ChangePlanAmount {
    public void change(@PathVariable("sheetId") String sheetId, @PathVariable("planId") String planId, @RequestBody AmountRequest request,
            Plans plans, People people, Claims claims, Sheets sheets, Periods periods, Settings settings, Rollup rollup, Audit audit,
            ObjectResponse<PlanResponse> response)
            throws InvalidPlanException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        BigDecimal amount;
        try {
            amount = ValidateClaim.amount(request.amount());
        } catch (InvalidClaimException e) {
            throw new InvalidPlanException(e.getMessage());
        }
        Plan plan;
        try {
            plan = plans.find(Long.parseLong(planId));
        } catch (NumberFormatException e) {
            plan = null;
        }
        if (plan == null || !plan.sheetId().equals(sheetId)) {
            throw new InvalidPlanException("No such plan");
        }
        Person person = people.find(sheetId, plan.personId());
        LocalDate today = sheets.today(sheetId);
        plans.changeAmount(plan.id(), today, amount);
        audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + request.user() + " name=" + (person != null ? person.getName() : "")
                + " start=" + plan.start() + " amount=" + amount.toPlainString());
        editDrafts(plan, amount, request.user(), plans, people, claims, sheets, periods, rollup, audit);
        response.send(PlanResponse.from(plans.find(plan.id()), today));
    }
    /** Edits each DRAFT claim the plan generated (on its own sheet or the plan's target) to the amount, as the claim form would. */
    private static void editDrafts(Plan plan, BigDecimal amount, String user, Plans plans, People people, Claims claims, Sheets sheets,
            Periods periods, Rollup rollup, Audit audit) {
        String on = plan.target() != null ? plan.target() : plan.sheetId();
        RollupFigures before = null;
        ApplyClaim form = new ApplyClaim();
        for (long id : plans.claimIds(plan.id())) {
            Claim claim = claims.find(on, id);
            if (claim == null || claim.getStatus() != ClaimStatus.DRAFT) continue;
            if (before == null) before = rollup.figures(on);
            ValidClaim edit = new ValidClaim(amount, claim.getDate(), claim.getNote(), user, claim.getCorrects(), claim.getRef(), claim.getTags());
            try {
                form.apply(edit, claim, sheets, periods, people, claims);
            } catch (InvalidClaimException e) {
                continue; // the form would refuse this draft's edit: it keeps its amount
            }
            claims.save(claim);
            audit.recordOnCommit(ClaimAudit.line("CLAIM_EDITED", user, people.find(on, claim.getPersonId()), claim, claim.getNumber()));
        }
        if (before != null) rollup.recordChanges(on, user, before);
    }
}
