118	      <ul>
119	        {pool.members.map((m) => (
120	          <li
121	            key={m.memberPool ? `pool:${m.memberPool}` : m.personId}
122	            data-testid={m.memberPool ? `pool-member-${pool.name}-pool-${m.memberPool}` : `pool-member-${pool.name}-${m.personId}`}
123	          >
124	            <span data-testid="pool-member-name">{m.name}</span>{' '}
125	            <span data-testid="pool-share">{m.share}</span>{' '}
126	            cut <span data-testid="pool-cut">{m.cut}</span>
127	            {Object.entries(m.periodCuts ?? {}).map(([period, cut]) => (
128	              <span key={period}>
129	                {' '}{period} <span data-testid={`pool-cut-${period}`}>{cut}</span>
130	              </span>
131	            ))}
132	            {m.retired && ' (retired)'}
133	            {!m.current && ' (not current)'}
134	          </li>
135	        ))}
136	      </ul>
137	      {!pool.crew && <form
138	        onSubmit={(e) => {
139	          e.preventDefault();
140	          submitOnce(() => {
141	            add.reset();
142	            const memberPool = personId.startsWith('pool:') ? personId.slice('pool:'.length) : '';
143	            const dates = { share: share.trim(), from: from.trim(), to: to.trim() };
144	            return add.mutateAsync(memberPool ? { memberPool, ...dates } : { personId, ...dates });
145	          });
146	        }}
147	      >
148	        <select
149	          data-testid="pool-member-select"
150	          value={personId}
151	          onChange={(e) => {
152	            setPersonId(e.target.value);
153	            add.reset();
154	          }}
155	        >
156	          <option value="">Choose a person</option>
157	          {people.map((p) => (
158	            <option key={p.id} value={p.id}>{p.name}</option>
159	          ))}
160	          {pools.map((p) => (
161	            <option key={`pool:${p.name}`} value={`pool:${p.name}`}>{`pool:${p.name}`}</option>
162	          ))}
163	        </select>{' '}
164	        <input
165	          data-testid="pool-member-share"
166	          value={share}
167	          placeholder="Share %"
168	          onChange={(e) => {
169	            setShare(e.target.value);
170	            add.reset();
171	          }}
172	        />{' '}
173	        <input
174	          type="date"
175	          data-testid="pool-member-from"
176	          value={from}
177	          title="Member from (blank: unbounded)"
178	          onChange={(e) => {
179	            setFrom(e.target.value);
180	            add.reset();
181	          }}
182	        />{' '}
183	        <input
184	          type="date"
185	          data-testid="pool-member-to"
186	          value={to}
187	          title="Member to (blank: unbounded)"
188	          onChange={(e) => {
189	            setTo(e.target.value);
190	            add.reset();
191	          }}
192	        />{' '}
193	        <button type="submit" data-testid="pool-member-add">Add member</button>
194	        {add.isError && <span data-testid="pool-error" role="alert"> Could not add the member: already in the pool, a pool already in a pool, containing this pool, or nesting more than three deep, or the share is not more than 0.00 and at most 100.00 with two decimals, or the to-date is before the from-date.</span>}
195	      </form>}
196	    </li>
197	  );
