51	    /** The value of a dated setting in force on the date; null when nothing is recorded on or before it. */
52	    private InForce on(String sheetId, String key, LocalDate on) {
53	        List<InForce> found = jdbc.query(
54	                "SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = ? AND from_date <= ?"
55	                        + " ORDER BY from_date DESC LIMIT 1",
56	                (rs, i) -> new InForce(rs.getBigDecimal(1)), sheetId, key, Date.valueOf(on));
57	        return found.isEmpty() ? null : found.get(0);
58	    }
