61	    public void setFrom(String sheetId, String key, LocalDate from, BigDecimal value) {
62	        sheets.today(sheetId);
63	        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, from_date, setting_value)"
64	                + " KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)", sheetId, key, Date.valueOf(from), value);
65	        jdbc.update("INSERT INTO setting_history (sheet_id, set_on, setting_key, from_date, setting_value) VALUES (?, (SELECT today FROM sheet WHERE id = ?), ?, ?, ?)",
66	                sheetId, sheetId, key, Date.valueOf(from), value);
67	    }
