79	        jdbc.query("SELECT setting_key, from_date, setting_value FROM sheet_setting WHERE sheet_id = ? ORDER BY setting_key, from_date",
80	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> {
81	                    String shown = shown(rs.getString(1), rs.getBigDecimal(3));
82	                    all.computeIfAbsent(rs.getString(1), k -> new java.util.ArrayList<>())
83	                            .add(new DatedValue(rs.getDate(2).toLocalDate().toString(), shown));
