128	    /** Each policy version, oldest first, among the setting history rows the extra condition keeps (bound to the args). */
129	    public static List<PolicyVersion> policyLines(JdbcTemplate jdbc, String sheetId, String condition, Object... args) {
130	        Object[] all = new Object[args.length + 1];
131	        all[0] = sheetId;
132	        System.arraycopy(args, 0, all, 1, args.length);
133	        return jdbc.query("SELECT from_date, setting_key, setting_value FROM setting_history WHERE sheet_id = ? AND setting_key IN ('"
