135	                (rs, i) -> new PolicyVersion(rs.getDate(1) == null ? "" : rs.getDate(1).toLocalDate().toString(), rs.getString(2),
136	                        shown(rs.getString(2), rs.getBigDecimal(3))), all);
137	    }
