 183	    /** A claim's due as the screen shows it now; null for n/a. */
 184	    public BigDecimal due(Claim claim, Person person) {
 185	        String sheetId = claim.getSheetId();
 186	        return due(claim, person, sheets.today(sheetId), settings.policyDate(sheetId));
 187	    }
 188	
 189	    /** A claim's due: fixed when settled; else the figure a statement bound it to, or its amount at the rate of its person's grade
 190	     *  in force on its date, with its late charge (each 30-day boundary at the late percent in force on it) as of today on top,
 191	     *  raised to the floor in force on its date. */
 192	    private BigDecimal due(Claim claim, Person person, LocalDate today, LocalDate policyDate) {
 193	        String sheetId = claim.getSheetId();
 194	        RoundingMode rounding = Rounding.of(claim, policyDate, on -> settings.roundingMode(sheetId, on));
 195	        BigDecimal fixed = ClaimResponse.fixedDue(claim);
 196	        BigDecimal figure = fixed != null || claim.isBound() ? fixed
 197	                : Rates.due(claim.getAmount(), rates.find(claim, person.gradeOn(claim.getDate())), rounding);
 198	        return LateCharge.due(claim, figure, settings.floor(sheetId, claim.getDate()), on -> settings.latePct(sheetId, on), today, rounding,
 199	                grace(claim, person));
 200	    }
 201	
 202	    /** Audit (on commit) one SNAPSHOT line per person, in list order, with their due-total in {@code before}, and keep
 203	     *  it on the person dated the sheet's today (so call it before today moves). */
 204	    public void recordSnapshots(String sheetId, String user, RollupFigures before, LocalDate takenOn) {
 205	        String prefix = " sheet=" + sheetId + " by=" + user;
 206	        before.people().forEach((id, was) -> {
 207	            people.recordSnapshot(sheetId, id, was.dueTotal(), takenOn);
 208	            audit.recordOnCommit("SNAPSHOT" + prefix + " name=" + was.name() + " due-total=" + was.dueTotal());
 209	        });
 210	    }
 211	
 212	    /** Audit (on commit) the figures that moved since {@code before}, as taken by {@code user}. */
 213	    public void recordChanges(String sheetId, String user, RollupFigures before) {
 214	        RollupFigures after = figures(sheetId);
 215	        String prefix = " sheet=" + sheetId + " by=" + user;
 216	        after.people().forEach((id, now) -> {
 217	            RollupFigures.PersonFigures was = before.people().get(id);
 218	            if (was == null || !Objects.equals(was.claimed(), now.claimed())
 219	                    || !Objects.equals(was.dueTotal(), now.dueTotal())
 220	                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
 221	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
 222	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
 223	            }
 224	        });
 225	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
 226	                || !before.overdueTotal().equals(after.overdueTotal())) {
 227	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
 228	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
 229	        }
 230	        BigDecimal threshold = settings.alertThreshold(sheetId);
 231	        if (threshold != null) {
 232	            after.people().forEach((id, now) -> {
 233	                RollupFigures.PersonFigures was = before.people().get(id);
 234	                if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
 235	                    audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + now.dueTotal());
 236	                }
 237	            });
 238	        }
 239	    }
 240	
 241	    /** A person's score: the dues of their counting SETTLED claims that correct nothing over 100, minus 5 for each of their overdue counting claims, rounded half to
 242	     *  even to a whole number. */
 243	    private static String score(BigDecimal settled, int overdueCount) {
 244	        return settled.subtract(BigDecimal.valueOf(5L * overdueCount * 100)).divide(BigDecimal.valueOf(100), 0, RoundingMode.HALF_EVEN)
 245	                .toPlainString();
 246	    }
 247	
 248	    /** Audit (on commit), while the sheet's score log is on, one SCORE line per person, in list order, with their score in
 249	     *  {@code before} (so call it before the SNAPSHOT lines). */
 250	    public void recordScores(String sheetId, String user, RollupFigures before) {
 251	        if (!settings.scoreLog(sheetId)) {
 252	            return;
 253	        }
 254	        String prefix = " sheet=" + sheetId + " by=" + user;
 255	        before.people().forEach((id, was) -> audit.recordOnCommit("SCORE" + prefix + " name=" + was.name() + " score=" + was.score()));
 256	    }
 257	
 258	    /** Whether a due-total as shown is above the threshold (n/a is no due-total). */
 259	    private static boolean above(String dueTotal, BigDecimal threshold) {
 260	        return !NA.equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
 261	    }
 262	
 263	    /** The grace days of the claim's person's grade in force on its date, as in force on that date (0 for none). */
 264	    private int grace(Claim claim, Person person) {
 265	        return settings.grace(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
 266	    }
 267	
 268	    /** A claim is overdue when it is OPEN (or PENDING) and its due-by plus its grace days is before the sheet's today. */
 269	    private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
 270	        return claim.getStatus().isOpen() && claim.getDueBy() != null && LateCharge.lateFrom(claim, grace).isBefore(today);
 271	    }
 272	
 273	    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
 274	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
 275	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
 276	        if (figures.size() < 3) {
 277	            return sum;
 278	        }
 279	        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
 280	                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
 281	    }
 282	
 283	    private static String show(BigDecimal value) {
 284	        return value.setScale(2).toPlainString();
 285	    }
 286	}

