     8	/**
     9	 * How a claim's live figures (the rate step and the late charge) are rounded: by the sheet's rounding mode in force on the
    10	 * claim's date when one is; else a claim dated before the sheet's policy date rounds half up, one dated on or after it half
    11	 * to even. A correction rounds by the date of the claim it corrects, not its own.
    12	 */
    13	public final class Rounding {
    14	
    15	    /** The rounding mode setting's values, as typed. */
    16	    public static final String HALF_UP = "half-up", HALF_EVEN = "half-even";
    17	
    18	    private Rounding() {
    19	    }
    20	
    21	    /** A rounding mode as stored in a dated setting (1: half up, 2: half to even); null for none. */
    22	    public static BigDecimal code(String mode) {
    23	        return HALF_UP.equals(mode) ? BigDecimal.ONE : HALF_EVEN.equals(mode) ? BigDecimal.valueOf(2) : null;
    24	    }
    25	
    26	    /** A stored rounding mode's name ("" for none). */
    27	    public static String name(BigDecimal code) {
    28	        return code == null ? "" : code.intValue() == 1 ? HALF_UP : HALF_EVEN;
    29	    }
    30	
    31	    /** A stored rounding mode; null for none. */
    32	    public static RoundingMode mode(BigDecimal code) {
    33	        return code == null ? null : code.intValue() == 1 ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    34	    }
    35	
    36	    /** @param modeOn the sheet's rounding mode in force on a date; null for none. */
    37	    public static RoundingMode of(Claim claim, LocalDate policyDate, Function<LocalDate, RoundingMode> modeOn) {
    38	        RoundingMode set = modeOn.apply(claim.getRoundingDate());
    39	        if (set != null) {
    40	            return set;
    41	        }
    42	        return claim.getRoundingDate().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    43	    }
