    47	/**
    48	 * A claim's status. It starts DRAFT; DRAFT -> OPEN -> SETTLED, and DRAFT or OPEN -> VOID. A clerk
    49	 * settling above the clerk limit sends an OPEN claim to PENDING instead: a steward approves it
    50	 * (-> SETTLED) or rejects it (-> OPEN); a PENDING claim may also be voided, and a steward may void a SETTLED claim
    51	 * within 7 days of its settlement. A DRAFT claim may be deleted (-> DELETED, counting nowhere) and, on the same
    52	 * sheet-today, restored (-> DRAFT). A claim whose due is above the review threshold in force on its date goes to REVIEW
    53	 * when opened instead of OPEN; a steward's review makes it OPEN, and a REVIEW claim may be voided.
    54	 */
    55	public enum ClaimStatus {
    56	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
    57	
    58	    /** Whether a claim in this status may move to the target status. */
    59	    public boolean canBecome(ClaimStatus target) {
    60	        return switch (target) {
    61	            case OPEN, REVIEW -> this == DRAFT;
    62	            case SETTLED, PENDING -> this == OPEN;
    63	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
    64	            case DELETED -> this == DRAFT;
    65	            case DRAFT -> this == DELETED;
    66	        };
    67	    }
    68	
    69	    /** Only OPEN, PENDING and SETTLED claims count toward claimed and every total. */
    70	    public boolean counts() {
    71	        return this == OPEN || this == PENDING || this == SETTLED;
    72	    }
    73	
    74	    /** OPEN and PENDING claims are open: their due is live, they go overdue and a hold covering their date takes them out of the totals (unless bound). */
    75	    public boolean isOpen() {
    76	        return this == OPEN || this == PENDING;
    77	    }
