    12	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody DelegationRequest request,
    13	            Out<ValidDelegation> body, Settings settings, Sheets sheets) throws InvalidSettingException {
    14	        if (sheets.archived(sheetId)) {
    15	            throw new InvalidSettingException("The sheet is archived: nothing on it can change");
    16	        }
    17	        if (!Settings.STEWARD.equals(settings.roleSet(sheetId, request.user()))) {
    18	            throw new InvalidSettingException("Only a steward can delegate the steward role");
    19	        }
    20	        String name = request.name() == null ? "" : request.name().trim();
    21	        if (name.isEmpty()) {
    22	            throw new InvalidSettingException("A delegation needs a user name");
    23	        }
    24	        LocalDate today = sheets.today(sheetId);
    25	        LocalDate from = date(request.from(), today);
    26	        LocalDate to = date(request.to(), today);
    27	        if (to.isBefore(from)) {
    28	            throw new InvalidSettingException("The to-date cannot be before the from-date");
    29	        }
    30	        body.set(new ValidDelegation(name, from, to, request.user().trim()));
