 25	/**
 26	 * The sheet's figures as the screen shows them — each person's claimed (leaving out corrections; a hold does not take a claim out) and due-total, and the
 27	 * sheet's claimed-total and due-total, each person's and the sheet's overdue-total (the dues of their overdue claims, uncapped), each person's due-total held to the sheet's cap less their cut total, not below 0.00 (a holder's due-total counting their parts of the claims shared with them — each the claim's amount times their share
 28	 * over 100 times the rate of their own grade in force on its date over 100, rounded like the claim, a settled claim's parts
 29	 * frozen at its settled due times the share — the claim's own person's the claim's due less those parts) — worked out on the server so a change can audit what it
 30	 * moved: after the change's own lines, one ROLLUP line per person whose figures changed (people in
 31	 * the order they were added; a new person counts as changed), then a TOTALS line when the sheet's
 32	 * totals changed. The sheet's due-total and overdue-total leave out the single highest and the single
 33	 * lowest person's figure when three or more people have one (n/a is no figure). While the sheet has an
 34	 * alert threshold, after those lines one ALERT line per person (in list order) whose due-total went from
 35	 * at or below it (or none) to above it.
 36	 */
 37	@Service
 38	public class Rollup {
 39	
 40	    private static final String NA = "n/a";
 41	
 42	    private final People people;
 43	    private final Claims claims;
 44	    private final Rates rates;
 45	    private final Sheets sheets;
 46	    private final Settings settings;
 47	    private final Audit audit;
 48	    private final net.officefloor.hq.app.pool.Pools pools;
 49	
 50	    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings, Audit audit,
 51	            net.officefloor.hq.app.pool.Pools pools) {
 52	        this.pools = pools;
 53	        this.people = people;
 54	        this.claims = claims;
 55	        this.rates = rates;
 56	        this.sheets = sheets;
 57	        this.settings = settings;
 58	        this.audit = audit;
 59	    }
 60	
 61	    /** The sheet's figures now. */
 62	    public RollupFigures figures(String sheetId) {
 63	        LocalDate today = sheets.today(sheetId);
 64	        LocalDate policyDate = settings.policyDate(sheetId);
 65	        Map<Long, BigDecimal> cutTotals = pools.cutTotals(sheetId, null);
 66	        List<Claim> all = claims.list(sheetId);
 67	        Map<Long, RollupFigures.PersonFigures> byPerson = new LinkedHashMap<>();
 68	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
 69	        List<BigDecimal> dues = new ArrayList<>();
 70	        List<BigDecimal> overdues = new ArrayList<>();
 71	        List<Person> listed = people.list(sheetId);
 72	        Map<Long, Person> byId = new LinkedHashMap<>();
 73	        listed.forEach(person -> byId.put(person.getId(), person));
 74	        SharedParts parts = sharedParts(all, byId, today, policyDate);
 75	        Map<Long, BigDecimal> partsIn = parts.in();
 76	        Map<Long, BigDecimal> partsOut = parts.out();
 77	        for (Person person : listed) {
 78	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
 79	            BigDecimal due = BigDecimal.ZERO.setScale(2);
 80	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
 81	            BigDecimal settled = BigDecimal.ZERO.setScale(2);
 82	            int overdueCount = 0;
 83	            boolean anyFigure = false;
 84	            // The cap is the one in force on the date of their latest claim that counts (the sheet's today when none does).
 85	            LocalDate capDate = null;
 86	            for (Claim claim : all) {
 87	                if (claim.getPersonId() != person.getId() || !person.countsClaimed(claim, today)) {
 88	                    continue;
 89	                }
 90	                if (claim.getCorrects() == null || claim.getCorrects().isEmpty()) {
 91	                    claimed = claimed.add(claim.getAmount());
 92	                }
 93	                if (!person.countsLive(claim, today)) {
 94	                    continue;
 95	                }
 96	                if (capDate == null || claim.getDate().isAfter(capDate)) {
 97	                    capDate = claim.getDate();
 98	                }
 99	                BigDecimal figure = due(claim, person, today, policyDate);
100	                if (isOverdue(claim, grace(claim, person), today)) {
101	                    overdueCount++;
102	                }
103	                // The score's settled figures leave out corrections.
104	                if (figure != null && claim.getStatus() == net.officefloor.hq.app.claim.ClaimStatus.SETTLED
105	                        && (claim.getCorrects() == null || claim.getCorrects().isEmpty())) {
106	                    settled = settled.add(figure);
107	                }
108	                if (figure != null) {
109	                    anyFigure = true;
110	                    due = due.add(figure);
111	                    if (isOverdue(claim, grace(claim, person), today)) {
112	                        overdue = overdue.add(figure);
113	                    }
114	                }
115	            }
116	            if (partsIn.containsKey(person.getId())) {
117	                anyFigure = true;
118	                due = due.add(partsIn.get(person.getId()));
119	            }
120	            due = due.subtract(partsOut.getOrDefault(person.getId(), BigDecimal.ZERO));
121	            // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
122	            boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
123	            BigDecimal cap = settings.cap(sheetId, capDate == null ? today : capDate);
124	            due = Settings.capped(due, cap, cutTotals.getOrDefault(person.getId(), BigDecimal.ZERO));
125	            claimedTotal = claimedTotal.add(claimed);
126	            if (!na) {
127	                dues.add(due);
128	            }
129	            overdues.add(overdue);
130	            byPerson.put(person.getId(), new RollupFigures.PersonFigures(person.getName(),
131	                    show(claimed), na ? NA : show(due), show(overdue),
132	                    score(settled, overdueCount)));
133	        }
134	        return new RollupFigures(byPerson, show(claimedTotal), show(trimmedSum(dues)), show(trimmedSum(overdues)));
135	    }
