202	    /** Audit (on commit) one SNAPSHOT line per person, in list order, with their due-total in {@code before}, and keep
203	     *  it on the person dated the sheet's today (so call it before today moves). */
204	    public void recordSnapshots(String sheetId, String user, RollupFigures before, LocalDate takenOn) {
205	        String prefix = " sheet=" + sheetId + " by=" + user;
206	        before.people().forEach((id, was) -> {
207	            people.recordSnapshot(sheetId, id, was.dueTotal(), takenOn);
208	            audit.recordOnCommit("SNAPSHOT" + prefix + " name=" + was.name() + " due-total=" + was.dueTotal());
209	        });
210	    }
211	
212	    /** Audit (on commit) the figures that moved since {@code before}, as taken by {@code user}. */
213	    public void recordChanges(String sheetId, String user, RollupFigures before) {
214	        RollupFigures after = figures(sheetId);
215	        String prefix = " sheet=" + sheetId + " by=" + user;
216	        after.people().forEach((id, now) -> {
217	            RollupFigures.PersonFigures was = before.people().get(id);
218	            if (was == null || !Objects.equals(was.claimed(), now.claimed())
219	                    || !Objects.equals(was.dueTotal(), now.dueTotal())
220	                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
221	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
222	                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
223	            }
224	        });
225	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
226	                || !before.overdueTotal().equals(after.overdueTotal())) {
227	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
228	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
229	        }
230	        BigDecimal threshold = settings.alertThreshold(sheetId);
231	        if (threshold != null) {
232	            after.people().forEach((id, now) -> {
233	                RollupFigures.PersonFigures was = before.people().get(id);
234	                if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
235	                    audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + now.dueTotal());
236	                }
237	            });
238	        }
239	    }
