241	    /** A person's score: the dues of their counting SETTLED claims that correct nothing over 100, minus 5 for each of their overdue counting claims, rounded half to
242	     *  even to a whole number. */
243	    private static String score(BigDecimal settled, int overdueCount) {
244	        return settled.subtract(BigDecimal.valueOf(5L * overdueCount * 100)).divide(BigDecimal.valueOf(100), 0, RoundingMode.HALF_EVEN)
245	                .toPlainString();
246	    }
247	
248	    /** Audit (on commit), while the sheet's score log is on, one SCORE line per person, in list order, with their score in
249	     *  {@code before} (so call it before the SNAPSHOT lines). */
250	    public void recordScores(String sheetId, String user, RollupFigures before) {
251	        if (!settings.scoreLog(sheetId)) {
252	            return;
253	        }
254	        String prefix = " sheet=" + sheetId + " by=" + user;
255	        before.people().forEach((id, was) -> audit.recordOnCommit("SCORE" + prefix + " name=" + was.name() + " score=" + was.score()));
256	    }
257	
258	    /** Whether a due-total as shown is above the threshold (n/a is no due-total). */
259	    private static boolean above(String dueTotal, BigDecimal threshold) {
260	        return !NA.equals(dueTotal) && new BigDecimal(dueTotal).compareTo(threshold) > 0;
261	    }
262	
263	    /** The grace days of the claim's person's grade in force on its date, as in force on that date (0 for none). */
264	    private int grace(Claim claim, Person person) {
265	        return settings.grace(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
266	    }
267	
268	    /** A claim is overdue when it is OPEN (or PENDING) and its due-by plus its grace days is before the sheet's today. */
269	    private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
270	        return claim.getStatus().isOpen() && claim.getDueBy() != null && LateCharge.lateFrom(claim, grace).isBefore(today);
271	    }
272	
273	    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
274	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
275	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
276	        if (figures.size() < 3) {
277	            return sum;
278	        }
279	        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
280	                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
281	    }
282	
283	    private static String show(BigDecimal value) {
284	        return value.setScale(2).toPlainString();
285	    }
