    14	/**
    15	 * Adds the holiday and re-fixes the due-by of every claim not SETTLED, VOID or DELETED whose due-by is on or after it: worked
    16	 * out again from the claim's date, with the terms it was fixed with, over the holidays now on the sheet.
    17	 */
    18	public class SaveHoliday {
    19	    public void save(@PathVariable("sheetId") String sheetId, @Val ValidHoliday holiday, @Val RollupFigures before,
    20	            Holidays holidays, Claims claims, Rollup rollup, Audit audit, ObjectResponse<List<String>> response) {
    21	        holidays.add(sheetId, holiday.date());
    22	        for (Claim claim : claims.list(sheetId)) {
    23	            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
    24	                    || claim.getStatus() == ClaimStatus.DELETED
    25	                    || claim.getDueBy() == null || claim.getTerms() == null || claim.getDueBy().isBefore(holiday.date())) {
    26	                continue;
    27	            }
    28	            java.time.LocalDate dueBy = holidays.dueBy(sheetId, claim.getDate(), claim.getTerms());
    29	            if (!dueBy.equals(claim.getDueBy())) {
    30	                claim.setDueBy(dueBy);
    31	                claims.refix(claim);
    32	            }
    33	        }
    34	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + holiday.user() + " date=" + holiday.date());
    35	        rollup.recordChanges(sheetId, holiday.user(), before);
    36	        response.send(holidays.list(sheetId));
    37	    }
    38	}
