 21	/**
 22	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 23	 * so tests can assert side-effects by reading that file — the second test-assertion channel
 24	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 25	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 26	 *
 27	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 28	 * SYNC) so a test reads the record immediately.
 29	 */
 30	@Service
 31	public class Audit {
 32	
 33	    /** The lines that only report figures: they never carry for=. */
 34	    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
 35	
 36	    private final Path file;
 37	
 38	    private final ObjectProvider<Settings> settings;
 39	
 40	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<Settings> settings) {
 41	        this.file = Path.of(path);
 42	        this.settings = settings;
 43	    }
 44	
 45	    /** Append one audit record. Tests assert the exact line(s) in the file. */
 46	    public void record(String entry) {
 47	        append(delegated(entry));
 48	    }
 49	
 50	    /**
 51	     * The entry, ending with for=<the steward who delegated> when its by= user acts as a steward by a
 52	     * delegation covering the sheet's today — unless it is a line that only reports figures.
 53	     */
 54	    private String delegated(String entry) {
 55	        String[] fields = entry.split(" ");
 56	        if (FIGURES.contains(fields[0])) {
 57	            return entry;
 58	        }
 59	        String sheet = null;
 60	        String by = null;
 61	        for (String field : fields) {
 62	            if (sheet == null && field.startsWith("sheet=")) {
 63	                sheet = field.substring("sheet=".length());
 64	            } else if (by == null && field.startsWith("by=")) {
 65	                by = field.substring("by=".length());
 66	            }
 67	        }
 68	        if (sheet == null || by == null) {
 69	            return entry;
 70	        }
 71	        String delegator = settings.getObject().delegator(sheet, by);
 72	        return delegator == null ? entry : entry + " for=" + delegator;
 73	    }
 74	
 75	    private synchronized void append(String entry) {
 76	        try {
 77	            Path parent = file.toAbsolutePath().getParent();
 78	            if (parent != null) {
 79	                Files.createDirectories(parent);
 80	            }
 81	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
 82	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
 83	        } catch (IOException e) {
 84	            throw new UncheckedIOException(e);
 85	        }
 86	    }
 87	
 88	    /**
 89	     * Append one audit record once the current transaction commits, so a change that is rolled back
 90	     * (refused by a later step) writes no line. Outside a transaction it is appended at once.
 91	     */
 92	    public void recordOnCommit(String raw) {
 93	        String entry = delegated(raw);
 94	        if (TransactionSynchronizationManager.isSynchronizationActive()) {
 95	            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
 96	                @Override
 97	                public void afterCommit() {
 98	                    append(entry);
 99	                }
100	            });
101	        } else {
102	            append(entry);
103	        }
104	    }
105	
106	    /**
107	     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only
108	     * the lines carrying name=<it> or person=<it>, compared as names are (case and surrounding
109	     * spaces ignored). Read from the file: the viewer is not a second record.
110	     */
111	    public synchronized List<String> lines(String sheet, String name) {
112	        String wanted = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
113	        List<String> found = new ArrayList<>();
114	        if (!Files.exists(file)) {
115	            return found;
116	        }
117	        List<String> all;
118	        try {
119	            all = Files.readAllLines(file, StandardCharsets.UTF_8);
120	        } catch (IOException e) {
121	            throw new UncheckedIOException(e);
122	        }
123	        for (String line : all) {
124	            List<String[]> fields = fields(line);
125	            if (!has(fields, "sheet", sheet, false)) {
126	                continue;
127	            }
128	            if (!wanted.isEmpty() && !has(fields, "name", wanted, true) && !has(fields, "person", wanted, true)) {
129	                continue;
130	            }
131	            found.add(line);
132	        }
133	        Collections.reverse(found);
134	        return found;
135	    }
136	
137	    /**
138	     * A claim's timeline: the sheet's lines about it exactly as the file holds them, newest first. With a number,
139	     * the lines carrying number=<it>; without one, the lines carrying no number that name its person (compared as
140	     * names are), amount and date together. Read from the file: the timeline is not a second record.
141	     */
142	    public synchronized List<String> claimLines(String sheet, String number, String person, String amount,
143	            String date) {
144	        String wanted = person.trim().toLowerCase(Locale.ROOT);
145	        List<String> found = new ArrayList<>();
146	        if (!Files.exists(file)) {
147	            return found;
148	        }
149	        List<String> all;
150	        try {
151	            all = Files.readAllLines(file, StandardCharsets.UTF_8);
152	        } catch (IOException e) {
153	            throw new UncheckedIOException(e);
154	        }
155	        for (String line : all) {
156	            List<String[]> fields = fields(line);
157	            if (!has(fields, "sheet", sheet, false)) {
158	                continue;
159	            }
160	            boolean about = number != null && !number.isEmpty()
161	                    ? has(fields, "number", number, false)
162	                    : !hasKey(fields, "number") && has(fields, "person", wanted, true)
163	                            && has(fields, "amount", amount, false) && has(fields, "date", date, false);
164	            if (about) {
165	                found.add(line);
166	            }
167	        }
168	        Collections.reverse(found);
169	        return found;
170	    }
171	
172	    /**
173	     * The sheet's activity: for every user (by=) and every event in the sheet's lines, one line
174	     * "<user> <EVENT> <count>", sorted by user then event. Read from the file: not a second record.
175	     */
176	    public synchronized List<String> activity(String sheet) {
177	        java.util.TreeMap<String, java.util.TreeMap<String, Integer>> counts = new java.util.TreeMap<>();
178	        for (String line : lines(sheet, null)) {
179	            String event = line.split(" ", 2)[0];
180	            String by = null;
181	            for (String[] field : fields(line)) {
182	                if (field[0].equals("by")) {
183	                    by = field[1];
184	                    break;
185	                }
186	            }
187	            if (by == null || event.isEmpty()) {
188	                continue;
189	            }
190	            counts.computeIfAbsent(by, k -> new java.util.TreeMap<>()).merge(event, 1, Integer::sum);
191	        }
192	        List<String> found = new ArrayList<>();
193	        counts.forEach((user, events) -> events.forEach((event, n) -> found.add(user + " " + event + " " + n)));
194	        return found;
195	    }
196	
197	    /** Whether the line carries a field with the key. */
198	    private static boolean hasKey(List<String[]> fields, String key) {
199	        return fields.stream().anyMatch(field -> field[0].equals(key));
200	    }
201	
202	    /** Whether a field key=value is among the line's fields (a name compared trimmed, case ignored). */
203	    private static boolean has(List<String[]> fields, String key, String value, boolean asName) {
204	        for (String[] field : fields) {
205	            if (field[0].equals(key)) {
206	                String v = asName ? field[1].trim().toLowerCase(Locale.ROOT) : field[1];
207	                if (v.equals(value)) {
208	                    return true;
209	                }
210	            }
211	        }
212	        return false;
213	    }
214	
215	    /** A line's key=value fields; a word without key= continues the value before it (a name with spaces). */
216	    private static List<String[]> fields(String line) {
217	        List<String[]> fields = new ArrayList<>();
218	        String[] words = line.split(" ");
219	        for (int i = 1; i < words.length; i++) {
220	            String word = words[i];
221	            int eq = word.indexOf('=');
222	            if (eq > 0 && word.substring(0, eq).matches("[a-z][a-z-]*")) {
223	                fields.add(new String[] { word.substring(0, eq), word.substring(eq + 1) });
224	            } else if (!fields.isEmpty()) {
225	                String[] last = fields.get(fields.size() - 1);
226	                last[1] = last[1] + " " + word;
227	            }
228	        }
229	        return fields;
230	    }
231	
232	    /** Remove the audit file. */
233	    public synchronized void clear() {
234	        try {
235	            Files.deleteIfExists(file);
236	        } catch (IOException e) {
237	            throw new UncheckedIOException(e);
238	        }
239	    }
240	}

