     9	import net.officefloor.plugin.variable.Val;
    10	import net.officefloor.web.ObjectResponse;
    11	import org.springframework.web.bind.annotation.PathVariable;
    13	/**
    14	 * Gives every person whose grade in force on the sheet's today is the merged grade the other grade from
    15	 * the sheet's today, in list order, each exactly as a person form save would: audited as PERSON_EDITED
    16	 * with the rollup lines it moved; then, retroactively, every grade record of theirs on the merged grade becomes
    17	 * the other grade; then the rollup lines the whole merge moved. Counted.
    18	 */
    19	public class MergeGrade {
    20	    public void merge(@PathVariable("sheetId") String sheetId, @Val ValidGradeMerge request, People people,
    21	            Rollup rollup, Audit audit, ObjectResponse<GradeMergeResponse> response) throws PersonConflictException {
    22	        audit.recordOnCommit("GRADE_MERGED sheet=" + sheetId + " by=" + request.user()
    23	                + " from=" + request.from() + " into=" + request.into());
    24	        RollupFigures start = rollup.figures(sheetId);
    25	        java.util.List<Person> moved = new java.util.ArrayList<>();
    26	        for (Person person : people.list(sheetId)) {
    27	            if (!request.from().equals(person.getGrade())) {
    28	                continue;
    29	            }
    30	            RollupFigures before = rollup.figures(sheetId);
    31	            person.recordGrade(person.getToday(), request.into());
    32	            if (!people.save(person)) {
    33	                throw new PersonConflictException(person.getId());
    34	            }
    35	            audit.recordOnCommit("PERSON_EDITED sheet=" + sheetId + " by=" + request.user()
    36	                    + " name=" + person.getName() + " grade=" + person.getGrade());
    37	            rollup.recordChanges(sheetId, request.user(), before);
    38	            moved.add(person);
    39	        }
    40	        // The merge is retroactive: every grade record of each person it moved on the merged grade becomes the other.
    41	        for (Person person : moved) {
    42	            people.regrade(person, request.from(), request.into());
    43	        }
    44	        int merged = moved.size();
    45	        if (merged > 0) {
    46	            rollup.recordChanges(sheetId, request.user(), start);
    47	        }
    48	        response.send(new GradeMergeResponse(merged));
    49	    }
    50	}
