217	    /** Adds each of the sheet's crews, in the order added and after the pools, as a pool of its name: the lead and then
218	     *  the members (in the order added) at equal shares, 100.00 split as patrons' shares are (each rounded half to even to
219	     *  two decimals, the remainder on the lead), every membership current. Returns the crews' names. */
220	    private Set<String> crewPools(String sheetId, Map<String, List<PoolResponse.Member>> members, java.sql.Date addedBy,
221	            Map<Long, Boolean> retiredThen) {
222	        Set<String> crews = new HashSet<>();
223	        Map<String, List<PoolResponse.Member>> people = new LinkedHashMap<>();
224	        Object[] args = addedBy == null ? new Object[] {sheetId} : new Object[] {sheetId, addedBy};
225	        jdbc.query("SELECT c.name, c.lead_person_id, p.name, p.retired_from FROM crew c"
226	                + " LEFT JOIN person p ON p.id = c.lead_person_id AND p.sheet_id = c.sheet_id"
227	                + " WHERE c.sheet_id = ?" + (addedBy == null ? "" : " AND (c.added_on IS NULL OR c.added_on <= ?)")
228	                + " ORDER BY c.seq", rs -> {
229	                    List<PoolResponse.Member> list = new ArrayList<>();
230	                    // A lead no longer on the sheet (moved away) is left out: the crew's members share it all.
231	                    if (rs.getString(3) != null) {
232	                        list.add(new PoolResponse.Member(String.valueOf(rs.getLong(2)), null, rs.getString(3), "",
233	                                retired(rs.getLong(2), rs.getDate(4), retiredThen), true, ""));
234	                    }
235	                    people.put(rs.getString(1), list);
236	                }, args);
237	        jdbc.query("SELECT m.crew_name, m.person_id, p.name, p.retired_from FROM crew_member m"
238	                + " JOIN person p ON p.id = m.person_id AND p.sheet_id = m.sheet_id"
239	                + " WHERE m.sheet_id = ?" + (addedBy == null ? "" : " AND (m.added_on IS NULL OR m.added_on <= ?)")
240	                + " ORDER BY m.seq", rs -> {
241	                    List<PoolResponse.Member> list = people.get(rs.getString(1));
242	                    if (list != null) {
243	                        list.add(new PoolResponse.Member(String.valueOf(rs.getLong(2)), null, rs.getString(3), "",
244	                                retired(rs.getLong(2), rs.getDate(4), retiredThen), true, ""));
245	                    }
246	                }, args);
247	        people.forEach((name, list) -> {
248	            if (members.containsKey(name)) {
249	                return;
250	            }
251	            // A crew with no one left on the sheet is still a pool: it shares nothing.
252	            if (list.isEmpty()) {
253	                members.put(name, new ArrayList<>());
254	                crews.add(name);
255	                return;
256	            }
257	            BigDecimal each = FULL.divide(BigDecimal.valueOf(list.size()), 2, RoundingMode.HALF_EVEN);
258	            BigDecimal lead = FULL.subtract(each.multiply(BigDecimal.valueOf(list.size() - 1)));
259	            List<PoolResponse.Member> shared = new ArrayList<>();
260	            for (int i = 0; i < list.size(); i++) {
261	                PoolResponse.Member m = list.get(i);
262	                shared.add(new PoolResponse.Member(m.personId(), null, m.name(), (i == 0 ? lead : each).toPlainString(),
263	                        m.retired(), true, ""));
264	            }
265	            members.put(name, shared);
266	            crews.add(name);
267	        });
268	        return crews;
269	    }
