301	    /** Gives the pool's members their cuts of its pot, when it has one and is balanced, and passes each member pool's
302	     *  cut down to it as that pool's pot. */
303	    private static void share(String name, BigDecimal pot, Map<String, List<PoolResponse.Member>> members,
304	            Map<String, String> totals, Set<String> held, Map<String, List<PoolResponse.Member>> shown, int depth) {
305	        if (pot == null || depth > MAX_DEPTH || new BigDecimal(totals.get(name)).compareTo(FULL) != 0) {
306	            return;
307	        }
308	        List<PoolResponse.Member> withCuts = cuts(members.get(name), pot, held);
309	        shown.put(name, withCuts);
310	        for (PoolResponse.Member m : withCuts) {
311	            if (m.memberPool() != null && members.containsKey(m.memberPool()) && m.current()) {
312	                share(m.memberPool(), new BigDecimal(m.cut()), members, totals, held, shown, depth + 1);
313	            }
314	        }
315	    }
