317	    /** The members with their cuts of the pot: the pot times their share divided by the shares of the members with a
318	     *  cut added up, rounded half to even to two decimals (a retired member, or a person held on the sheet's today,
319	     *  cuts 0.00, their share spread over the others in proportion to theirs); the remainder, the pot minus the cuts added up, goes to the member with a cut with the smallest
320	     *  non-zero cut (the latest added on a tie; with no non-zero cut, the last member with a cut), so the cuts total exactly the pot. With no member left with a cut, each cuts 0.00 —
321	     *  unless every member is retired, when none has a cut ("").
322	     *  A member whose dates do not include the sheet's today has no cut at all (""). */
323	    static List<PoolResponse.Member> cuts(List<PoolResponse.Member> members, BigDecimal pot, Set<String> held) {
324	        BigDecimal[] cuts = new BigDecimal[members.size()];
325	        boolean[] cutting = new boolean[members.size()];
326	        BigDecimal shares = BigDecimal.ZERO;
327	        boolean allRetired = true;
328	        for (int i = 0; i < members.size(); i++) {
329	            PoolResponse.Member m = members.get(i);
330	            if (m.current() && !m.retired()) {
331	                allRetired = false;
332	            }
333	            cutting[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
334	            if (cutting[i]) {
335	                shares = shares.add(new BigDecimal(m.share()));
336	            }
337	        }
338	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
339	        int smallest = -1;
340	        int last = -1;
341	        for (int i = 0; i < members.size(); i++) {
342	            PoolResponse.Member m = members.get(i);
343	            BigDecimal share = new BigDecimal(m.share());
344	            cuts[i] = !m.current() || allRetired ? null : !cutting[i] || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
345	                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
346	            if (cuts[i] != null) {
347	                sum = sum.add(cuts[i]);
348	            }
349	            if (cutting[i]) {
350	                last = i;
351	                if (cuts[i].signum() != 0 && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
352	                    smallest = i;
353	                }
354	            }
355	        }
356	        int remainder = smallest >= 0 ? smallest : last;
357	        if (remainder >= 0 && shares.signum() != 0) {
358	            cuts[remainder] = cuts[remainder].add(pot.subtract(sum));
359	        }
360	        List<PoolResponse.Member> withCuts = new ArrayList<>();
361	        for (int i = 0; i < members.size(); i++) {
362	            PoolResponse.Member m = members.get(i);
363	            withCuts.add(new PoolResponse.Member(m.personId(), m.memberPool(), m.name(), m.share(), m.retired(), m.current(),
364	                    cuts[i] == null ? "" : cuts[i].toPlainString(), m.periodCuts()));
365	        }
366	        return withCuts;
367	    }
