137	    /** Each holder's parts of the shared claims that count for their own person ({@code in}), and what those parts take
138	     *  from that person ({@code out}), by person id. */
139	    public record SharedParts(Map<Long, BigDecimal> in, Map<Long, BigDecimal> out) {
140	    }
