149	    private SharedParts sharedParts(List<Claim> all, Map<Long, Person> byId, LocalDate today, LocalDate policyDate) {
150	        Map<Long, BigDecimal> partsIn = new LinkedHashMap<>();
151	        Map<Long, BigDecimal> partsOut = new LinkedHashMap<>();
152	        for (Claim claim : all) {
153	            Person owner = byId.get(claim.getPersonId());
154	            if (claim.getShares().isEmpty() || owner == null || !owner.countsClaimed(claim, today) || !owner.countsLive(claim, today)) {
155	                continue;
156	            }
157	            BigDecimal figure = due(claim, owner, today, policyDate);
158	            if (figure == null) {
159	                continue;
160	            }
161	            for (ClaimShare share : claim.getShares()) {
162	                if (!byId.containsKey(share.personId())) {
163	                    continue;
164	                }
165	                BigDecimal part = figure;
166	                if (claim.getSettledDue() != null) {
167	                    part = share.partOf(figure);
168	                } else {
169	                    // A holder whose grade has no rate holds 0.00: it takes nothing and gives them no figure.
170	                    BigDecimal rate = rates.find(claim, byId.get(share.personId()).gradeOn(claim.getDate()));
171	                    if (rate == null) {
172	                        continue;
173	                    }
174	                    part = share.partOf(claim, rate, Rounding.of(claim, policyDate, on -> settings.roundingMode(claim.getSheetId(), on)));
175	                }
176	                partsIn.merge(share.personId(), part, BigDecimal::add);
177	                partsOut.merge(owner.getId(), part, BigDecimal::add);
178	            }
179	        }
180	        return new SharedParts(partsIn, partsOut);
181	    }
