189	    /** A claim's due: fixed when settled; else the figure a statement bound it to, or its amount at the rate of its person's grade
190	     *  in force on its date, with its late charge (each 30-day boundary at the late percent in force on it) as of today on top,
191	     *  raised to the floor in force on its date. */
192	    private BigDecimal due(Claim claim, Person person, LocalDate today, LocalDate policyDate) {
193	        String sheetId = claim.getSheetId();
194	        RoundingMode rounding = Rounding.of(claim, policyDate, on -> settings.roundingMode(sheetId, on));
195	        BigDecimal fixed = ClaimResponse.fixedDue(claim);
196	        BigDecimal figure = fixed != null || claim.isBound() ? fixed
197	                : Rates.due(claim.getAmount(), rates.find(claim, person.gradeOn(claim.getDate())), rounding);
198	        return LateCharge.due(claim, figure, settings.floor(sheetId, claim.getDate()), on -> settings.latePct(sheetId, on), today, rounding,
199	                grace(claim, person));
200	    }
