    58	            for (LocalDate date : plan.dates(last)) {
    59	                if (plans.made(plan.id(), date)) continue;
    60	                LocalDate dueBy = holidays.dueBy(on, date, settings.termsOnCreation(on, person));
    61	                if (periods.isClosed(on, dueBy) || !person.allowsClaimOn(date)) continue;
    62	                Claim claim = claims.add(on, person.getId(), plan.amount(), date, "", null, dueBy, null);
    63	                plans.recordMade(plan.id(), date, claim.getId());
