    37	        if (!Settings.STEWARD.equals(settings.role(sheetId, user))) {
    38	            throw new ViewerRefusedException("Only a steward can clone the sheet");
    39	        }
    40	        if (to.isEmpty()) {
    41	            throw new InvalidCloneException("Name the sheet to clone to");
    42	        }
    43	        if (to.equals(sheetId) || sheets.exists(to)) {
    44	            throw new InvalidCloneException("The sheet " + to + " is already used");
    45	        }
    47	        Map<Long, Long> people = cloner.copy(sheetId, to);
    48	        // Every person and the totals are new on the clone.
    49	        RollupFigures before = new RollupFigures(new LinkedHashMap<>(), "", "", "");
    51	        List<Claim> copied = new ArrayList<>();
    52	        Map<Long, Long> newIds = new HashMap<>();
    53	        for (Map.Entry<Long, Long> person : people.entrySet()) {
    54	            List<Claim> theirs = new ArrayList<>(claims.ofPerson(sheetId, person.getKey()));
    55	            Collections.reverse(theirs); // oldest listed first, so they keep their order
    56	            for (Claim claim : theirs) {
    57	                newIds.put(claim.getId(), claims.cloneIn(claim, to, person.getValue()));
    58	                copied.add(claim);
    59	            }
    60	        }
