    63	        for (Claim claim : numbered) {
    64	            openedOn.put(claim.getId(), claims.openedOn(claim));
    65	        }
    66	        numbered.sort(Comparator.comparing((Claim c) -> openedOn.get(c.getId()), Comparator.nullsLast(Comparator.naturalOrder()))
    67	                .thenComparingLong(c -> newIds.get(c.getId())));
    68	        Map<String, String> renumbered = new HashMap<>();
    69	        Map<Long, String> numbers = new HashMap<>();
    70	        for (Claim claim : numbered) {
    71	            String number = numbering.next(to, claim.getDate());
    72	            renumbered.put(claim.getNumber(), number);
    73	            numbers.put(claim.getId(), number);
    74	        }
    75	        for (Claim claim : copied) {
    76	            claims.finishCloned(to, newIds.get(claim.getId()), numbers.get(claim.getId()),
    77	                    claim.getCorrects() == null ? null : renumbered.get(claim.getCorrects()),
    78	                    claim.getSplitFrom() == null ? null : renumbered.get(claim.getSplitFrom()));
    79	        }
