 81	            RoundingMode rounding, int grace) {
 82	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
 83	            return BigDecimal.ZERO.setScale(2);
 84	        }
 85	        return asOpen(claim, figure, pct, today, rounding, grace);
 86	    }
 87	
 88	    /** The charge the claim's figure would carry were it open, whatever its status; re-settling uses it. */
 89	    public static BigDecimal asOpen(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
 90	            RoundingMode rounding) {
 91	        return asOpen(claim, figure, pct, today, rounding, 0);
 92	    }
 93	
 94	    /** As {@link #asOpen(Claim, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
 95	    public static BigDecimal asOpen(Claim claim, BigDecimal figure, Function<LocalDate, BigDecimal> pct, LocalDate today,
 96	            RoundingMode rounding, int grace) {
 97	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
 98	        if (figure == null || claim.isCorrection() || claim.isWaived()) {
 99	            return charge;
100	        }
101	        LocalDate lateFrom = lateFrom(claim, grace);
102	        long overdue = ChronoUnit.DAYS.between(lateFrom, today);
103	        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
104	        for (long n = 1; n <= periods; n++) {
105	            BigDecimal rate = pct.apply(lateFrom.plusDays(n * PERIOD_DAYS));
106	            if (rate != null && rate.signum() != 0) {
107	                charge = charge.add(Rates.due(figure.add(charge), rate, rounding));
108	            }
109	        }
110	        return charge;
111	    }
