121	    /** As {@link #due(Claim, BigDecimal, BigDecimal, Function, LocalDate, RoundingMode)}, with the claim's grace days. */
122	    public static BigDecimal due(Claim claim, BigDecimal figure, BigDecimal floor, Function<LocalDate, BigDecimal> pct,
123	            LocalDate today, RoundingMode rounding, int grace) {
124	        if (figure == null || claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) {
125	            return figure;
126	        }
127	        BigDecimal base = floored(claim, figure, floor);
128	        return base.add(of(claim, base, pct, today, rounding, grace));
129	    }
