131	    /** The date a claim's lateness counts from: its due-by plus its grace days. */
132	    public static LocalDate lateFrom(Claim claim, int grace) {
133	        return claim.getDueBy() == null ? null : claim.getDueBy().plusDays(grace);
134	    }
135	
136	    /** A due raised to the floor; a correction has no floor. */
137	    public static BigDecimal floored(Claim claim, BigDecimal due, BigDecimal floor) {
138	        return due == null || floor == null || claim.isCorrection() || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
139	    }
